import { NextRequest, NextResponse } from "next/server";

type ApiScope = "validator:read" | "network:read" | "staking:read" | "staking:write" | "governance:read" | "governance:write";

interface ApiKey {
  id: string;
  name: string;
  key: string;
  scopes: ApiScope[];
  createdAt: string;
  status: "active" | "revoked";
  rateLimit: {
    current: number;
    limit: number;
  };
}

// In-memory storage (in production, use a database)
const apiKeys: ApiKey[] = [
  {
    id: "1",
    name: "Development Key",
    key: "lumina_dev123456789",
    scopes: ["validator:read", "network:read"],
    createdAt: new Date(Date.now() - 86400000 * 7).toISOString(),
    status: "active",
    rateLimit: { current: 450, limit: 1000 },
  },
];

// GET /api/v1/dev/api-keys - List all API keys
export async function GET() {
  return NextResponse.json({ keys: apiKeys });
}

// POST /api/v1/dev/api-keys - Create a new API key
export async function POST(request: NextRequest) {
  try {
    const body = await request.json();
    const { name, scopes } = body;

    if (!name || !scopes || !Array.isArray(scopes)) {
      return NextResponse.json(
        { error: "Name and scopes are required" },
        { status: 400 }
      );
    }

    const newKey: ApiKey = {
      id: Date.now().toString(),
      name,
      key: `lumina_${Math.random().toString(36).substring(2, 15)}${Math.random().toString(36).substring(2, 15)}`,
      scopes,
      createdAt: new Date().toISOString(),
      status: "active",
      rateLimit: { current: 0, limit: 1000 },
    };

    apiKeys.push(newKey);

    return NextResponse.json(newKey, { status: 201 });
  } catch (error) {
    return NextResponse.json(
      { error: "Invalid request body" },
      { status: 400 }
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

// In-memory storage for received webhooks (in production, use a database or message queue)
let receivedWebhooks: any[] = [];

// POST /api/v1/dev/webhook-test - Test endpoint for receiving webhooks
export async function POST(request: NextRequest) {
  try {
    const body = await request.json();
    const headers = Object.fromEntries(request.headers.entries());

    const webhookData = {
      id: Date.now().toString(),
      timestamp: new Date().toISOString(),
      headers,
      body,
      method: request.method,
      url: request.url,
    };

    receivedWebhooks.push(webhookData);

    // Keep only the last 50 webhooks to prevent memory issues
    if (receivedWebhooks.length > 50) {
      receivedWebhooks = receivedWebhooks.slice(-50);
    }

    return NextResponse.json({
      message: "Webhook received successfully",
      webhookId: webhookData.id,
    });
  } catch (error) {
    return NextResponse.json(
      { error: "Invalid request body" },
      { status: 400 }
    );
  }
}

// GET /api/v1/dev/webhook-test - Retrieve received webhooks
export async function GET() {
  return NextResponse.json({
    webhooks: receivedWebhooks,
    count: receivedWebhooks.length,
  });
}

"use client";

import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Modal } from "@/components/ui/modal";
import { Check } from "lucide-react";
import type { ApiScope } from "./api-key-list";

interface ApiKeyCreateProps {
  isOpen: boolean;
  onClose: () => void;
  onCreate: (name: string, scopes: ApiScope[]) => void;
}

const AVAILABLE_SCOPES: ApiScope[] = [
  "validator:read",
  "network:read",
  "staking:read",
  "staking:write",
  "governance:read",
  "governance:write",
];

export function ApiKeyCreate({ isOpen, onClose, onCreate }: ApiKeyCreateProps) {
  const [name, setName] = useState("");
  const [selectedScopes, setSelectedScopes] = useState<ApiScope[]>([]);
  const [createdKey, setCreatedKey] = useState<string | null>(null);

  const toggleScope = (scope: ApiScope) => {
    setSelectedScopes((prev) =>
      prev.includes(scope)
        ? prev.filter((s) => s !== scope)
        : [...prev, scope]
    );
  };

  const handleCreate = () => {
    if (!name.trim() || selectedScopes.length === 0) return;
    
    // Generate a mock API key (in production, this would come from the backend)
    const newKey = `lumina_${Math.random().toString(36).substring(2, 15)}${Math.random().toString(36).substring(2, 15)}`;
    setCreatedKey(newKey);
    onCreate(name, selectedScopes);
  };

  const handleClose = () => {
    setName("");
    setSelectedScopes([]);
    setCreatedKey(null);
    onClose();
  };

  const copyToClipboard = () => {
    if (createdKey) {
      navigator.clipboard.writeText(createdKey);
    }
  };

  return (
    <Modal isOpen={isOpen} onClose={handleClose} title="Create API Key">
      {createdKey ? (
        <div className="space-y-4">
          <div className="rounded-lg bg-green-50 p-4 dark:bg-green-900/20">
            <p className="text-sm font-medium text-green-900 dark:text-green-100">
              API Key Created Successfully
            </p>
            <p className="mt-2 text-xs text-green-700 dark:text-green-300">
              Copy this key now. You won't be able to see it again.
            </p>
          </div>
          <div className="space-y-2">
            <label className="text-sm font-medium text-zinc-900 dark:text-zinc-50">
              Your API Key
            </label>
            <div className="flex gap-2">
              <Input
                value={createdKey}
                readOnly
                className="font-mono text-sm"
              />
              <Button onClick={copyToClipboard}>Copy</Button>
            </div>
          </div>
          <div className="flex justify-end">
            <Button onClick={handleClose}>Done</Button>
          </div>
        </div>
      ) : (
        <div className="space-y-4">
          <div className="space-y-2">
            <label className="text-sm font-medium text-zinc-900 dark:text-zinc-50">
              Key Name
            </label>
            <Input
              placeholder="e.g., Production App"
              value={name}
              onChange={(e) => setName(e.target.value)}
            />
          </div>
          <div className="space-y-2">
            <label className="text-sm font-medium text-zinc-900 dark:text-zinc-50">
              Scopes
            </label>
            <div className="grid grid-cols-2 gap-2">
              {AVAILABLE_SCOPES.map((scope) => (
                <button
                  key={scope}
                  type="button"
                  onClick={() => toggleScope(scope)}
                  className={`flex items-center gap-2 rounded-md border px-3 py-2 text-sm text-left transition-colors ${
                    selectedScopes.includes(scope)
                      ? "border-zinc-900 bg-zinc-900 text-zinc-50 dark:border-zinc-50 dark:bg-zinc-50 dark:text-zinc-900"
                      : "border-zinc-200 bg-white text-zinc-700 hover:bg-zinc-50 dark:border-zinc-800 dark:bg-zinc-950 dark:text-zinc-300 dark:hover:bg-zinc-900"
                  }`}
                >
                  <div
                    className={`flex h-4 w-4 items-center justify-center rounded-sm ${
                      selectedScopes.includes(scope)
                        ? "bg-zinc-50 dark:bg-zinc-900"
                        : "border border-zinc-300 dark:border-zinc-700"
                    }`}
                  >
                    {selectedScopes.includes(scope) && (
                      <Check className="h-3 w-3 text-zinc-900 dark:text-zinc-50" />
                    )}
                  </div>
                  {scope}
                </button>
              ))}
            </div>
          </div>
          <div className="flex justify-end gap-2">
            <Button
              onClick={handleClose}
              className="bg-zinc-200 text-zinc-900 hover:bg-zinc-300 dark:bg-zinc-800 dark:text-zinc-50 dark:hover:bg-zinc-700"
            >
              Cancel
            </Button>
            <Button
              onClick={handleCreate}
              disabled={!name.trim() || selectedScopes.length === 0}
            >
              Create Key
            </Button>
          </div>
        </div>
      )}
    </Modal>
  );
}

"use client";

import { useState, useEffect } from "react";
import SwaggerUI from "swagger-ui-react";
import "swagger-ui-react/swagger-ui.css";

interface ApiPlaygroundProps {
  apiKey: string;
}

export function ApiPlayground({ apiKey }: ApiPlaygroundProps) {
  const [spec, setSpec] = useState<any>(null);

  useEffect(() => {
    // Mock OpenAPI spec - in production, this would be fetched from the API
    const mockSpec = {
      openapi: "3.0.0",
      info: {
        title: "Lumina API",
        version: "1.0.0",
        description: "API for interacting with the Lumina Network",
      },
      servers: [
        {
          url: "https://api.lumina.network/v1",
          description: "Production server",
        },
      ],
      components: {
        securitySchemes: {
          bearerAuth: {
            type: "http",
            scheme: "bearer",
            bearerFormat: "API Key",
          },
        },
      },
      security: [
        {
          bearerAuth: [],
        },
      ],
      paths: {
        "/validator/status": {
          get: {
            summary: "Get validator status",
            tags: ["Validator"],
            responses: {
              "200": {
                description: "Successful response",
                content: {
                  "application/json": {
                    example: {
                      status: "active",
                      uptime: "99.9%",
                      last_block: 12345678,
                    },
                  },
                },
              },
            },
          },
        },
        "/network/info": {
          get: {
            summary: "Get network information",
            tags: ["Network"],
            responses: {
              "200": {
                description: "Successful response",
                content: {
                  "application/json": {
                    example: {
                      network_id: "lumina-mainnet",
                      block_height: 12345678,
                      total_validators: 100,
                    },
                  },
                },
              },
            },
          },
        },
        "/staking/pools": {
          get: {
            summary: "List staking pools",
            tags: ["Staking"],
            responses: {
              "200": {
                description: "Successful response",
                content: {
                  "application/json": {
                    example: {
                      pools: [
                        {
                          id: "pool-1",
                          name: "Pool A",
                          apy: "5.5%",
                          total_staked: 1000000,
                        },
                      ],
                    },
                  },
                },
              },
            },
          },
        },
        "/staking/delegate": {
          post: {
            summary: "Delegate tokens to a pool",
            tags: ["Staking"],
            requestBody: {
              required: true,
              content: {
                "application/json": {
                  schema: {
                    type: "object",
                    properties: {
                      pool_id: { type: "string" },
                      amount: { type: "number" },
                    },
                  },
                },
              },
            },
            responses: {
              "200": {
                description: "Successful response",
              },
            },
          },
        },
        "/governance/proposals": {
          get: {
            summary: "List governance proposals",
            tags: ["Governance"],
            responses: {
              "200": {
                description: "Successful response",
                content: {
                  "application/json": {
                    example: {
                      proposals: [
                        {
                          id: "prop-1",
                          title: "Protocol Upgrade",
                          status: "active",
                          votes_for: 1000,
                          votes_against: 200,
                        },
                      ],
                    },
                  },
                },
              },
            },
          },
        },
      },
    };

    setSpec(mockSpec);
  }, []);

  if (!spec) {
    return (
      <div className="flex h-96 items-center justify-center text-zinc-500 dark:text-zinc-400">
        Loading API documentation...
      </div>
    );
  }

  return (
    <div className="rounded-lg border border-zinc-200 bg-white dark:border-zinc-800 dark:bg-zinc-950">
      <SwaggerUI
        spec={spec}
        requestInterceptor={(request) => {
          if (apiKey) {
            request.headers.Authorization = `Bearer ${apiKey}`;
          }
          return request;
        }}
        docExpansion="list"
        defaultModelsExpandDepth={1}
        persistAuthorization={true}
      />
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { RefreshCw, Clock, CheckCircle } from "lucide-react";
import { format } from "date-fns";

interface WebhookData {
  id: string;
  timestamp: string;
  headers: Record<string, string>;
  body: any;
  method: string;
  url: string;
}

export function WebhookTester() {
  const [webhooks, setWebhooks] = useState<WebhookData[]>([]);
  const [isLoading, setIsLoading] = useState(false);

  const fetchWebhooks = async () => {
    setIsLoading(true);
    try {
      const response = await fetch("/api/v1/dev/webhook-test");
      const data = await response.json();
      setWebhooks(data.webhooks || []);
    } catch (error) {
      console.error("Failed to fetch webhooks:", error);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchWebhooks();
    // Poll for new webhooks every 5 seconds
    const interval = setInterval(fetchWebhooks, 5000);
    return () => clearInterval(interval);
  }, []);

  const clearWebhooks = async () => {
    try {
      await fetch("/api/v1/dev/webhook-test", { method: "DELETE" });
      setWebhooks([]);
    } catch (error) {
      console.error("Failed to clear webhooks:", error);
    }
  };

  return (
    <Card>
      <CardHeader>
        <div className="flex items-center justify-between">
          <CardTitle>Webhook Test Endpoint</CardTitle>
          <div className="flex gap-2">
            <Button
              onClick={fetchWebhooks}
              disabled={isLoading}
              className="h-8"
            >
              <RefreshCw className={`h-4 w-4 ${isLoading ? "animate-spin" : ""}`} />
            </Button>
            {webhooks.length > 0 && (
              <Button
                onClick={clearWebhooks}
                className="h-8 bg-red-600 hover:bg-red-700 text-white"
              >
                Clear
              </Button>
            )}
          </div>
        </div>
        <p className="text-sm text-zinc-500 dark:text-zinc-400">
          Send POST requests to{" "}
          <code className="rounded bg-zinc-100 px-1 py-0.5 dark:bg-zinc-800">
            /api/v1/dev/webhook-test
          </code>{" "}
          to test webhooks. Webhooks are displayed in real-time.
        </p>
      </CardHeader>
      <CardContent>
        {webhooks.length === 0 ? (
          <div className="flex h-32 items-center justify-center text-zinc-500 dark:text-zinc-400">
            <div className="text-center">
              <CheckCircle className="mx-auto h-12 w-12 mb-2 opacity-50" />
              <p>No webhooks received yet</p>
            </div>
          </div>
        ) : (
          <div className="space-y-4 max-h-96 overflow-y-auto">
            {webhooks.map((webhook) => (
              <div
                key={webhook.id}
                className="rounded-lg border border-zinc-200 bg-zinc-50 p-4 dark:border-zinc-800 dark:bg-zinc-900"
              >
                <div className="mb-2 flex items-center gap-2 text-sm text-zinc-500 dark:text-zinc-400">
                  <Clock className="h-4 w-4" />
                  {format(new Date(webhook.timestamp), "MMM d, yyyy HH:mm:ss")}
                </div>
                <div className="space-y-2">
                  <div>
                    <span className="text-xs font-medium text-zinc-500 dark:text-zinc-400">
                      Method:
                    </span>{" "}
                    <span className="text-sm font-mono text-zinc-900 dark:text-zinc-50">
                      {webhook.method}
                    </span>
                  </div>
                  <div>
                    <span className="text-xs font-medium text-zinc-500 dark:text-zinc-400">
                      Body:
                    </span>
                    <pre className="mt-1 rounded bg-zinc-100 p-2 text-xs dark:bg-zinc-800">
                      {JSON.stringify(webhook.body, null, 2)}
                    </pre>
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
      </CardContent>
    </Card>
  );
}

import { cn } from "@/lib/utils";
import { ButtonHTMLAttributes, forwardRef } from "react";

const Button = forwardRef<HTMLButtonElement, ButtonHTMLAttributes<HTMLButtonElement> & { variant?: string; size?: string }>(
  ({ className, variant, size, ...props }, ref) => {
    return (
      <button
        ref={ref}
        className={cn(
          "inline-flex items-center justify-center rounded-md text-sm font-medium transition-colors",
          "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-offset-2",
          "disabled:pointer-events-none disabled:opacity-50",
          "bg-zinc-900 text-zinc-50 hover:bg-zinc-800",
          "dark:bg-zinc-50 dark:text-zinc-900 dark:hover:bg-zinc-200",
          "h-10 px-4 py-2",
          className
        )}
        {...props}
      />
    );
  }
);
Button.displayName = "Button";

export { Button };

#!/usr/bin/env node

const pairs = [
  { fg: "#000000", bg: "#ffffff", name: "text on bg (solar)", required: 10 },
  { fg: "#1a1a1a", bg: "#ffffff", name: "text-secondary on bg (solar)", required: 10 },
  { fg: "#2a2a2a", bg: "#ffffff", name: "text-tertiary on bg (solar)", required: 10 },
  { fg: "#0020b3", bg: "#ffffff", name: "primary on bg (solar)", required: 10 },
  { fg: "#001999", bg: "#ffffff", name: "primary-hover on bg (solar)", required: 10 },
  { fg: "#ffffff", bg: "#0020b3", name: "primary-text on primary (solar)", required: 10 },
  { fg: "#004d00", bg: "#ffffff", name: "secondary on bg (solar)", required: 10 },
  { fg: "#8b0000", bg: "#ffffff", name: "danger on bg (solar)", required: 10 },
  { fg: "#8b0000", bg: "#ffffff", name: "danger-text on bg (solar)", required: 10 },
  { fg: "#4a3a00", bg: "#ffffff", name: "warning on bg (solar)", required: 10 },
  { fg: "#3a2e00", bg: "#ffffff", name: "warning-fill on bg (solar)", required: 10 },
  { fg: "#000000", bg: "#f5f5f5", name: "text on surface (solar)", required: 10 },
  { fg: "#001999", bg: "#e0e8ff", name: "tag-text on tag-bg (solar)", required: 10 },
  { fg: "#ffffff", bg: "#000000", name: "nav-text on nav-bg (solar)", required: 10 },
  { fg: "#000000", bg: "#ffffff", name: "focus-ring on bg (solar)", required: 12 },
  { fg: "#171717", bg: "#ffffff", name: "text on bg (light)", required: 0 },
  { fg: "#6f5f48", bg: "#f7f4ee", name: "text-secondary on bg (light)", required: 0 },
  { fg: "#0f766e", bg: "#f7f4ee", name: "primary on bg (light)", required: 0 },
  { fg: "#ffffff", bg: "#0f766e", name: "primary-text on primary (light)", required: 0 },
  { fg: "#ededed", bg: "#0a0a0a", name: "text on bg (dark)", required: 0 },
  { fg: "#2dd4bf", bg: "#0a0a0a", name: "primary on bg (dark)", required: 0 },
  { fg: "#0a0a0a", bg: "#2dd4bf", name: "primary-text on primary (dark)", required: 0 },
];

function hexToRgb(hex) {
  const h = hex.replace("#", "");
  return {
    r: parseInt(h.substring(0, 2), 16) / 255,
    g: parseInt(h.substring(2, 4), 16) / 255,
    b: parseInt(h.substring(4, 6), 16) / 255,
  };
}

function srgb(c) {
  return c <= 0.04045 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4);
}

function relativeLuminance(hex) {
  const { r, g, b } = hexToRgb(hex);
  return 0.2126 * srgb(r) + 0.7152 * srgb(g) + 0.0722 * srgb(b);
}

function contrastRatio(hex1, hex2) {
  const l1 = relativeLuminance(hex1);
  const l2 = relativeLuminance(hex2);
  const lighter = Math.max(l1, l2);
  const darker = Math.min(l1, l2);
  return (lighter + 0.05) / (darker + 0.05);
}

let failures = 0;

for (const { fg, bg, name, required } of pairs) {
  const ratio = contrastRatio(fg, bg);
  const passesText = ratio >= 10.0;
  const passesAAA = ratio >= 7.0;
  const meetsRequired = required === 0 || ratio >= required;

  let status;
  if (required === 0) {
    status = "INFO";
  } else if (meetsRequired) {
    status = "PASS";
  } else {
    status = "FAIL";
  }

  if (required > 0 && !meetsRequired) failures++;
  console.log(
    `${status.padEnd(8)} ${ratio.toFixed(2).padStart(5)}:1  ${name}  (${fg} on ${bg})`,
  );
}

console.log(`\n---`);
if (failures === 0) {
  console.log(`All required contrast pairs meet minimum thresholds.`);
} else {
  console.log(`${failures} pair(s) below required threshold.`);
  process.exitCode = 1;
}

/// <reference lib="webworker" />
import { defaultCache } from "@serwist/next/worker";
import type { PrecacheEntry, SerwistGlobalConfig } from "serwist";
import {
  CacheFirst,
  ExpirationPlugin,
  NetworkFirst,
  Serwist,
} from "serwist";

interface FilePickerAcceptType {
  description?: string;
  accept: Record<string, string[]>;
}

interface SaveFilePickerOptions {
  suggestedName?: string;
  types?: FilePickerAcceptType[];
  excludeAcceptAllOption?: boolean;
  id?: string;
  startIn?: FileSystemHandle | string;
}

interface FileSystemHandlePermissionDescriptor {
  name: 'file' | 'directory';
  mode?: 'read' | 'readwrite';
}

interface FileSystemCreateWritableOptions {
  keepExistingData?: boolean;
}

interface FileSystemWritableFileStream extends WritableStream {
  write(data: any): Promise<void>;
  seek(position: number): Promise<void>;
  truncate(size: number): Promise<void>;
  close(): Promise<void>;
}

interface FileSystemFileHandle extends FileSystemHandle {
  getFile(): Promise<File>;
  createWritable(options?: FileSystemCreateWritableOptions): Promise<FileSystemWritableFileStream>;
}

declare global {
  interface WorkerGlobalScope extends SerwistGlobalConfig {
    __SW_MANIFEST: (PrecacheEntry | string)[] | undefined;
  }
}

declare const self: ServiceWorkerGlobalScope &
  SerwistGlobalConfig & {
    __SW_MANIFEST: (PrecacheEntry | string)[] | undefined;
  };

const serwist = new Serwist({
  precacheEntries: self.__SW_MANIFEST,
  skipWaiting: true,
  clientsClaim: true,
  navigationPreload: true,
  fallbacks: {
    entries: [
      {
        url: "/offline",
        matcher({ request }) {
          return request.destination === "document";
        },
      },
    ],
  },
  runtimeCaching: [
    {
      matcher: ({ url }) => url.pathname.startsWith("/api/telemetry/"),
      handler: new NetworkFirst({
        cacheName: "lumina-telemetry",
        networkTimeoutSeconds: 5,
        plugins: [
          {
            cacheWillUpdate: async ({ response }) => {
              if (response && response.status === 200) {
                return response;
              }
              return null;
            },
          },
        ],
      }),
    },
    {
      matcher: ({ url }) => url.pathname.startsWith("/api/"),
      handler: new NetworkFirst({
        cacheName: "lumina-api",
        networkTimeoutSeconds: 4,
        plugins: [
          new ExpirationPlugin({
            maxEntries: 32,
            maxAgeSeconds: 60 * 60 * 24,
            purgeOnQuotaError: true,
          }),
        ],
      }),
    },
    {
      matcher: ({ url }) =>
        url.pathname.startsWith("/icons/") ||
        url.pathname.startsWith("/favicon"),
      handler: new CacheFirst({
        cacheName: "lumina-icons",
        plugins: [
          new ExpirationPlugin({
            maxEntries: 32,
            maxAgeSeconds: 60 * 60 * 24 * 30,
            purgeOnQuotaError: true,
          }),
        ],
      }),
    },
    ...defaultCache,
  ],
});

serwist.addEventListeners();

let activeFileStream: FileSystemWritableFileStream | null = null;
let abortController: AbortController | null = null;

self.addEventListener('fetch', (event) => {
  const { request } = event;
  
  if (request.headers.get('X-Stream-Export') === 'true') {
    event.respondWith(handleStreamExport(request, event.clientId));
  }
});

self.addEventListener('message', async (event) => {
  const { type } = event.data;
  
  if (type === 'abort-export') {
    if (abortController) {
      abortController.abort();
    }
    if (activeFileStream) {
      try {
        await activeFileStream.abort();
      } catch (e) {
        console.error('Error aborting file stream:', e);
      }
    }
  }
});

async function handleStreamExport(request: Request, clientId: string) {
  try {
    abortController = new AbortController();
    const response = await fetch(request, { signal: abortController.signal });
    
    if (!response.ok) {
      return new Response('Export failed', { status: response.status });
    }

    const contentEncoding = response.headers.get('Content-Encoding');
    let readableStream = response.body;
    
    if (contentEncoding === 'gzip' && readableStream) {
      const decompressionStream = new DecompressionStream('gzip');
      readableStream = readableStream.pipeThrough(decompressionStream);
    }

    const client = await self.clients.get(clientId);
    if (!client) {
      return new Response('Client not found', { status: 400 });
    }

    const messageChannel = new MessageChannel();
    const { port1, port2 } = messageChannel;
    const CHUNK_SIZE = 64 * 1024;
    const PROGRESS_THRESHOLD = 1024 * 1024;
    
    let bytesReceived = 0;
    let bytesWritten = 0;
    let buffer = new Uint8Array(0);
    let lastProgressEmittedAt = 0;

    port2.onmessage = async (msg) => {
      if (msg.data.type === 'init-file-stream' && msg.data.fileHandle) {
        activeFileStream = await msg.data.fileHandle.createWritable();
        
        const reader = readableStream?.getReader();
        if (!reader) return;

        try {
          while (true) {
            const { done, value } = await reader.read();
            
            if (done) {
              if (buffer.length > 0 && activeFileStream) {
                await activeFileStream.write(buffer);
                bytesWritten += buffer.length;
              }
              if (activeFileStream) {
                await activeFileStream.close();
              }
              client.postMessage({ type: 'export-complete', bytesWritten });
              break;
            }

            if (value) {
              bytesReceived += value.length;
              
              const newBuffer = new Uint8Array(buffer.length + value.length);
              newBuffer.set(buffer);
              newBuffer.set(value, buffer.length);
              buffer = newBuffer;
              
              while (buffer.length >= CHUNK_SIZE && activeFileStream) {
                const chunk = buffer.slice(0, CHUNK_SIZE);
                await activeFileStream.write(chunk);
                bytesWritten += CHUNK_SIZE;
                buffer = buffer.slice(CHUNK_SIZE);
              }
              
              if (bytesReceived - lastProgressEmittedAt >= PROGRESS_THRESHOLD) {
                client.postMessage({ 
                  type: 'progress', 
                  bytesReceived, 
                  bytesWritten 
                });
                lastProgressEmittedAt = bytesReceived;
              }
            }
          }
        } catch (error) {
          if (error instanceof Error && error.name === 'AbortError') {
            client.postMessage({ type: 'export-aborted' });
          } else {
            client.postMessage({ type: 'export-error', error });
          }
        }
      }
    };

    client.postMessage({ type: 'request-file-handle' }, [port1]);
    
    return new Response('Export initiated', { status: 200 });
  } catch (error) {
    console.error('Stream export error:', error);
    return new Response('Export failed', { status: 500 });
  }
}

