"use client";

import { useBackupRestore } from "@/src/hooks/useBackupRestore";

export function BackupDashboard() {
  const {
    backups,
    lastBackup,
    lastEvent,
    isCreating,
    isRestoring,
    scheduleConfig,
    createBackup,
    downloadBackup,
    uploadAndRestore,
    updateSchedule,
    deleteBackup,
    refreshBackups,
  } = useBackupRestore();

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    await uploadAndRestore(file);
    e.target.value = "";
  };

  const handleScheduleToggle = () => {
    updateSchedule({
      ...scheduleConfig,
      enabled: !scheduleConfig.enabled,
    });
  };

  return (
    <div className="space-y-6">
      {/* Status Header */}
      <div className="rounded-lg border border-neutral-800 bg-neutral-900/50 p-4">
        <div className="flex items-center justify-between">
          <h2 className="text-lg font-semibold text-neutral-100">
            Database Backup & Restore
          </h2>
          <span className={`inline-flex items-center gap-1.5 rounded-full px-3 py-1 text-xs font-medium ${
            scheduleConfig.enabled
              ? "bg-emerald-900/50 text-emerald-400"
              : "bg-neutral-800 text-neutral-400"
          }`}>
            <span className={`h-1.5 w-1.5 rounded-full ${
              scheduleConfig.enabled ? "bg-emerald-400" : "bg-neutral-500"
            }`} />
            {scheduleConfig.enabled ? "Scheduled" : "Manual Only"}
          </span>
        </div>

        <div className="mt-3 grid grid-cols-3 gap-4 text-sm">
          <div>
            <span className="text-neutral-500">Backups</span>
            <p className="mt-0.5 font-mono text-neutral-200">{backups.length}</p>
          </div>
          <div>
            <span className="text-neutral-500">Last Backup</span>
            <p className="mt-0.5 font-mono text-neutral-200">
              {lastBackup
                ? new Date(lastBackup.createdAt).toLocaleString()
                : "Never"}
            </p>
          </div>
          <div>
            <span className="text-neutral-500">Last Event</span>
            <p className="mt-0.5 font-mono text-neutral-200">
              {lastEvent
                ? `${lastEvent.type.replace("-", " ")} ${lastEvent.durationMs ? `(${lastEvent.durationMs}ms)` : ""}`
                : "None"}
            </p>
          </div>
        </div>
      </div>

      {/* Actions */}
      <div className="flex flex-wrap gap-3">
        <button
          onClick={() => downloadBackup()}
          disabled={isCreating}
          className="inline-flex items-center gap-2 rounded-lg bg-emerald-600 px-4 py-2 text-sm font-medium text-white hover:bg-emerald-500 disabled:opacity-50"
        >
          {isCreating ? "Creating..." : "Download Backup"}
        </button>

        <button
          onClick={() => createBackup()}
          disabled={isCreating}
          className="inline-flex items-center gap-2 rounded-lg bg-neutral-700 px-4 py-2 text-sm font-medium text-neutral-200 hover:bg-neutral-600 disabled:opacity-50"
        >
          {isCreating ? "Creating..." : "Create Backup"}
        </button>

        <label className="inline-flex cursor-pointer items-center gap-2 rounded-lg bg-neutral-700 px-4 py-2 text-sm font-medium text-neutral-200 hover:bg-neutral-600">
          <input
            type="file"
            accept=".json"
            onChange={handleFileUpload}
            className="hidden"
            disabled={isRestoring}
          />
          {isRestoring ? "Restoring..." : "Restore Backup"}
        </label>
      </div>

      {/* Schedule Controls */}
      <div className="rounded-lg border border-neutral-800 bg-neutral-900/50 p-4">
        <div className="flex items-center justify-between">
          <h3 className="text-sm font-semibold text-neutral-200">
            Backup Schedule
          </h3>
          <button
            onClick={handleScheduleToggle}
            className={`relative inline-flex h-5 w-9 items-center rounded-full transition-colors ${
              scheduleConfig.enabled ? "bg-emerald-600" : "bg-neutral-700"
            }`}
          >
            <span className={`inline-block h-3.5 w-3.5 transform rounded-full bg-white transition-transform ${
              scheduleConfig.enabled ? "translate-x-4.5" : "translate-x-1"
            }`} />
          </button>
        </div>

        {scheduleConfig.enabled && (
          <div className="mt-3 grid grid-cols-3 gap-3">
            <div>
              <label className="block text-xs text-neutral-500">Frequency</label>
              <select
                value={scheduleConfig.frequency}
                onChange={(e) =>
                  updateSchedule({
                    ...scheduleConfig,
                    frequency: e.target.value as any,
                  })
                }
                className="mt-1 w-full rounded border border-neutral-700 bg-neutral-800 px-2 py-1.5 text-sm text-neutral-200"
              >
                <option value="hourly">Hourly</option>
                <option value="daily">Daily</option>
                <option value="weekly">Weekly</option>
                <option value="manual">Manual</option>
              </select>
            </div>
            <div>
              <label className="block text-xs text-neutral-500">Time</label>
              <input
                type="time"
                value={scheduleConfig.timeOfDay ?? "02:00"}
                onChange={(e) =>
                  updateSchedule({
                    ...scheduleConfig,
                    timeOfDay: e.target.value,
                  })
                }
                className="mt-1 w-full rounded border border-neutral-700 bg-neutral-800 px-2 py-1.5 text-sm text-neutral-200"
              />
            </div>
            <div>
              <label className="block text-xs text-neutral-500">Keep</label>
              <input
                type="number"
                min={1}
                value={scheduleConfig.retentionCount}
                onChange={(e) =>
                  updateSchedule({
                    ...scheduleConfig,
                    retentionCount: parseInt(e.target.value) || 7,
                  })
                }
                className="mt-1 w-full rounded border border-neutral-700 bg-neutral-800 px-2 py-1.5 text-sm text-neutral-200"
              />
            </div>
          </div>
        )}
      </div>

      {/* Backup History */}
      <div className="rounded-lg border border-neutral-800 bg-neutral-900/50 p-4">
        <div className="flex items-center justify-between">
          <h3 className="text-sm font-semibold text-neutral-200">
            Backup History
          </h3>
          <button
            onClick={() => refreshBackups()}
            className="text-xs text-neutral-500 hover:text-neutral-300"
          >
            Refresh
          </button>
        </div>

        {backups.length === 0 ? (
          <p className="mt-3 text-sm text-neutral-500">
            No backups yet. Create your first backup above.
          </p>
        ) : (
          <div className="mt-3 overflow-x-auto">
            <table className="w-full text-sm">
              <thead>
                <tr className="border-b border-neutral-800 text-left text-neutral-500">
                  <th className="pb-2 pr-4 font-medium">Date</th>
                  <th className="pb-2 pr-4 font-medium">Records</th>
                  <th className="pb-2 pr-4 font-medium">Size</th>
                  <th className="pb-2 pr-4 font-medium">Channel</th>
                  <th className="pb-2 font-medium" />
                </tr>
              </thead>
              <tbody>
                {backups.map((b) => (
                  <tr
                    key={b.id}
                    className="border-b border-neutral-800/50 text-neutral-300"
                  >
                    <td className="py-2 pr-4 font-mono text-xs">
                      {new Date(b.createdAt).toLocaleString()}
                    </td>
                    <td className="py-2 pr-4 font-mono text-xs">
                      {b.recordCount.toLocaleString()}
                    </td>
                    <td className="py-2 pr-4 font-mono text-xs">
                      {formatBytes(b.totalSizeBytes)}
                    </td>
                    <td className="py-2 pr-4 text-xs">{b.deployChannel}</td>
                    <td className="py-2 text-right">
                      <button
                        onClick={() => deleteBackup(b.id)}
                        className="text-xs text-red-400 hover:text-red-300"
                      >
                        Delete
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
}

function formatBytes(bytes: number): string {
  if (bytes === 0) return "0 B";
  const k = 1024;
  const sizes = ["B", "KB", "MB", "GB"];
  const i = Math.floor(Math.log(bytes) / Math.log(k));
  return `${parseFloat((bytes / Math.pow(k, i)).toFixed(1))} ${sizes[i]}`;
}

"use client";

import { useState } from "react";
import { useBackupRestore } from "@/src/hooks/useBackupRestore";

interface RestoreStep {
  id: "select" | "verify" | "confirm" | "result";
  label: string;
}

const STEPS: RestoreStep[] = [
  { id: "select", label: "Select File" },
  { id: "verify", label: "Verify" },
  { id: "confirm", label: "Confirm" },
  { id: "result", label: "Result" },
];

export function RestoreWizard() {
  const { uploadAndRestore, runRestoreTest } = useBackupRestore();
  const [step, setStep] = useState<RestoreStep["id"]>("select");
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const [verifyResult, setVerifyResult] = useState<any>(null);
  const [restoreResult, setRestoreResult] = useState<any>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setSelectedFile(file);
    setError(null);
    setIsProcessing(true);

    try {
      const text = await file.text();
      const backup = JSON.parse(text);
      const result = await runRestoreTest(backup);
      setVerifyResult(result);
      if (result.ok) {
        setStep("verify");
      } else {
        setError(result.error ?? "Verification failed");
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "Invalid backup file");
    } finally {
      setIsProcessing(false);
    }
  };

  const handleConfirm = async () => {
    if (!selectedFile) return;
    setIsProcessing(true);
    setError(null);

    try {
      const text = await selectedFile.text();
      const backup = JSON.parse(text);
      const result = await uploadAndRestore(selectedFile, false);
      setRestoreResult(result);
      if (result?.ok) {
        setStep("result");
      } else {
        setError(result?.error ?? "Restore failed");
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "Restore failed");
    } finally {
      setIsProcessing(false);
    }
  };

  const handleReset = () => {
    setStep("select");
    setSelectedFile(null);
    setVerifyResult(null);
    setRestoreResult(null);
    setError(null);
  };

  const currentStepIndex = STEPS.findIndex((s) => s.id === step);

  return (
    <div className="rounded-lg border border-neutral-800 bg-neutral-900/50 p-4">
      {/* Step Indicator */}
      <div className="mb-6 flex items-center gap-2">
        {STEPS.map((s, i) => (
          <div key={s.id} className="flex items-center gap-2">
            <span className={`flex h-6 w-6 items-center justify-center rounded-full text-xs font-medium ${
              i <= currentStepIndex
                ? "bg-emerald-600 text-white"
                : "bg-neutral-800 text-neutral-500"
            }`}>
              {i + 1}
            </span>
            <span className={`text-xs ${
              i <= currentStepIndex ? "text-neutral-200" : "text-neutral-600"
            }`}>
              {s.label}
            </span>
            {i < STEPS.length - 1 && (
              <span className="text-neutral-700">→</span>
            )}
          </div>
        ))}
      </div>

      {/* Step Content */}
      {step === "select" && (
        <div>
          <p className="mb-3 text-sm text-neutral-400">
            Select a backup JSON file to restore. The file will be verified
            before any data is written.
          </p>
          <label className="inline-flex cursor-pointer items-center gap-2 rounded-lg bg-neutral-700 px-4 py-2 text-sm font-medium text-neutral-200 hover:bg-neutral-600">
            <input
              type="file"
              accept=".json"
              onChange={handleFileSelect}
              className="hidden"
              disabled={isProcessing}
            />
            {isProcessing ? "Verifying..." : "Choose Backup File"}
          </label>
          {error && (
            <p className="mt-3 text-sm text-red-400">{error}</p>
          )}
        </div>
      )}

      {step === "verify" && verifyResult && (
        <div>
          {verifyResult.ok ? (
            <div className="mb-4 rounded-lg bg-emerald-900/20 p-3">
              <p className="text-sm font-medium text-emerald-400">
                Backup Verified Successfully
              </p>
              <p className="mt-1 text-xs text-neutral-400">
                {verifyResult.totalRecordsRestored} records across{" "}
                {verifyResult.storesAttempted} stores will be restored.
              </p>
            </div>
          ) : (
            <div className="mb-4 rounded-lg bg-red-900/20 p-3">
              <p className="text-sm font-medium text-red-400">
                Verification Failed
              </p>
              <p className="mt-1 text-xs text-neutral-400">
                {verifyResult.error}
              </p>
            </div>
          )}

          <div className="flex gap-3">
            {verifyResult.ok && (
              <button
                onClick={handleConfirm}
                disabled={isProcessing}
                className="rounded-lg bg-amber-600 px-4 py-2 text-sm font-medium text-white hover:bg-amber-500 disabled:opacity-50"
              >
                {isProcessing ? "Restoring..." : "Proceed with Restore"}
              </button>
            )}
            <button
              onClick={handleReset}
              className="rounded-lg bg-neutral-700 px-4 py-2 text-sm font-medium text-neutral-200 hover:bg-neutral-600"
            >
              Cancel
            </button>
          </div>

          {error && (
            <p className="mt-3 text-sm text-red-400">{error}</p>
          )}
        </div>
      )}

      {step === "confirm" && (
        <div>
          <p className="mb-3 text-sm text-neutral-400">
            Restore in progress...
          </p>
          <div className="h-1 w-full overflow-hidden rounded bg-neutral-800">
            <div className="h-full w-1/2 animate-pulse rounded bg-emerald-600" />
          </div>
        </div>
      )}

      {step === "result" && restoreResult && (
        <div>
          {restoreResult.ok ? (
            <div className="mb-4 rounded-lg bg-emerald-900/20 p-3">
              <p className="text-sm font-medium text-emerald-400">
                Restore Completed Successfully
              </p>
              <p className="mt-1 text-xs text-neutral-400">
                {restoreResult.totalRecordsRestored} records restored across{" "}
                {restoreResult.storesSucceeded} stores in{" "}
                {restoreResult.durationMs}ms.
              </p>
            </div>
          ) : (
            <div className="mb-4 rounded-lg bg-red-900/20 p-3">
              <p className="text-sm font-medium text-red-400">
                Restore Failed
              </p>
              <p className="mt-1 text-xs text-neutral-400">
                {restoreResult.error ?? "Unknown error"}
              </p>
            </div>
          )}

          <button
            onClick={handleReset}
            className="rounded-lg bg-neutral-700 px-4 py-2 text-sm font-medium text-neutral-200 hover:bg-neutral-600"
          >
            Start New Restore
          </button>
        </div>
      )}
    </div>
  );
}

/**
 * ThroughputChart - High-performance throughput visualization
 * 
 * Features:
 * - Handles 200+ messages/second without frame drops
 * - Throttled rendering at 500ms intervals
 * - Fixed 200-point sliding window
 * - Zero message loss
 * - Performance monitoring
 * - Automatic cleanup on unmount
 */

'use client'

import { useCallback, useEffect, useMemo, useRef } from 'react'
import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  Legend,
} from 'recharts'
import { useWebSocket } from '@/src/hooks/useWebSocket'
import { useDataThrottle } from '@/src/hooks/useDataThrottle'
import { SlidingWindow } from '@/src/lib/slidingWindow'

interface PacketMessage {
  timestamp: number
  packetsForwarded: number
  throughput: number
  nodeId?: string
}

interface ChartDataPoint {
  timestamp: number
  value: number  // Required by SlidingWindow DataPoint interface
  throughput: number
  time: string
}

export interface ThroughputChartProps {
  /** WebSocket URL for packet stream */
  wsUrl: string
  /** Chart title */
  title?: string
  /** Chart height in pixels */
  height?: number
  /** Enable performance monitoring */
  enablePerformanceTracking?: boolean
  /** Color scheme */
  lineColor?: string
  gridColor?: string
}

export function ThroughputChart({
  wsUrl,
  title = 'Network Throughput',
  height = 400,
  enablePerformanceTracking = false,
  lineColor,
  gridColor,
}: ThroughputChartProps) {
  const chartColors = useMemo(() => {
    if (typeof window === 'undefined') return { text: '#6f5f48', border: '#d8d0c1', surface: '#ffffff', grid: '#e5e7eb' }
    const s = getComputedStyle(document.documentElement)
    return {
      text: s.getPropertyValue('--color-chart-text').trim(),
      border: s.getPropertyValue('--color-chart-border').trim(),
      surface: s.getPropertyValue('--color-surface').trim(),
      grid: s.getPropertyValue('--color-chart-grid').trim(),
    }
  }, [])

  // Sliding window to maintain max 200 data points
  const slidingWindowRef = useRef(
    new SlidingWindow<ChartDataPoint>(200)
  )

  // Performance tracking
  const renderCountRef = useRef(0)
  const messageCountRef = useRef(0)
  const lastLogTimeRef = useRef(Date.now())

  // Throttle incoming messages to max one render per 500ms
  const { data: throttledMessages, push, metrics } = useDataThrottle<PacketMessage>({
    intervalMs: 500,
    maxBufferSize: 1000,
    enablePerformanceTracking,
  })

  // WebSocket message handler
  const handleWebSocketMessage = useCallback((message: PacketMessage) => {
    messageCountRef.current++
    push(message)
  }, [push])

  // For demo/testing: listen to mock WebSocket events
  useEffect(() => {
    const handleMockMessage = (e: Event) => {
      const customEvent = e as CustomEvent<PacketMessage>
      handleWebSocketMessage(customEvent.detail)
    }

    window.addEventListener('mock-ws-message', handleMockMessage)
    return () => {
      window.removeEventListener('mock-ws-message', handleMockMessage)
    }
  }, [handleWebSocketMessage])

  // Connect to WebSocket (skip if using mock)
  const useMock = typeof window !== 'undefined' && wsUrl.includes('localhost:8080')
  const wsConfig = useMock 
    ? { url: 'ws://mock', reconnect: false }
    : { url: wsUrl, reconnect: true, maxReconnectAttempts: 5, reconnectDelayMs: 2000 }
  
  const { state: wsState, error } = useWebSocket<PacketMessage>(
    wsConfig,
    useMock ? () => {} : handleWebSocketMessage
  )

  // Override state for mock mode
  const state = useMock ? 'connected' : wsState

  // Process throttled messages and update sliding window
  useEffect(() => {
    if (throttledMessages.length === 0) return

    // Add all messages to sliding window
    throttledMessages.forEach((msg) => {
      const dataPoint: ChartDataPoint = {
        timestamp: msg.timestamp,
        value: msg.throughput,  // value field for DataPoint interface
        throughput: msg.throughput,
        time: new Date(msg.timestamp).toLocaleTimeString(),
      }
      slidingWindowRef.current.push(dataPoint)
    })

    renderCountRef.current++

    // Log performance metrics every 10 seconds
    if (enablePerformanceTracking) {
      const now = Date.now()
      if (now - lastLogTimeRef.current > 10000) {
        console.log('[ThroughputChart] Performance metrics:', {
          messagesReceived: messageCountRef.current,
          rendersTriggered: renderCountRef.current,
          messagesPerRender: (messageCountRef.current / renderCountRef.current).toFixed(2),
          windowSize: slidingWindowRef.current.size(),
          throttleMetrics: metrics,
        })
        lastLogTimeRef.current = now
      }
    }
  }, [throttledMessages, enablePerformanceTracking, metrics])

  // Get chart data from sliding window
  const chartData = useMemo(() => {
    return slidingWindowRef.current.getAll()
  }, [throttledMessages]) // Re-compute when throttled data updates

  // Format tooltip
  const formatTooltip = useCallback((value: unknown) => {
    if (typeof value === 'number') {
      return `${value.toFixed(2)} packets/s`
    }
    return String(value || '')
  }, [])

  // Format Y-axis
  const formatYAxis = useCallback((value: number) => {
    return value >= 1000 ? `${(value / 1000).toFixed(1)}k` : value.toString()
  }, [])

  return (
    <div className="rounded-lg border border-border bg-surface p-4">
      {/* Header */}
      <div className="mb-4 flex items-center justify-between">
        <div>
          <h3 className="text-lg font-semibold text-foreground">{title}</h3>
          <div className="mt-1 flex items-center gap-4 text-xs text-muted">
            <span className="flex items-center gap-1">
              <span
                className={`inline-block h-2 w-2 rounded-full ${
                  state === 'connected'
                    ? 'bg-green-500'
                    : state === 'connecting'
                    ? 'bg-yellow-500'
                    : 'bg-red-500'
                }`}
              />
              {state === 'connected' ? 'Live' : state === 'connecting' ? 'Connecting' : 'Disconnected'}
            </span>
            <span>{slidingWindowRef.current.size()} / 200 points</span>
            {enablePerformanceTracking && metrics && (
              <>
                <span>{metrics.messagesReceived} msgs</span>
                <span>{metrics.rendersTriggered} renders</span>
                <span>{metrics.lastRenderDuration.toFixed(1)}ms</span>
              </>
            )}
          </div>
        </div>
      </div>

      {/* Error message */}
      {error && (
        <div className="mb-4 rounded border border-red-200 bg-red-50 p-3 text-sm text-red-800">
          WebSocket error occurred. Attempting to reconnect...
        </div>
      )}

      {/* Chart */}
      <ResponsiveContainer width="100%" height={height}>
        <LineChart
          data={chartData}
          margin={{ top: 5, right: 30, left: 20, bottom: 5 }}
        >
          <CartesianGrid strokeDasharray="3 3" stroke={gridColor} />
          <XAxis
            dataKey="time"
            tick={{ fontSize: 12, fill: chartColors.text }}
            tickLine={{ stroke: chartColors.border }}
          />
          <YAxis
            tickFormatter={formatYAxis}
            tick={{ fontSize: 12, fill: chartColors.text }}
            tickLine={{ stroke: chartColors.border }}
            label={{
              value: 'Throughput (packets/s)',
              angle: -90,
              position: 'insideLeft',
              style: { fontSize: 12, fill: chartColors.text },
            }}
          />
          <Tooltip
            formatter={formatTooltip}
            contentStyle={{
              backgroundColor: chartColors.surface,
              border: `1px solid ${chartColors.border}`,
              borderRadius: '6px',
              fontSize: '12px',
            }}
          />
          <Legend
            wrapperStyle={{ fontSize: '12px' }}
            iconType="line"
          />
          <Line
            type="monotone"
            dataKey="throughput"
            stroke={lineColor}
            strokeWidth={2}
            dot={false}
            isAnimationActive={false}
            name="Throughput"
          />
        </LineChart>
      </ResponsiveContainer>

      {/* Footer stats */}
      {chartData.length > 0 && (
        <div className="mt-4 grid grid-cols-3 gap-4 border-t border-table-divider pt-4">
          <div>
            <p className="text-xs font-semibold uppercase tracking-wider text-muted">
              Current
            </p>
            <p className="mt-1 text-lg font-semibold text-foreground">
              {chartData[chartData.length - 1]?.throughput.toFixed(2)}
            </p>
            <p className="text-xs text-muted">packets/s</p>
          </div>
          <div>
            <p className="text-xs font-semibold uppercase tracking-wider text-muted">
              Average
            </p>
            <p className="mt-1 text-lg font-semibold text-foreground">
              {(
                chartData.reduce((sum, d) => sum + d.throughput, 0) / chartData.length
              ).toFixed(2)}
            </p>
            <p className="text-xs text-muted">packets/s</p>
          </div>
          <div>
            <p className="text-xs font-semibold uppercase tracking-wider text-muted">
              Peak
            </p>
            <p className="mt-1 text-lg font-semibold text-foreground">
              {Math.max(...chartData.map((d) => d.throughput)).toFixed(2)}
            </p>
            <p className="text-xs text-muted">packets/s</p>
          </div>
        </div>
      )}

      {/* No data message */}
      {chartData.length === 0 && (
        <div className="flex items-center justify-center py-20 text-sm text-muted">
          {state === 'connecting' ? 'Connecting to data stream...' : 'Waiting for data...'}
        </div>
      )}
    </div>
  )
}

'use client'

import { useCallback, useEffect, useRef, useState } from 'react'
import { useBandwidthStream, type BandwidthDataPoint } from '../../hooks/useBandwidthStream'
import { BandwidthFrameQueue } from '../../utils/telemetry/bandwidthFrameQueue'
import { drawBandwidthChart } from './chart/d3Renderer'

export interface BandwidthChartProps {
  wsUrl: string
  title?: string
  height?: number
  enablePerformanceTracking?: boolean
}

export function BandwidthChart({
  wsUrl,
  title = 'Bandwidth Usage',
  height = 300,
  enablePerformanceTracking = false,
}: BandwidthChartProps) {
  const containerRef = useRef<HTMLDivElement>(null)
  const canvasRef = useRef<HTMLCanvasElement>(null)
  const workerRef = useRef<Worker | null>(null)
  const mainThreadDataRef = useRef<BandwidthDataPoint[]>([])
  const mainThreadQueueRef = useRef(new BandwidthFrameQueue())

  const [dimensions, setDimensions] = useState({ width: 400, height })
  const [useWorker, setUseWorker] = useState(false)
  const [connectionState, setConnectionState] = useState<'connecting' | 'connected' | 'disconnected'>('connecting')
  const [mainThreadDecimated, setMainThreadDecimated] = useState(false)
  const [stats, setStats] = useState({ current: 0, average: 0, peak: 0, pointsCount: 0 })

  const updateStats = useCallback((newData: BandwidthDataPoint[]) => {
    if (newData.length === 0) return
    const values = newData.map((d) => d.value)
    setStats({
      current: values[values.length - 1],
      average: values.reduce((sum, value) => sum + value, 0) / values.length,
      peak: Math.max(...values),
      pointsCount: newData.length,
    })
  }, [])

  const appendVisibleFrames = useCallback((frames: BandwidthDataPoint[]) => {
    const data = mainThreadDataRef.current
    frames.forEach((frame) => {
      if (!data.some((point) => point.timestamp === frame.timestamp)) data.push(frame)
    })
    data.sort((a, b) => a.timestamp - b.timestamp)
    while (data.length > 300) data.shift()
    updateStats(data)
  }, [updateStats])

  const handleDataPoint = useCallback((point: BandwidthDataPoint) => {
    if (workerRef.current && useWorker) {
      workerRef.current.postMessage({ type: 'data', data: point })
      appendVisibleFrames([point])
      return
    }

    mainThreadQueueRef.current.enqueue(point)
  }, [appendVisibleFrames, useWorker])

  const ws = useBandwidthStream({ wsUrl, onMessage: handleDataPoint })

  useEffect(() => {
    setConnectionState(
      ws.state === 'connected' ? 'connected' : ws.state === 'connecting' ? 'connecting' : 'disconnected'
    )
  }, [ws.state])

  useEffect(() => {
    const container = containerRef.current
    const canvas = canvasRef.current
    if (!container || !canvas) return

    const rect = container.getBoundingClientRect()
    const dpr = typeof window !== 'undefined' ? window.devicePixelRatio || 1 : 1
    const width = rect.width || 400
    setDimensions({ width, height })

    const supportsOffscreen = typeof HTMLCanvasElement.prototype.transferControlToOffscreen === 'function'
    if (supportsOffscreen && !workerRef.current) {
      try {
        const worker = new Worker(new URL('../../workers/bandwidthWorker.ts', import.meta.url), { type: 'module' })
        canvas.width = width * dpr
        canvas.height = height * dpr
        const offscreen = canvas.transferControlToOffscreen()
        worker.postMessage({ type: 'init', canvas: offscreen, width: width * dpr, height: height * dpr }, [offscreen])
        workerRef.current = worker
        setUseWorker(true)
      } catch (error) {
        console.warn('Failed to initialize OffscreenCanvas worker, falling back to main thread:', error)
        setUseWorker(false)
      }
    }

    const handleResize = () => {
      if (!containerRef.current) return
      const nextWidth = containerRef.current.getBoundingClientRect().width || 400
      setDimensions({ width: nextWidth, height })

      if (workerRef.current) {
        workerRef.current.postMessage({ type: 'resize', width: nextWidth * dpr, height: height * dpr })
      } else if (canvasRef.current) {
        canvasRef.current.width = nextWidth * dpr
        canvasRef.current.height = height * dpr
      }
    }

    window.addEventListener('resize', handleResize)
    return () => {
      window.removeEventListener('resize', handleResize)
      workerRef.current?.terminate()
      workerRef.current = null
      mainThreadQueueRef.current.clear()
    }
  }, [height])

  useEffect(() => {
    if (useWorker) return

    let frameId = 0
    const renderFrame = () => {
      const drained = mainThreadQueueRef.current.drain()
      if (drained.frames.length > 0) {
        appendVisibleFrames(drained.frames)
        setMainThreadDecimated(drained.catchUp)

        const canvas = canvasRef.current
        const ctx = canvas?.getContext('2d')
        if (ctx) {
          drawBandwidthChart(
            ctx,
            mainThreadDataRef.current,
            dimensions.width,
            dimensions.height,
            drained.catchUp
          )
        }
      } else if (mainThreadQueueRef.current.size === 0 && mainThreadDecimated) {
        setMainThreadDecimated(false)
      }

      frameId = requestAnimationFrame(renderFrame)
    }

    frameId = requestAnimationFrame(renderFrame)
    return () => cancelAnimationFrame(frameId)
  }, [appendVisibleFrames, dimensions, mainThreadDecimated, useWorker])

  return (
    <div ref={containerRef} className="rounded-lg border border-border bg-surface p-4">
      <div className="mb-4 flex items-center justify-between">
        <div>
          <h3 className="text-lg font-semibold text-foreground">{title}</h3>
          <div className="mt-1 flex items-center gap-4 text-xs text-muted">
            <span className="flex items-center gap-1">
              <span
                className={`inline-block h-2 w-2 rounded-full ${
                  connectionState === 'connected'
                    ? 'bg-green-500'
                    : connectionState === 'connecting'
                    ? 'bg-yellow-500'
                    : 'bg-red-500'
                }`}
              />
              {connectionState === 'connected' ? 'Live' : connectionState === 'connecting' ? 'Connecting' : 'Disconnected'}
            </span>
            <span>{stats.pointsCount} / 300 points</span>
            {mainThreadDecimated && !useWorker && (
              <span className="text-[10px] bg-surface-alt text-muted px-1.5 py-0.5 rounded font-mono">
                Catching up
              </span>
            )}
            {enablePerformanceTracking && (
              <span className="text-[10px] bg-surface-alt text-muted px-1.5 py-0.5 rounded font-mono">
                {useWorker ? 'Worker Offscreen' : 'Main Thread Fallback'}
              </span>
            )}
          </div>
        </div>
      </div>

      <div style={{ position: 'relative', width: '100%', height: dimensions.height }}>
        <canvas ref={canvasRef} style={{ display: 'block', width: '100%', height: '100%' }} />
      </div>

      {stats.pointsCount > 0 && (
        <div className="mt-4 grid grid-cols-3 gap-4 border-t border-table-divider pt-4">
          <div>
            <p className="text-xs font-semibold uppercase tracking-wider text-muted">Current</p>
            <p className="mt-1 text-lg font-semibold text-foreground">{stats.current.toFixed(2)}</p>
            <p className="text-xs text-muted">Mb/s</p>
          </div>
          <div>
            <p className="text-xs font-semibold uppercase tracking-wider text-muted">Average</p>
            <p className="mt-1 text-lg font-semibold text-foreground">{stats.average.toFixed(2)}</p>
            <p className="text-xs text-muted">Mb/s</p>
          </div>
          <div>
            <p className="text-xs font-semibold uppercase tracking-wider text-muted">Peak</p>
            <p className="mt-1 text-lg font-semibold text-foreground">{stats.peak.toFixed(2)}</p>
            <p className="text-xs text-muted">Mb/s</p>
          </div>
        </div>
      )}
    </div>
  )
}

import React, { useState, useEffect, useRef } from 'react';
import { useShortcutStore, Shortcut } from '../../store/shortcutStore';

export const ShortcutConfigPanel: React.FC = () => {
  const { shortcuts, rebindShortcut, resetToDefaults } = useShortcutStore();
  const [recordingId, setRecordingId] = useState<string | null>(null);
  const [recordedKeys, setRecordedKeys] = useState<string[]>([]);
  const [countdown, setCountdown] = useState<number>(3);
  const [conflictMsg, setConflictMsg] = useState<string | null>(null);
  const countdownIntervalRef = useRef<NodeJS.Timeout | null>(null);

  const BROWSER_DEFAULTS = ['t', 'n', 'w', 'r', 'd', 'f'];

  const startRecording = (id: string) => {
    setRecordingId(id);
    setRecordedKeys([]);
    setCountdown(3);
    setConflictMsg(null);
  };

  useEffect(() => {
    if (recordingId !== null) {
      countdownIntervalRef.current = setInterval(() => {
        setCountdown((prev) => {
          if (prev <= 1) {
            saveBinding();
            return 0;
          }
          return prev - 1;
        });
      }, 1000);
    }
    return () => {
      if (countdownIntervalRef.current) clearInterval(countdownIntervalRef.current);
    };
  }, [recordingId, recordedKeys]);

  useEffect(() => {
    if (recordingId === null) return;

    const handleKeyDown = (e: KeyboardEvent) => {
      e.preventDefault();
      if (['Control', 'Shift', 'Alt', 'Meta'].includes(e.key)) return;
      
      setRecordedKeys((prev) => {
        if (prev.length >= 3) return prev;
        return [...prev, e.key.toLowerCase()];
      });
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [recordingId]);

  const saveBinding = async () => {
    if (!recordingId || recordedKeys.length === 0) {
      cancelRecording();
      return;
    }

    const conflictsWithBrowser = recordedKeys.some((k) => BROWSER_DEFAULTS.includes(k));
    if (conflictsWithBrowser) {
      const confirmOverride = window.confirm(
        `Warning: This shortcut sequence overrides common browser behaviors. Do you want to proceed?`
      );
      if (!confirmOverride) {
        cancelRecording();
        return;
      }
    }

    const result = await rebindShortcut(recordingId, recordedKeys);
    if (!result.success) {
      setConflictMsg(`Conflict detected! Assigned to: "${result.conflict}"`);
      if (countdownIntervalRef.current) clearInterval(countdownIntervalRef.current);
    } else {
      cancelRecording();
    }
  };

  const cancelRecording = () => {
    if (countdownIntervalRef.current) clearInterval(countdownIntervalRef.current);
    setRecordingId(null);
    setRecordedKeys([]);
  };

  return (
    <div className="rounded-xl border border-slate-800 bg-slate-900/50 p-6">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 border-b border-slate-800 pb-4 mb-6">
        <div>
          <h3 className="text-lg font-bold text-white">Keyboard Customization Matrix</h3>
          <p className="text-xs text-slate-400 mt-0.5">Customize workspace mappings. Up to 3 unique keystrokes maximum.</p>
        </div>
        <button
          onClick={() => { if(confirm("Reset all customizations?")) resetToDefaults(); }}
          className="text-xs bg-red-950/40 text-red-400 border border-red-900/50 px-3 py-1.5 rounded-lg hover:bg-red-900/30 transition font-medium"
        >
          Reset All Mappings
        </button>
      </div>

      {recordingId && (
        <div className="mb-6 p-4 rounded-xl border border-cyan-800/50 bg-cyan-950/30 text-cyan-200 flex flex-col md:flex-row justify-between items-center gap-4 animate-pulse">
          <div className="text-center md:text-left">
            <span className="font-bold block text-sm">Listening for Keystrokes...</span>
            <span className="text-xs text-cyan-400">Press sequential bindings. Finalizing in {countdown}s...</span>
          </div>
          <div className="flex gap-2 items-center">
            <div className="flex gap-1.5 bg-slate-950 p-2 rounded-lg border border-slate-800 min-w-[120px] justify-center">
              {recordedKeys.length === 0 ? (
                <span className="text-xs text-slate-500 font-mono">Press keys...</span>
              ) : (
                recordedKeys.map((k, idx) => (
                  <kbd key={idx} className="bg-slate-800 px-2 py-0.5 border border-slate-700 text-white font-mono text-xs font-bold rounded uppercase">{k}</kbd>
                ))
              )}
            </div>
            <button onClick={cancelRecording} className="text-xs text-slate-400 hover:text-white px-2 py-1 bg-slate-800 rounded">Cancel</button>
          </div>
          {conflictMsg && <p className="w-full text-xs text-red-400 mt-2 font-bold">{conflictMsg}</p>}
        </div>
      )}

      <div className="overflow-x-auto">
        <table className="w-full text-left text-xs text-slate-300">
          <thead>
            <tr className="border-b border-slate-800 text-slate-400 font-semibold bg-slate-950/20">
              <th className="py-3 px-4">Action Context</th>
              <th className="py-3 px-4">Category</th>
              <th className="py-3 px-4">Assigned Mapping</th>
              <th className="py-3 px-4 text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-800/60">
            {shortcuts.map((shortcut) => (
              <tr key={shortcut.id} className="hover:bg-slate-800/20 transition-colors">
                <td className="py-3 px-4 font-medium text-white">{shortcut.description}</td>
                <td className="py-3 px-4">
                  <span className="px-2 py-0.5 rounded-full text-[10px] bg-slate-800 text-slate-400 font-medium">
                    {shortcut.category}
                  </span>
                </td>
                <td className="py-3 px-4">
                  <div className="flex gap-1">
                    {shortcut.keys.map((key, i) => (
                      <kbd key={i} className="px-1.5 py-0.5 bg-slate-950 border border-slate-800 rounded font-mono font-bold uppercase text-[11px] text-cyan-400">{key}</kbd>
                    ))}
                  </div>
                </td>
                <td className="py-3 px-4 text-right">
                  <button
                    disabled={recordingId !== null}
                    onClick={() => startRecording(shortcut.id)}
                    className="text-xs bg-slate-800 hover:bg-slate-700 disabled:opacity-50 text-white font-medium px-2.5 py-1 rounded transition"
                  >
                    Rebind
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};

'use client'

import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { useWebSocket } from '@/src/hooks/useWebSocket'
import { useCanvasResize } from '@/src/hooks/useCanvasResize'
import type {
  NetworkActivityData,
  NetworkActivityMessage,
  TimeRange,
  HeatmapCell,
  TrafficArc,
} from '@/src/types/network'
import { TIME_RANGE_LABELS } from '@/src/types/network'

interface ArcParticle {
  arcIndex: number
  progress: number
  speed: number
}

const GRID_RESOLUTION = 0.1
const WORLD_WIDTH = 360
const WORLD_HEIGHT = 180
const PADDING = 40

const TIME_RANGES: TimeRange[] = ['realtime', '1h', '6h', '24h']

const REGION_COLORS = [
  '#0f766e', '#2563eb', '#7c3aed', '#db2777',
  '#ca8a04', '#ea580c', '#059669', '#0284c7',
]

function latLngToXY(
  lat: number,
  lng: number,
  width: number,
  height: number
): [number, number] {
  const x = PADDING + ((lng + 180) / WORLD_WIDTH) * (width - 2 * PADDING)
  const y = PADDING + ((90 - lat) / WORLD_HEIGHT) * (height - 2 * PADDING)
  return [x, y]
}

function heatmapColor(value: number, maxValue: number): string {
  if (maxValue === 0) return 'rgba(0,0,0,0)'
  const t = Math.min(value / maxValue, 1)
  const r = Math.round(t * 255)
  const g = Math.round((1 - t) * 200)
  const b = Math.round((1 - t) * 255)
  const a = 0.3 + t * 0.5
  return `rgba(${r},${g},${b},${a})`
}

function drawGridCell(
  ctx: CanvasRenderingContext2D,
  cellLat: number,
  cellLng: number,
  count: number,
  maxCount: number,
  width: number,
  height: number
) {
  const [x1, y1] = latLngToXY(cellLat, cellLng, width, height)
  const [x2, y2] = latLngToXY(
    cellLat + GRID_RESOLUTION,
    cellLng + GRID_RESOLUTION,
    width,
    height
  )
  const cellW = Math.max(x2 - x1, 2)
  const cellH = Math.max(y2 - y1, 2)

  ctx.fillStyle = heatmapColor(count, maxCount)
  ctx.fillRect(x1, y1, cellW, cellH)
}

function drawArc(
  ctx: CanvasRenderingContext2D,
  sourceLat: number,
  sourceLng: number,
  targetLat: number,
  targetLng: number,
  color: string,
  width: number,
  height: number,
  alpha: number
) {
  const [sx, sy] = latLngToXY(sourceLat, sourceLng, width, height)
  const [tx, ty] = latLngToXY(targetLat, targetLng, width, height)

  const midX = (sx + tx) / 2
  const dy = ty - sy
  const dx = tx - sx
  const distance = Math.sqrt(dx * dx + dy * dy)
  const arcHeight = Math.max(distance * 0.3, 30)
  const cpY = (sy + ty) / 2 - arcHeight

  ctx.beginPath()
  ctx.moveTo(sx, sy)
  ctx.quadraticCurveTo(midX, cpY, tx, ty)
  ctx.strokeStyle = color
  ctx.globalAlpha = alpha * 0.4
  ctx.lineWidth = Math.max(1.5, Math.min(4, distance / 80))
  ctx.stroke()
  ctx.globalAlpha = 1
}

function getArcPoint(
  sourceLat: number,
  sourceLng: number,
  targetLat: number,
  targetLng: number,
  progress: number,
  width: number,
  height: number
): [number, number] {
  const [sx, sy] = latLngToXY(sourceLat, sourceLng, width, height)
  const [tx, ty] = latLngToXY(targetLat, targetLng, width, height)

  const midX = (sx + tx) / 2
  const dy = ty - sy
  const dx = tx - sx
  const distance = Math.sqrt(dx * dx + dy * dy)
  const arcHeight = Math.max(distance * 0.3, 30)
  const cpY = (sy + ty) / 2 - arcHeight

  const t = progress
  const oneMinusT = 1 - t
  const px = oneMinusT * oneMinusT * sx + 2 * oneMinusT * t * midX + t * t * tx
  const py = oneMinusT * oneMinusT * sy + 2 * oneMinusT * t * cpY + t * t * ty
  return [px, py]
}

export interface NetworkActivityHeatmapProps {
  wsUrl?: string
  height?: number
}

export function NetworkActivityHeatmap({
  wsUrl = 'wss://api.lumina.network/ws/v1/network/activity',
  height = 600,
}: NetworkActivityHeatmapProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null)
  const [timeRange, setTimeRange] = useState<TimeRange>('realtime')
  const [activityData, setActivityData] = useState<NetworkActivityData | null>(null)
  const particlesRef = useRef<ArcParticle[]>([])
  const animFrameRef = useRef<number>(0)
  const messagesRef = useRef<NetworkActivityMessage[]>([])
  const lastUpdateRef = useRef(0)

  const handleMessage = useCallback((msg: NetworkActivityMessage) => {
    messagesRef.current.push(msg)
    if (messagesRef.current.length > 5000) {
      messagesRef.current = messagesRef.current.slice(-2500)
    }
  }, [])

  const useMock = typeof window !== 'undefined' && wsUrl.includes('localhost')
  const wsConfig = useMock
    ? { url: 'ws://mock', reconnect: false }
    : { url: wsUrl, reconnect: true, maxReconnectAttempts: 5, reconnectDelayMs: 2000 }

  const { state: wsState } = useWebSocket<NetworkActivityMessage>(
    wsConfig,
    useMock ? () => {} : handleMessage
  )

  const state = useMock ? 'connected' : wsState

  const aggregatedData = useMemo((): NetworkActivityData | null => {
    const msgs = messagesRef.current
    if (msgs.length === 0) return null

    const now = Date.now()
    const windowMs =
      timeRange === 'realtime' ? 5 * 60 * 1000
      : timeRange === '1h' ? 60 * 60 * 1000
      : timeRange === '6h' ? 6 * 60 * 60 * 1000
      : 24 * 60 * 60 * 1000

    const cutoff = now - windowMs
    const relevantMessages = msgs.filter(m => m.timestamp >= cutoff)

    const cellMap = new Map<string, number>()
    const nodeSet = new Set<string>()
    const arcMap = new Map<string, {
      sourceLat: number
      sourceLng: number
      targetLat: number
      targetLng: number
      count: number
    }>()

    for (const msg of relevantMessages) {
      const srcLat = Math.floor(msg.sourceLat / GRID_RESOLUTION) * GRID_RESOLUTION
      const srcLng = Math.floor(msg.sourceLng / GRID_RESOLUTION) * GRID_RESOLUTION
      const srcKey = `${srcLat},${srcLng}`
      cellMap.set(srcKey, (cellMap.get(srcKey) || 0) + msg.messageCount)

      const tgtLat = Math.floor(msg.targetLat / GRID_RESOLUTION) * GRID_RESOLUTION
      const tgtLng = Math.floor(msg.targetLng / GRID_RESOLUTION) * GRID_RESOLUTION
      const tgtKey = `${tgtLat},${tgtLng}`
      cellMap.set(tgtKey, (cellMap.get(tgtKey) || 0) + msg.messageCount)

      nodeSet.add(msg.nodeId)

      const arcKey = `${Math.floor(msg.sourceLat * 10)},${Math.floor(msg.sourceLng * 10)}-${Math.floor(msg.targetLat * 10)},${Math.floor(msg.targetLng * 10)}`
      const existing = arcMap.get(arcKey)
      if (existing) {
        existing.count += msg.messageCount
      } else {
        arcMap.set(arcKey, {
          sourceLat: msg.sourceLat,
          sourceLng: msg.sourceLng,
          targetLat: msg.targetLat,
          targetLng: msg.targetLng,
          count: msg.messageCount,
        })
      }
    }

    const cells: HeatmapCell[] = []
    for (const [key, count] of cellMap) {
      const [latStr, lngStr] = key.split(',')
      cells.push({
        lat: parseFloat(latStr),
        lng: parseFloat(lngStr),
        count,
        weight: count,
      })
    }

    const arcEntries = Array.from(arcMap.entries())
    const topArcs = arcEntries
      .sort(([, a], [, b]) => b.count - a.count)
      .slice(0, 50)

    const arcs: TrafficArc[] = topArcs.map(([key, val], i) => ({
      id: key,
      sourceLat: val.sourceLat,
      sourceLng: val.sourceLng,
      targetLat: val.targetLat,
      targetLng: val.targetLng,
      messageCount: val.count,
      color: REGION_COLORS[i % REGION_COLORS.length],
    }))

    return {
      cells,
      arcs,
      messageCount: relevantMessages.reduce((s, m) => s + m.messageCount, 0),
      activeNodes: nodeSet.size,
      timestamp: now,
    }
  }, [timeRange, state])

  const draw = useCallback(() => {
    const canvas = canvasRef.current
    if (!canvas) return

    const ctx = canvas.getContext('2d')
    if (!ctx || !activityData) return

    const w = canvas.width
    const h = canvas.height
    if (w === 0 || h === 0) return

    ctx.clearRect(0, 0, w, h)

    ctx.fillStyle = '#f7f4ee'
    ctx.fillRect(0, 0, w, h)

    const graticuleSpacing = 30
    ctx.strokeStyle = '#e8e0d4'
    ctx.lineWidth = 0.5
    for (let lat = -90; lat <= 90; lat += graticuleSpacing) {
      const y = PADDING + ((90 - lat) / WORLD_HEIGHT) * (h - 2 * PADDING)
      ctx.beginPath()
      ctx.moveTo(PADDING, y)
      ctx.lineTo(w - PADDING, y)
      ctx.stroke()
    }
    for (let lng = -180; lng <= 180; lng += graticuleSpacing) {
      const x = PADDING + ((lng + 180) / WORLD_WIDTH) * (w - 2 * PADDING)
      ctx.beginPath()
      ctx.moveTo(x, PADDING)
      ctx.lineTo(x, h - PADDING)
      ctx.stroke()
    }

    const continentOutlines = [
      { lat: 35, lng: -10 }, { lat: 36, lng: -5 }, { lat: 43, lng: 0 }, { lat: 47, lng: 3 }, { lat: 51, lng: 5 }, { lat: 55, lng: 2 }, { lat: 58, lng: -5 }, { lat: 58, lng: -10 }, { lat: 55, lng: -15 }, { lat: 50, lng: -18 }, { lat: 45, lng: -15 }, { lat: 38, lng: -10 }, { lat: 35, lng: -10 },
      { lat: 35, lng: -80 }, { lat: 30, lng: -75 }, { lat: 25, lng: -70 }, { lat: 20, lng: -65 }, { lat: 15, lng: -60 }, { lat: 10, lng: -55 }, { lat: 5, lng: -50 }, { lat: 0, lng: -45 }, { lat: -5, lng: -40 }, { lat: -10, lng: -35 }, { lat: -15, lng: -30 }, { lat: -20, lng: -25 }, { lat: -25, lng: -20 }, { lat: -30, lng: -15 }, { lat: -35, lng: -10 }, { lat: -40, lng: -5 }, { lat: -45, lng: 0 }, { lat: -50, lng: 5 }, { lat: -55, lng: 0 }, { lat: -50, lng: -5 }, { lat: -45, lng: -10 }, { lat: -40, lng: -15 }, { lat: -35, lng: -20 }, { lat: -30, lng: -25 }, { lat: -25, lng: -30 }, { lat: -20, lng: -35 }, { lat: -15, lng: -40 }, { lat: -10, lng: -45 }, { lat: -5, lng: -50 }, { lat: 0, lng: -55 }, { lat: 5, lng: -60 }, { lat: 10, lng: -65 }, { lat: 15, lng: -70 }, { lat: 20, lng: -75 }, { lat: 25, lng: -80 }, { lat: 30, lng: -85 }, { lat: 35, lng: -80 },
      { lat: -85, lng: 10 }, { lat: -80, lng: 15 }, { lat: -75, lng: 20 }, { lat: -70, lng: 25 }, { lat: -65, lng: 30 }, { lat: -60, lng: 35 }, { lat: -55, lng: 40 }, { lat: -50, lng: 45 }, { lat: -45, lng: 50 }, { lat: -40, lng: 55 }, { lat: -35, lng: 60 }, { lat: -30, lng: 65 }, { lat: -25, lng: 70 }, { lat: -20, lng: 75 }, { lat: -15, lng: 80 }, { lat: -10, lng: 85 }, { lat: -5, lng: 90 }, { lat: 0, lng: 95 }, { lat: -5, lng: 100 }, { lat: -10, lng: 105 }, { lat: -15, lng: 110 }, { lat: -20, lng: 115 }, { lat: -25, lng: 120 }, { lat: -30, lng: 125 }, { lat: -35, lng: 130 }, { lat: -40, lng: 135 }, { lat: -45, lng: 140 }, { lat: -50, lng: 145 }, { lat: -55, lng: 150 },
      { lat: 35, lng: 115 }, { lat: 30, lng: 120 }, { lat: 25, lng: 125 }, { lat: 20, lng: 130 }, { lat: 15, lng: 135 }, { lat: 10, lng: 140 }, { lat: 5, lng: 145 }, { lat: 0, lng: 150 }, { lat: -5, lng: 155 }, { lat: -10, lng: 160 }, { lat: -15, lng: 165 }, { lat: -20, lng: 170 }, { lat: -25, lng: 175 }, { lat: -30, lng: 180 },
      { lat: -170, lng: 60 }, { lat: -165, lng: 65 }, { lat: -160, lng: 70 }, { lat: -155, lng: 70 }, { lat: -150, lng: 65 }, { lat: -145, lng: 60 }, { lat: -140, lng: 55 }, { lat: -135, lng: 50 }, { lat: -130, lng: 45 }, { lat: -125, lng: 40 }, { lat: -120, lng: 35 }, { lat: -115, lng: 30 }, { lat: -110, lng: 25 }, { lat: -105, lng: 20 }, { lat: -100, lng: 15 }, { lat: -95, lng: 20 }, { lat: -90, lng: 25 }, { lat: -85, lng: 30 }, { lat: -80, lng: 35 }, { lat: -75, lng: 40 }, { lat: -70, lng: 45 }, { lat: -65, lng: 50 }, { lat: -60, lng: 55 }, { lat: -55, lng: 60 }, { lat: -50, lng: 65 }, { lat: -45, lng: 70 },
      { lat: 10, lng: -85 }, { lat: 15, lng: -80 }, { lat: 20, lng: -75 }, { lat: 25, lng: -70 }, { lat: 30, lng: -65 }, { lat: 35, lng: -60 }, { lat: 40, lng: -55 }, { lat: 45, lng: -50 }, { lat: 50, lng: -45 }, { lat: 55, lng: -40 }, { lat: 60, lng: -35 }, { lat: 65, lng: -30 }, { lat: 70, lng: -25 }, { lat: 75, lng: -20 }, { lat: 80, lng: -15 }, { lat: 85, lng: -10 },
    ]

    ctx.strokeStyle = '#d8d0c1'
    ctx.lineWidth = 1
    ctx.beginPath()
    let isFirst = true
    for (const pt of continentOutlines) {
      const [x, y] = latLngToXY(pt.lat, pt.lng, w, h)
      if (isFirst) {
        ctx.moveTo(x, y)
        isFirst = false
      } else {
        ctx.lineTo(x, y)
      }
    }
    ctx.stroke()

    const maxCellCount = Math.max(...activityData.cells.map(c => c.count), 1)
    for (const cell of activityData.cells) {
      drawGridCell(ctx, cell.lat, cell.lng, cell.count, maxCellCount, w, h)
    }

    for (const arc of activityData.arcs) {
      drawArc(ctx, arc.sourceLat, arc.sourceLng, arc.targetLat, arc.targetLng, arc.color, w, h, 0.6)
    }

    const particles = particlesRef.current
    for (const p of particles) {
      if (p.arcIndex >= activityData.arcs.length) continue
      const arc = activityData.arcs[p.arcIndex]
      const [px, py] = getArcPoint(
        arc.sourceLat, arc.sourceLng,
        arc.targetLat, arc.targetLng,
        p.progress, w, h
      )

      ctx.beginPath()
      ctx.arc(px, py, 3, 0, Math.PI * 2)
      ctx.fillStyle = arc.color
      ctx.globalAlpha = 0.8
      ctx.fill()
      ctx.globalAlpha = 1

      p.progress += p.speed * 0.005
      if (p.progress > 1) {
        p.progress = 0
      }
    }

    const gradient = ctx.createLinearGradient(
      w - PADDING - 180, PADDING + 10,
      w - PADDING, PADDING + 10
    )
    gradient.addColorStop(0, 'rgba(0,0,255,0.8)')
    gradient.addColorStop(0.25, 'rgba(0,200,255,0.8)')
    gradient.addColorStop(0.5, 'rgba(0,255,100,0.8)')
    gradient.addColorStop(0.75, 'rgba(255,200,0,0.8)')
    gradient.addColorStop(1, 'rgba(255,0,0,0.8)')

    ctx.fillStyle = gradient
    ctx.fillRect(w - PADDING - 180, PADDING + 10, 180, 14)

    ctx.strokeStyle = '#d8d0c1'
    ctx.lineWidth = 1
    ctx.strokeRect(w - PADDING - 180, PADDING + 10, 180, 14)

    ctx.fillStyle = '#6f5f48'
    ctx.font = '10px sans-serif'
    ctx.textAlign = 'left'
    ctx.fillText('Low', w - PADDING - 180, PADDING + 34)
    ctx.textAlign = 'right'
    ctx.fillText('High', w - PADDING, PADDING + 34)

    animFrameRef.current = requestAnimationFrame(draw)
  }, [activityData])

  useCanvasResize(canvasRef, draw)

  useEffect(() => {
    if (!activityData) return

    const neededParticles = Math.max(activityData.arcs.length * 3, 10)
    const currentParticles = particlesRef.current

    while (currentParticles.length < neededParticles) {
      const arcIndex = currentParticles.length % Math.max(activityData.arcs.length, 1)
      currentParticles.push({
        arcIndex,
        progress: Math.random(),
        speed: 0.5 + Math.random() * 0.5,
      })
    }

    while (currentParticles.length > neededParticles) {
      currentParticles.pop()
    }

    animFrameRef.current = requestAnimationFrame(draw)

    return () => {
      if (animFrameRef.current) {
        cancelAnimationFrame(animFrameRef.current)
      }
    }
  }, [activityData, draw])

  useEffect(() => {
    if (!useMock) return

    const regions = [
      { lat: 40.7128, lng: -74.006 },
      { lat: 34.0522, lng: -118.2437 },
      { lat: 51.5074, lng: -0.1278 },
      { lat: 48.8566, lng: 2.3522 },
      { lat: 35.6762, lng: 139.6503 },
      { lat: 31.2304, lng: 121.4737 },
      { lat: -33.8688, lng: 151.2093 },
      { lat: -23.5505, lng: -46.6333 },
      { lat: 55.7558, lng: 37.6173 },
      { lat: 28.6139, lng: 77.209 },
      { lat: 1.3521, lng: 103.8198 },
      { lat: 19.076, lng: 72.8777 },
      { lat: 41.9028, lng: 12.4964 },
      { lat: 52.52, lng: 13.405 },
      { lat: 37.5665, lng: 126.978 },
    ]

    const interval = setInterval(() => {
      const msgCount = 3 + Math.floor(Math.random() * 8)
      for (let i = 0; i < msgCount; i++) {
        const srcIdx = Math.floor(Math.random() * regions.length)
        let dstIdx = Math.floor(Math.random() * regions.length)
        while (dstIdx === srcIdx) {
          dstIdx = Math.floor(Math.random() * regions.length)
        }
        const src = regions[srcIdx]
        const dst = regions[dstIdx]

        messagesRef.current.push({
          timestamp: Date.now(),
          sourceLat: src.lat + (Math.random() - 0.5) * 2,
          sourceLng: src.lng + (Math.random() - 0.5) * 2,
          targetLat: dst.lat + (Math.random() - 0.5) * 2,
          targetLng: dst.lng + (Math.random() - 0.5) * 2,
          messageCount: 1 + Math.floor(Math.random() * 20),
          nodeId: `node-${srcIdx}`,
        })

        if (messagesRef.current.length > 5000) {
          messagesRef.current = messagesRef.current.slice(-2500)
        }
      }
    }, 400)

    return () => clearInterval(interval)
  }, [useMock])

  useEffect(() => {
    if (aggregatedData) {
      setActivityData(aggregatedData)
      lastUpdateRef.current = Date.now()
    }
  }, [aggregatedData])

  return (
    <div className="rounded-lg border border-[#d8d0c1] bg-white">
      <div className="flex items-center justify-between border-b border-[#d8d0c1] px-5 py-3">
        <div>
          <h3 className="text-lg font-semibold text-[#1a1410]">
            Network Activity Heatmap
          </h3>
          <div className="mt-1 flex items-center gap-3 text-xs text-[#6f5f48]">
            <span className="flex items-center gap-1">
              <span
                className={`inline-block h-2 w-2 rounded-full ${
                  state === 'connected'
                    ? 'bg-green-500'
                    : state === 'connecting'
                    ? 'bg-yellow-500'
                    : 'bg-red-500'
                }`}
              />
              {state === 'connected' ? 'Live' : state === 'connecting' ? 'Connecting' : 'Disconnected'}
            </span>
            {activityData && (
              <>
                <span>{activityData.messageCount.toLocaleString()} msgs</span>
                <span>{activityData.activeNodes} nodes</span>
                <span>{activityData.cells.length} cells</span>
              </>
            )}
          </div>
        </div>
        <div className="flex gap-1">
          {TIME_RANGES.map((range) => (
            <button
              key={range}
              onClick={() => setTimeRange(range)}
              className={`rounded-md px-3 py-1.5 text-xs font-medium transition-colors ${
                timeRange === range
                  ? 'bg-[#0f766e] text-white'
                  : 'bg-[#f7f4ee] text-[#6f5f48] hover:bg-[#ece5d8]'
              }`}
            >
              {TIME_RANGE_LABELS[range]}
            </button>
          ))}
        </div>
      </div>

      <div className="relative" style={{ height: `${height}px` }}>
        <canvas
          ref={canvasRef}
          className="h-full w-full"
        />

        {!activityData && (
          <div className="absolute inset-0 flex items-center justify-center text-sm text-[#6f5f48]">
            {state === 'connecting' ? 'Connecting to data stream...' : 'Waiting for data...'}
          </div>
        )}
      </div>

      {state === 'error' && (
        <div className="border-t border-[#d8d0c1] px-5 py-2 text-xs text-red-600">
          WebSocket connection error. Attempting to reconnect...
        </div>
      )}
    </div>
  )
}

import React, { useEffect, useRef } from "react";
import * as d3 from "d3";
import { configureTreeLayout } from "../../lib/d3/treeLayout";

interface TreeViewProps {
  data: d3.HierarchyNode<any>;
  width?: number;
  height?: number;
}

function getThemeColor(varName: string): string {
  return getComputedStyle(document.documentElement).getPropertyValue(varName).trim()
}

function resolveStatusColor(status: string): string {
  const map: Record<string, string> = {
    healthy: getThemeColor('--color-status-healthy'),
    warning: getThemeColor('--color-status-warning'),
    critical: getThemeColor('--color-status-critical'),
  }
  return map[status] || getThemeColor('--color-muted')
}

export const TreeView: React.FC<TreeViewProps> = ({
  data,
  width = 960,
  height = 600,
}) => {
  const svgRef = useRef<SVGSVGElement | null>(null);
  const gContainerRef = useRef<SVGGElement | null>(null);

  useEffect(() => {
    if (!svgRef.current || !data) return;

    const svg = d3.select(svgRef.current);
    const gContainer = d3.select(gContainerRef.current);
    const treeLayout = configureTreeLayout(width, height);

    // Track layout IDs to persist toggle state across renders
    let i = 0;

    // Initialize root position coordinates
    const root = data as any;
    root.x0 = height / 2;
    root.y0 = 0;

    // Explicitly collapse everything beyond Level 2 (Region) on initial load
    if (root.children) {
      root.children.forEach(collapseSubtree);
    }

    function collapseSubtree(d: any) {
      if (d.children) {
        d._children = d.children;
        d._children.forEach(collapseSubtree);
        d.children = null;
      }
    }

    // Set up Pan and Zoom behavior bounds
    const zoomBehavior = d3
      .zoom<SVGSVGElement, unknown>()
      .scaleExtent([0.25, 4])
      .on("zoom", (event) => {
        gContainer.attr("transform", event.transform);
      });

    svg.call(zoomBehavior);

    // Initial Tree Render Call
    update(root);

    function update(source: any) {
      const treeData = treeLayout(root);
      const nodes = treeData.descendants();
      const links = treeData.links();

      // Enforce normalized tree level depths
      nodes.forEach((d: any) => {
        d.y = d.depth * 180;
      });

      // --- Node Management ---
      const node = gContainer
        .selectAll("g.node")
        .data(nodes, (d: any) => d.id || (d.id = ++i));

      // Enter phase: Instantiate missing nodes at parent's previous position
      const nodeEnter = node
        .enter()
        .append("g")
        .attr("class", "node")
        .attr("transform", () => `translate(${source.y0},${source.x0})`)
        .on("click", (event, d: any) => {
          if (d.children) {
            d._children = d.children;
            d.children = null;
          } else {
            d.children = d._children;
            d._children = null;
          }
          update(d);
        })
        .style("cursor", "pointer");

      nodeEnter
        .append("circle")
        .attr("r", 1e-6)
        .style(
          "fill",
          (d: any) => resolveStatusColor(d.data.status),
        );

      nodeEnter
        .append("text")
        .attr("dy", ".35em")
        .attr("x", (d: any) => (d.children || d._children ? -13 : 13))
        .attr("text-anchor", (d: any) =>
          d.children || d._children ? "end" : "start",
        )
        .text((d: any) => d.data.name)
        .style("fill-opacity", 1e-6)
        .style("font-size", "12px")
        .style("user-select", "none")
        .attr("class", "fill-foreground font-medium");

      // Update phase: Smoothly transition nodes to their newly calculated positions
      const nodeUpdate = node
        .merge(nodeEnter as any)
        .transition()
        .duration(400)
        .ease(d3.easeCubicInOut)
        .attr("transform", (d: any) => `translate(${d.y},${d.x})`);

      nodeUpdate
        .select("circle")
        .attr("r", 7)
        .style(
          "fill",
          (d: any) => resolveStatusColor(d.data.status),
        )
        .style("stroke", () => getThemeColor('--color-surface'))
        .style("stroke-width", "2px");

      nodeUpdate.select("text").style("fill-opacity", 1);

      // Handle independent 200 ms color transitions on state/status mutations
      node
        .select("circle")
        .transition()
        .duration(200)
        .style(
          "fill",
          (d: any) => resolveStatusColor(d.data.status),
        );

      // Exit phase: Transition departing nodes back to the clicked parent node
      const nodeExit = node
        .exit()
        .transition()
        .duration(400)
        .ease(d3.easeCubicInOut)
        .attr("transform", () => `translate(${source.y},${source.x})`)
        .remove();

      nodeExit.select("circle").attr("r", 1e-6);
      nodeExit.select("text").style("fill-opacity", 1e-6);

      // --- Link Management ---
      const link = gContainer
        .selectAll("path.link")
        .data(links, (d: any) => d.target.id);

      // Generating clean standard horizontal curved path connections
      const diagonal = d3
        .linkHorizontal()
        .x((d: any) => d.y)
        .y((d: any) => d.x);

      // Enter phase: Generate links collapsing into parent node
      const linkEnter = link
        .enter()
        .insert("path", "g")
        .attr("class", "link")
        .attr("d", () => {
          const o = { x: source.x0, y: source.y0 };
          return diagonal({ source: o, target: o } as any);
        })
        .style("fill", "none")
        .style("stroke", () => getThemeColor('--color-border'))
        .style("stroke-width", "1.5px");

      // Update phase: Standard view transitions for expanding paths
      link
        .merge(linkEnter as any)
        .transition()
        .duration(400)
        .ease(d3.easeCubicInOut)
        .attr("d", diagonal as any);

      // Exit phase: Contract links back down into structural parent node
      link
        .exit()
        .transition()
        .duration(400)
        .ease(d3.easeCubicInOut)
        .attr("d", () => {
          const o = { x: source.x, y: source.y };
          return diagonal({ source: o, target: o } as any);
        })
        .remove();

      // Cache structural positional history for subsequent animation runs
      nodes.forEach((d: any) => {
        d.x0 = d.x;
        d.y0 = d.y;
      });
    }
  }, [data, width, height]);

  return (
    <div className="w-full h-full border border-border rounded-xl overflow-hidden bg-surface">
      <svg
        ref={svgRef}
        width={width}
        height={height}
        className="w-full h-full select-none"
      >
        <g ref={gContainerRef} transform="translate(80, 40)" />
      </svg>
    </div>
  );
};

'use client';

import React, { useState, useEffect, useRef } from 'react';
import { useQuery } from '@tanstack/react-query';
import { usePrintReport } from '@/src/hooks/usePrintReport';
import { ReportSection } from '@/src/components/reports/ReportSection';
import { type ReportData, splitReportIntoVolumes, type ReportVolume } from '@/src/utils/printHelpers';

// Chart implementation using Recharts for interactive view
import {
  ResponsiveContainer,
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip
} from 'recharts';

export function AuditReportPage() {
  const [startDate, setStartDate] = useState('2026-07-01');
  const [endDate, setEndDate] = useState('2026-07-19');
  const [simulateLarge, setSimulateLarge] = useState(false);
  const [activeVolumeIndex, setActiveVolumeIndex] = useState(0);

  const printContainerId = 'report-print-container';
  const { printVolume, isPrinting, volumes, activeVolumeToPrint } = usePrintReport();

  // TanStack Query to fetch data based on inputs
  const { data, isLoading, refetch, isFetching } = useQuery<ReportData>({
    queryKey: ['audit-report-data', startDate, endDate, simulateLarge],
    queryFn: async () => {
      // Mock network latency
      await new Promise((resolve) => setTimeout(resolve, 800));

      const totalNodes = simulateLarge ? 1300 : 65;
      const totalAlerts = simulateLarge ? 120 : 45;

      const nodeInventory = Array.from({ length: totalNodes }, (_, i) => ({
        id: `node-${i + 1}`,
        label: `Validator ${String.fromCharCode(65 + (i % 26))}-${Math.floor(i / 26) + 1}`,
        location: ['us-east', 'eu-west', 'ap-southeast', 'us-west', 'eu-central', 'ap-northeast'][i % 6],
        ownerName: `Organization ${String.fromCharCode(65 + (i % 26))}`,
        ipAddress: `10.0.${Math.floor(i / 4)}.${(i % 4) * 64 + 1}`,
        firmwareVersion: `v${Math.floor(i / 10) + 1}.${i % 10}`,
        uptime: `${95 + (i % 5)}.${(i * 17) % 100}%`,
        status: (i % 15 === 0 ? 'offline' : i % 8 === 0 ? 'degraded' : 'online') as 'online' | 'offline' | 'degraded',
      }));

      const alerts = Array.from({ length: totalAlerts }, (_, i) => ({
        id: `alert-${i + 1}`,
        severity: (i % 7 === 0 ? 'critical' : i % 3 === 0 ? 'warning' : 'info') as 'critical' | 'warning' | 'info',
        message: [
          'High latency detected on validator node',
          'Unscheduled peer disconnection',
          'CPU usage exceeded threshold 90%',
          'System update successfully applied',
          'Database replication lag warning',
        ][i % 5] + ` (Node ${Math.floor(i / 5) + 1})`,
        timestamp: new Date(Date.now() - i * 3600000).toLocaleString(),
        nodeId: `node-${Math.floor(i / 5) + 1}`,
      }));

      const bandwidthGraphs = Array.from({ length: 24 }, (_, i) => ({
        timestamp: Date.now() - (24 - i) * 3600000,
        throughput: Math.floor(800 + Math.sin(i / 3) * 300 + Math.random() * 100),
        latency: Math.floor(15 + Math.cos(i / 4) * 5 + Math.random() * 3),
      }));

      return {
        facilitySummary: {
          healthScore: 98,
          activeNodes: nodeInventory.filter(n => n.status !== 'offline').length,
          totalNodes: nodeInventory.length,
          activeAlerts: alerts.filter(a => a.severity === 'critical').length,
          uptime: '99.98%',
          avgLatency: '18.4ms',
          avgThroughput: '942/s',
        },
        nodeInventory,
        alerts,
        bandwidthGraphs,
      };
    },
    staleTime: 30_000,
  });

  // Calculate volumes for screen rendering & switcher
  const currentVolumes = data ? splitReportIntoVolumes(data) : [];

  // Canvas drawing reference for print layout
  const printCanvasRef = useRef<HTMLCanvasElement | null>(null);

  useEffect(() => {
    if (activeVolumeToPrint?.bandwidthGraphs && printCanvasRef.current) {
      const canvas = printCanvasRef.current;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        // Clear background
        ctx.fillStyle = '#ffffff';
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        // Draw title
        ctx.fillStyle = '#171512';
        ctx.font = 'bold 16px serif';
        ctx.fillText('Bandwidth Graph (Throughput packets/s)', 30, 40);

        // Draw Axis lines
        ctx.strokeStyle = '#cccccc';
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(50, 60);
        ctx.lineTo(50, 240);
        ctx.lineTo(750, 240);
        ctx.stroke();

        // Plot data points
        const points = activeVolumeToPrint.bandwidthGraphs;
        const paddingX = 60;
        const paddingY = 60;
        const width = 700;
        const height = 180;
        const maxThroughput = Math.max(...points.map(p => p.throughput), 1000);

        ctx.strokeStyle = '#0f766e';
        ctx.lineWidth = 2;
        ctx.beginPath();

        points.forEach((p, idx) => {
          const x = paddingX + (idx / (points.length - 1)) * width;
          const y = 240 - (p.throughput / maxThroughput) * height;
          if (idx === 0) {
            ctx.moveTo(x, y);
          } else {
            ctx.lineTo(x, y);
          }
        });
        ctx.stroke();
      }
    }
  }, [activeVolumeToPrint]);

  const handleGenerate = (e: React.FormEvent) => {
    e.preventDefault();
    refetch();
  };

  const handlePrint = (volumeNum: number) => {
    if (data) {
      printVolume(data, volumeNum, printContainerId);
    }
  };

  return (
    <main className="min-h-screen bg-[#f7f4ee] text-[#171512] screen-container">
      <div className="mx-auto max-w-7xl px-4 py-8 sm:px-6 lg:px-8">
        {/* Page Header */}
        <div className="border-b border-[#d8d0c1] pb-6 mb-8 flex flex-col sm:flex-row justify-between items-start sm:items-center">
          <div>
            <p className="text-xs font-semibold uppercase tracking-[0.22em] text-[#6f5f48]">
              Compliance & Auditing
            </p>
            <h1 className="mt-2 text-3xl font-bold tracking-tight text-[#171512] sm:text-4xl">
              Facility Audit Reports
            </h1>
            <p className="mt-1 text-sm text-[#6f5f48]">
              Generate printable PDF reports of facility health, validator node status, and alert history.
            </p>
          </div>
        </div>

        {/* Date Filter & Control Panel */}
        <form onSubmit={handleGenerate} className="bg-white rounded-xl border border-[#d8d0c1] p-5 shadow-sm mb-8 flex flex-wrap items-end gap-6">
          <div className="flex-1 min-w-[200px]">
            <label className="block text-xs font-bold uppercase tracking-wider text-[#6f5f48] mb-2">
              Start Date
            </label>
            <input
              type="date"
              value={startDate}
              onChange={(e) => setStartDate(e.target.value)}
              className="w-full rounded-lg border border-[#d8d0c1] bg-[#faf8f3] px-3 py-2 text-sm text-[#171512] focus:border-[#0f766e] focus:outline-none"
            />
          </div>

          <div className="flex-1 min-w-[200px]">
            <label className="block text-xs font-bold uppercase tracking-wider text-[#6f5f48] mb-2">
              End Date
            </label>
            <input
              type="date"
              value={endDate}
              onChange={(e) => setEndDate(e.target.value)}
              className="w-full rounded-lg border border-[#d8d0c1] bg-[#faf8f3] px-3 py-2 text-sm text-[#171512] focus:border-[#0f766e] focus:outline-none"
            />
          </div>

          <div className="flex items-center gap-3 py-2.5">
            <input
              type="checkbox"
              id="simulateLarge"
              checked={simulateLarge}
              onChange={(e) => setSimulateLarge(e.target.checked)}
              className="h-5 w-5 rounded border-[#d8d0c1] text-[#0f766e] focus:ring-[#0f766e]"
            />
            <label htmlFor="simulateLarge" className="text-sm font-semibold text-[#171512] select-none cursor-pointer">
              Simulate Large Dataset (&gt;50 pages)
            </label>
          </div>

          <div>
            <button
              type="submit"
              disabled={isFetching}
              className="w-full rounded-lg bg-[#0f766e] hover:bg-[#115e59] px-6 py-2 text-sm font-semibold text-white transition-colors duration-200 disabled:opacity-50"
            >
              {isFetching ? 'Fetching Data...' : 'Generate Report'}
            </button>
          </div>
        </form>

        {/* Dashboard Preview Interface */}
        {isLoading ? (
          <div className="py-20 text-center text-[#6f5f48]">
            <div className="inline-block h-8 w-8 animate-spin rounded-full border-4 border-solid border-current border-r-transparent align-[-0.125em] motion-reduce:animate-[spin_1.5s_linear_infinite]" />
            <p className="mt-4 text-sm font-medium">Fetching and compiling audit data...</p>
          </div>
        ) : !data ? (
          <div className="py-20 text-center border border-dashed border-[#d8d0c1] rounded-xl text-[#6f5f48]">
            Please enter a date range and click "Generate Report".
          </div>
        ) : (
          <div>
            {/* Volume Status and Switcher */}
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center bg-[#faf8f3] border border-[#d8d0c1] rounded-xl p-4 mb-6 gap-4">
              <div>
                <p className="text-sm font-semibold text-[#171512]">
                  Report Compiled successfully: <span className="font-bold text-[#0f766e]">{currentVolumes.length} Volume(s)</span>
                </p>
                <p className="text-xs text-[#6f5f48] mt-1">
                  Each volume is paginated within regulatory limits (&lt;50 pages) for physical printing.
                </p>
              </div>
              <div className="flex gap-2 flex-wrap">
                {currentVolumes.map((vol, idx) => (
                  <button
                    key={vol.volumeNumber}
                    onClick={() => {
                      setActiveVolumeIndex(idx);
                    }}
                    className={`px-4 py-1.5 text-xs font-semibold rounded-lg border transition-all duration-200 ${
                      activeVolumeIndex === idx
                        ? 'bg-[#0f766e] border-[#0f766e] text-white'
                        : 'bg-white border-[#d8d0c1] text-[#171512] hover:bg-neutral-50'
                    }`}
                  >
                    Volume {vol.volumeNumber}
                  </button>
                ))}
              </div>
            </div>

            {/* Selected Volume Preview Panel */}
            <div className="bg-white rounded-xl border border-[#d8d0c1] p-6 shadow-sm">
              <div className="flex justify-between items-center border-b border-[#ece5d8] pb-4 mb-6">
                <div>
                  <h2 className="text-xl font-bold text-[#171512]">
                    {currentVolumes[activeVolumeIndex]?.title}
                  </h2>
                  <p className="text-xs text-[#6f5f48] mt-0.5">
                    Previewing content that will be formatted in A4 sizing
                  </p>
                </div>
                <div>
                  <button
                    onClick={() => handlePrint(currentVolumes[activeVolumeIndex].volumeNumber)}
                    className="flex items-center gap-2 rounded-lg bg-[#0f766e] hover:bg-[#115e59] px-5 py-2 text-xs font-bold text-white transition-all duration-200"
                  >
                    <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z" />
                    </svg>
                    Print / Save as PDF
                  </button>
                </div>
              </div>

              {/* Volume Content Render Preview */}
              <div className="space-y-8">
                {/* 1. Facility Summary */}
                {currentVolumes[activeVolumeIndex]?.facilitySummary && (
                  <div className="border border-[#d8d0c1] rounded-xl p-5 bg-[#faf8f3]">
                    <h3 className="text-sm font-semibold uppercase tracking-wider text-[#6f5f48] mb-4">
                      Facility Performance Summary
                    </h3>
                    <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                      <div className="bg-white border border-[#d8d0c1] p-4 rounded-lg">
                        <span className="text-xs text-[#6f5f48]">Health Score</span>
                        <p className="text-2xl font-bold text-teal-700 mt-1">
                          {currentVolumes[activeVolumeIndex].facilitySummary?.healthScore}%
                        </p>
                      </div>
                      <div className="bg-white border border-[#d8d0c1] p-4 rounded-lg">
                        <span className="text-xs text-[#6f5f48]">Active / Total Nodes</span>
                        <p className="text-2xl font-bold text-neutral-800 mt-1">
                          {currentVolumes[activeVolumeIndex].facilitySummary?.activeNodes} / {currentVolumes[activeVolumeIndex].facilitySummary?.totalNodes}
                        </p>
                      </div>
                      <div className="bg-white border border-[#d8d0c1] p-4 rounded-lg">
                        <span className="text-xs text-[#6f5f48]">Active Critical Alerts</span>
                        <p className="text-2xl font-bold text-orange-700 mt-1">
                          {currentVolumes[activeVolumeIndex].facilitySummary?.activeAlerts}
                        </p>
                      </div>
                      <div className="bg-white border border-[#d8d0c1] p-4 rounded-lg">
                        <span className="text-xs text-[#6f5f48]">System Uptime</span>
                        <p className="text-2xl font-bold text-[#171512] mt-1">
                          {currentVolumes[activeVolumeIndex].facilitySummary?.uptime}
                        </p>
                      </div>
                    </div>
                  </div>
                )}

                {/* 2. Bandwidth Graphs */}
                {currentVolumes[activeVolumeIndex]?.bandwidthGraphs && (
                  <div className="border border-[#d8d0c1] rounded-xl p-5 bg-white">
                    <h3 className="text-sm font-semibold uppercase tracking-wider text-[#6f5f48] mb-4">
                      Bandwidth and Latency Over Time (Interactive Chart)
                    </h3>
                    <div className="h-[250px] w-full">
                      <ResponsiveContainer width="100%" height="100%">
                        <LineChart data={currentVolumes[activeVolumeIndex].bandwidthGraphs} margin={{ top: 10, right: 30, left: 0, bottom: 0 }}>
                          <CartesianGrid strokeDasharray="3 3" stroke="#ece5d8" />
                          <XAxis dataKey="timestamp" tickFormatter={(t) => new Date(t).getHours() + ':00'} tick={{ fontSize: 10, fill: '#6f5f48' }} />
                          <YAxis tick={{ fontSize: 10, fill: '#6f5f48' }} />
                          <Tooltip />
                          <Line type="monotone" dataKey="throughput" stroke="#0f766e" strokeWidth={2} dot={false} />
                        </LineChart>
                      </ResponsiveContainer>
                    </div>
                  </div>
                )}

                {/* 3. Node Inventory */}
                {currentVolumes[activeVolumeIndex]?.nodeInventory.length > 0 && (
                  <div className="border border-[#d8d0c1] rounded-xl overflow-hidden">
                    <div className="bg-[#faf8f3] border-b border-[#d8d0c1] px-5 py-4">
                      <h3 className="text-sm font-semibold uppercase tracking-wider text-[#6f5f48]">
                        Node Inventory List ({currentVolumes[activeVolumeIndex].nodeInventory.length} Nodes in this Volume)
                      </h3>
                    </div>
                    <div className="overflow-x-auto">
                      <table className="w-full text-left text-xs border-collapse">
                        <thead>
                          <tr className="bg-neutral-50 text-[#6f5f48] border-b border-[#d8d0c1] uppercase font-bold tracking-wider">
                            <th className="px-4 py-3">Label</th>
                            <th className="px-4 py-3">IP Address</th>
                            <th className="px-4 py-3">Location</th>
                            <th className="px-4 py-3">Uptime</th>
                            <th className="px-4 py-3">Firmware</th>
                            <th className="px-4 py-3">Status</th>
                          </tr>
                        </thead>
                        <tbody>
                          {currentVolumes[activeVolumeIndex].nodeInventory.map((node) => (
                            <tr key={node.id} className="border-b border-[#ece5d8] hover:bg-neutral-50">
                              <td className="px-4 py-3 font-semibold text-[#171512]">{node.label}</td>
                              <td className="px-4 py-3 monospace">{node.ipAddress}</td>
                              <td className="px-4 py-3 text-[#6f5f48]">{node.location}</td>
                              <td className="px-4 py-3">{node.uptime}</td>
                              <td className="px-4 py-3 monospace">{node.firmwareVersion}</td>
                              <td className="px-4 py-3">
                                <span className={`inline-block px-2.5 py-0.5 rounded-full font-bold ${
                                  node.status === 'online' ? 'bg-green-100 text-green-800' :
                                  node.status === 'offline' ? 'bg-red-100 text-red-800' : 'bg-yellow-100 text-yellow-800'
                                }`}>
                                  {node.status}
                                </span>
                              </td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>
                  </div>
                )}

                {/* 4. Alerts Log */}
                {currentVolumes[activeVolumeIndex]?.alerts.length > 0 && (
                  <div className="border border-[#d8d0c1] rounded-xl overflow-hidden">
                    <div className="bg-[#faf8f3] border-b border-[#d8d0c1] px-5 py-4">
                      <h3 className="text-sm font-semibold uppercase tracking-wider text-[#6f5f48]">
                        System Alerts Log ({currentVolumes[activeVolumeIndex].alerts.length} Alerts in this Volume)
                      </h3>
                    </div>
                    <div className="divide-y divide-[#ece5d8] max-h-[350px] overflow-y-auto">
                      {currentVolumes[activeVolumeIndex].alerts.map((alert) => (
                        <div key={alert.id} className="px-5 py-3 hover:bg-neutral-50 flex items-start gap-4 text-xs">
                          <span className={`px-2.5 py-0.5 rounded-full font-bold uppercase ${
                            alert.severity === 'critical' ? 'bg-red-100 text-red-800' :
                            alert.severity === 'warning' ? 'bg-yellow-100 text-yellow-800' : 'bg-blue-100 text-blue-800'
                          }`}>
                            {alert.severity}
                          </span>
                          <div className="flex-1">
                            <p className="font-semibold text-[#171512]">{alert.message}</p>
                            <p className="text-[10px] text-[#6f5f48] mt-0.5">{alert.timestamp}</p>
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            </div>
          </div>
        )}
      </div>

      {/* HIDDEN PRINT-ONLY CONTAINER (Rendered only during window.print()) */}
      {activeVolumeToPrint && (
        <div id={printContainerId} className="print-container hidden" style={{ display: 'none' }}>
          {/* Cover Page */}
          <div className="report-cover-page text-center py-20 border-b border-[#cccccc] break-after-page" style={{ height: '90%' }}>
            <h1 className="text-3xl font-bold uppercase tracking-widest text-neutral-800">Lumina Network</h1>
