import { renderHook, waitFor } from '@testing-library/react'
import { useWebSocket } from './useWebSocket'
import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest'

// Mock Sentry
vi.mock('@/src/lib/sentry/sentryClient', () => ({
  enqueueError: vi.fn(),
}))

// Mock WebSocket
class MockWebSocket {
  static CONNECTING = 0
  static OPEN = 1
  static CLOSING = 2
  static CLOSED = 3

  readyState = MockWebSocket.CONNECTING
  url: string
  protocols?: string | string[]

  onopen: ((event: Event) => void) | null = null
  onclose: ((event: Event) => void) | null = null
  onerror: ((event: Event) => void) | null = null
  onmessage: ((event: MessageEvent) => void) | null = null

  constructor(url: string, protocols?: string | string[]) {
    this.url = url
    this.protocols = protocols
  }

  send(data: string) {
    if (this.readyState !== MockWebSocket.OPEN) {
      throw new Error('WebSocket is not open')
    }
  }

  close() {
    this.readyState = MockWebSocket.CLOSED
    this.onclose?.(new Event('close'))
  }

  // Test helper methods
  simulateOpen() {
    this.readyState = MockWebSocket.OPEN
    this.onopen?.(new Event('open'))
  }

  simulateMessage(data: any) {
    this.readyState = MockWebSocket.OPEN
    this.onmessage?.(new MessageEvent('message', { data: JSON.stringify(data) }))
  }

  simulateError() {
    this.onerror?.(new Event('error'))
  }
}

// Store original WebSocket
const originalWebSocket = global.WebSocket

describe('useWebSocket', () => {
  let mockWs: MockWebSocket | null = null
  let onMessage: ReturnType<typeof vi.fn>

  beforeEach(() => {
    onMessage = vi.fn()
    mockWs = null

    // Replace global WebSocket with mock
    ;(global as any).WebSocket = class extends MockWebSocket {
      constructor(url: string, protocols?: string | string[]) {
        super(url, protocols)
        mockWs = this
      }
    }
  })

  afterEach(() => {
    ;(global as any).WebSocket = originalWebSocket
    vi.clearAllMocks()
  })

  it('should establish connection', async () => {
    const { result } = renderHook(() =>
      useWebSocket(
        {
          url: 'ws://localhost:8080',
          reconnect: false,
        },
        onMessage
      )
    )

    expect(result.current.state).toBe('connecting')

    // Simulate connection open
    mockWs?.simulateOpen()

    await waitFor(() => {
      expect(result.current.state).toBe('connected')
    })
  })

  /**
   * CRITICAL TEST: Multiple onopen events in rapid succession (2ms apart).
   * Verifies the connectionReady dedup flag prevents state corruption
   * and duplicate message queue processing.
   */
  it('should handle multiple onopen events (duplicate onopen dedup test)', async () => {
    const { result } = renderHook(() =>
      useWebSocket(
        {
          url: 'ws://localhost:8080',
          reconnect: false,
        },
        onMessage
      )
    )

    // Queue a message before connection
    result.current.send('test-message')

    expect(result.current.state).toBe('connecting')

    // Simulate first onopen (expected)
    mockWs?.simulateOpen()

    await waitFor(() => {
      expect(result.current.state).toBe('connected')
    })

    // Simulate second onopen 2ms later (Firefox bug scenario)
    // This should be ignored due to connectionReady dedup flag
    mockWs?.simulateOpen()

    // State should remain connected, not corrupted
    await waitFor(() => {
      expect(result.current.state).toBe('connected')
    })

    // Verify onopen only processed once (message queued once, not twice)
    expect(mockWs?.send).toHaveBeenCalledTimes(1)
  })

  /**
   * Test that 5 rapid onopen events (Firefox under poor network)
   * don't cause state issues or duplicate processing.
   */
  it('should handle 5 rapid onopen events without state corruption', async () => {
    const { result } = renderHook(() =>
      useWebSocket(
        {
          url: 'ws://localhost:8080',
          reconnect: false,
        },
        onMessage
      )
    )

    // Queue multiple messages
    result.current.send('msg-1')
    result.current.send('msg-2')

    // Simulate 5 rapid onopen events
    for (let i = 0; i < 5; i++) {
      mockWs?.simulateOpen()
    }

    await waitFor(() => {
      expect(result.current.state).toBe('connected')
    })

    // The queued messages should only be sent once
    // (dedup flag prevents re-processing)
    expect(mockWs?.send).toHaveBeenCalledTimes(2) // 2 queued messages

    // Verify reconnect attempts were reset (healthy connection)
    expect(result.current.reconnectAttempts).toBe(0)
  })

  /**
   * Test that onclose properly resets the dedup flag
   * so that a reconnection can process onopen normally.
   */
  it('should reset dedup flag on close, allowing reconnect to work', async () => {
    const { result } = renderHook(() =>
      useWebSocket(
        {
          url: 'ws://localhost:8080',
          reconnect: true,
          reconnectDelayMs: 100,
          maxReconnectAttempts: 1,
        },
        onMessage
      )
    )

    // First connection
    mockWs?.simulateOpen()

    await waitFor(() => {
      expect(result.current.state).toBe('connected')
    })

    // Close connection
    mockWs?.close()

    await waitFor(() => {
      expect(result.current.state).toBe('disconnected')
    })

    // Wait for reconnect
    vi.useFakeTimers()
    vi.advanceTimersByTime(100)

    // Simulate reconnect with new websocket
    const newMockWs = new MockWebSocket('ws://localhost:8080')
    ;(global as any).WebSocket = class {
      constructor() {
        return newMockWs
      }
    }

    // Simulate second connection
    newMockWs.simulateOpen()

    await waitFor(() => {
      expect(result.current.state).toBe('connected')
      expect(result.current.reconnectAttempts).toBe(0)
    })

    vi.useRealTimers()
  })

  it('should queue messages when disconnected', async () => {
    const { result } = renderHook(() =>
      useWebSocket(
        {
          url: 'ws://localhost:8080',
          reconnect: false,
        },
        onMessage
      )
    )

    // Send message while disconnected
    result.current.send('queued-message')

    // State should still be connecting
    expect(result.current.state).toBe('connecting')

    // Now connect
    mockWs?.simulateOpen()

    await waitFor(() => {
      expect(result.current.state).toBe('connected')
    })

    // Queued message should have been sent
    expect(mockWs?.send).toHaveBeenCalledWith(
      JSON.stringify('queued-message')
    )
  })

  it('should handle message reception', async () => {
    const { result } = renderHook(() =>
      useWebSocket(
        {
          url: 'ws://localhost:8080',
          reconnect: false,
        },
        onMessage
      )
    )

    mockWs?.simulateOpen()

    await waitFor(() => {
      expect(result.current.state).toBe('connected')
    })

    // Simulate incoming message
    mockWs?.simulateMessage({ type: 'test', payload: 'data' })

    await waitFor(() => {
      expect(onMessage).toHaveBeenCalledWith({
        type: 'test',
        payload: 'data',
      })
    })
  })

  it('should handle connection errors', async () => {
    const { result } = renderHook(() =>
      useWebSocket(
        {
          url: 'ws://localhost:8080',
          reconnect: false,
        },
        onMessage
      )
    )

    mockWs?.simulateError()

    await waitFor(() => {
      expect(result.current.state).toBe('error')
      expect(result.current.error).toBeDefined()
    })
  })

  it('should allow manual close', async () => {
    const { result } = renderHook(() =>
      useWebSocket(
        {
          url: 'ws://localhost:8080',
          reconnect: true,
        },
        onMessage
      )
    )

    mockWs?.simulateOpen()

    await waitFor(() => {
      expect(result.current.state).toBe('connected')
    })

    // Close connection
    result.current.close()

    await waitFor(() => {
      expect(result.current.state).toBe('disconnected')
    })

    // Should not attempt reconnection after manual close
    expect(result.current.reconnectAttempts).toBe(0)
  })
})

'use client'

import { useCallback, useEffect } from 'react'
import { useWebSocket } from './useWebSocket'

export interface BandwidthDataPoint {
  timestamp: number
  value: number
}

export interface UseBandwidthStreamProps {
  wsUrl: string
  onMessage: (data: BandwidthDataPoint) => void
  enabled?: boolean
}

export function useBandwidthStream({
  wsUrl,
  onMessage,
  enabled = true,
}: UseBandwidthStreamProps) {
  const handleMessage = useCallback(
    (data: any) => {
      if (!enabled) return
      // Support nested value/timestamp or direct format
      if (data && typeof data.value === 'number' && typeof data.timestamp === 'number') {
        onMessage({
          timestamp: data.timestamp,
          value: data.value,
        })
      } else if (data && typeof data.bandwidth === 'number') {
        onMessage({
          timestamp: data.timestamp || Date.now(),
          value: data.bandwidth,
        })
      }
    },
    [onMessage, enabled]
  )

  const isMock = typeof window !== 'undefined' && (wsUrl.includes('mock') || wsUrl.includes('localhost'))
  const wsConfig = isMock
    ? { url: 'ws://mock', reconnect: false }
    : { url: wsUrl, reconnect: true }

  const ws = useWebSocket<any>(wsConfig, isMock ? () => {} : handleMessage)

  // Listen for simulated/mock messages
  useEffect(() => {
    if (!isMock) return

    const handleMockEvent = (e: Event) => {
      const customEvent = e as CustomEvent<any>
      if (Array.isArray(customEvent.detail)) {
        // Handle burst of points
        customEvent.detail.forEach((pt) => handleMessage(pt))
      } else {
        handleMessage(customEvent.detail)
      }
    }

    window.addEventListener('mock-bandwidth-message', handleMockEvent)
    return () => {
      window.removeEventListener('mock-bandwidth-message', handleMockEvent)
    }
  }, [isMock, handleMessage])

  return ws
}

/**
 * useConnectionHealth - WebSocket health check with timer drift mitigation
 * 
 * Implements a monotonic deadline pattern to avoid timer drift from multiple
 * resetHealthTimer() calls during concurrent reconnections.
 * 
 * Features:
 * - Monotonic deadline pattern prevents timer drift
 * - Timer generation guard eliminates stale callback issues
 * - Secondary health check via ws events (error/close)
 * - Configurable ping/pong timeouts
 * - Automatic connection health tracking
 */

import { useCallback, useEffect, useRef, useState } from 'react'

export interface HealthCheckConfig {
  /** Ping interval in ms (default: 10000ms) */
  pingIntervalMs?: number
  /** Pong timeout in ms (default: 15000ms) */
  pongTimeoutMs?: number
  /** WebSocket instance to monitor */
  ws: WebSocket | null
  /** Callback when connection health status changes */
  onHealthChange?: (isHealthy: boolean) => void
}

export interface HealthCheckState {
  /** Whether connection is healthy */
  isHealthy: boolean
  /** Last time a pong was received */
  lastPongTime: number
  /** Last time a ping was sent */
  lastPingTime: number
  /** Number of missed pongs */
  missedPongCount: number
  /** Connection established time (for dedup tolerance) */
  connectedAt: number
}

export function useConnectionHealth(config: HealthCheckConfig) {
  const {
    pingIntervalMs = 10000,
    pongTimeoutMs = 15000,
    ws,
    onHealthChange,
  } = config

  const [health, setHealth] = useState<HealthCheckState>({
    isHealthy: true,
    lastPongTime: Date.now(),
    lastPingTime: Date.now(),
    missedPongCount: 0,
    connectedAt: Date.now(),
  })

  // Refs for monotonic deadline pattern
  const nextPingTimeRef = useRef(Date.now() + pingIntervalMs)
  const timerGenerationRef = useRef(0)
  const healthCheckTimeoutRef = useRef<NodeJS.Timeout | null>(null)
  const lastPongTimeRef = useRef(Date.now())
  const missedPongCountRef = useRef(0)
  const isMountedRef = useRef(true)
  const lastHealthStatusRef = useRef(true)

  /**
   * Reset the health timer to a new deadline.
   * Instead of clearing/recreating timers, we just update the deadline.
   * Increment generation to invalidate stale callbacks.
   */
  const resetHealthTimer = useCallback(() => {
    if (!isMountedRef.current) return

    // Update next ping deadline (monotonic deadline pattern)
    nextPingTimeRef.current = Date.now() + pingIntervalMs

    // Increment generation to guard against stale callbacks
    // When this function is called multiple times rapidly (duplicate onopen),
    // the generation increments each time. Stale callbacks check their generation
    // and return early if it doesn't match.
    timerGenerationRef.current += 1
    const currentGeneration = timerGenerationRef.current

    // Reset missed pong count on timer reset
    missedPongCountRef.current = 0

    // Cancel existing timeout if any
    if (healthCheckTimeoutRef.current) {
      clearTimeout(healthCheckTimeoutRef.current)
    }

    // Schedule next health check - this timeout will check if we need to ping
    healthCheckTimeoutRef.current = setTimeout(() => {
      // Guard: check if this callback is still valid (not superseded by reset)
      if (currentGeneration !== timerGenerationRef.current) {
        return
      }

      if (!isMountedRef.current || !ws) return

      performHealthCheck(currentGeneration)
    }, pingIntervalMs)
  }, [pingIntervalMs, ws])

  /**
   * Perform the actual health check.
   * Uses monotonic deadline to determine if we should ping,
   * avoiding drift from multiple timer resets.
   */
  const performHealthCheck = useCallback(
    (generation: number) => {
      if (!isMountedRef.current || !ws) return

      // Guard: this callback should not run if generation has changed
      if (generation !== timerGenerationRef.current) {
        return
      }

      const now = Date.now()
      const timeSinceLastPong = now - lastPongTimeRef.current
      const timeUntilNextPing = nextPingTimeRef.current - now

      // Check if we're past the deadline
      if (timeUntilNextPing <= 0) {
        // Time to send a ping
        if (ws.readyState === WebSocket.OPEN) {
          try {
            // Send a ping message (frame opcode 0x9, but most servers expect a message)
            ws.send(JSON.stringify({ type: 'ping', timestamp: now }))
            lastPongTimeRef.current = now

            setHealth((prev) => ({
              ...prev,
              lastPingTime: now,
            }))
          } catch (err) {
            console.error('[useConnectionHealth] Failed to send ping:', err)
          }
        }

        // Reschedule for next ping
        nextPingTimeRef.current = now + pingIntervalMs
        healthCheckTimeoutRef.current = setTimeout(() => {
          if (generation === timerGenerationRef.current && isMountedRef.current && ws) {
            performHealthCheck(generation)
          }
        }, pingIntervalMs)
      } else {
        // Not yet time to ping, reschedule closer to deadline
        healthCheckTimeoutRef.current = setTimeout(() => {
          if (generation === timerGenerationRef.current && isMountedRef.current && ws) {
            performHealthCheck(generation)
          }
        }, Math.min(timeUntilNextPing, 1000)) // Check every 1s max
      }

      // Secondary health check: check if we've missed a pong
      if (timeSinceLastPong > pongTimeoutMs) {
        missedPongCountRef.current += 1

        // Only mark unhealthy if we've truly missed multiple pongs
        // and no error/close event has been received
        if (missedPongCountRef.current > 2) {
          const isHealthy = false
          if (lastHealthStatusRef.current !== isHealthy) {
            lastHealthStatusRef.current = isHealthy
            onHealthChange?.(isHealthy)
            setHealth((prev) => ({
              ...prev,
              isHealthy,
              missedPongCount: missedPongCountRef.current,
            }))
          }
        }
      } else if (missedPongCountRef.current > 0) {
        // Pong was received, reset health
        missedPongCountRef.current = 0
        const isHealthy = true
        if (lastHealthStatusRef.current !== isHealthy) {
          lastHealthStatusRef.current = isHealthy
          onHealthChange?.(isHealthy)
          setHealth((prev) => ({
            ...prev,
            isHealthy,
            missedPongCount: 0,
          }))
        }
      }
    },
    [ws, pongTimeoutMs, onHealthChange]
  )

  /**
   * Handle pong response from server.
   * This resets the pong timeout counter.
   */
  const handlePong = useCallback(() => {
    if (!isMountedRef.current) return

    const now = Date.now()
    lastPongTimeRef.current = now
    missedPongCountRef.current = 0

    // Mark as healthy
    if (!lastHealthStatusRef.current) {
      lastHealthStatusRef.current = true
      onHealthChange?.(true)
    }

    setHealth((prev) => ({
      ...prev,
      isHealthy: true,
      lastPongTime: now,
      missedPongCount: 0,
    }))
  }, [onHealthChange])

  /**
   * Secondary health check: WebSocket error/close listener.
   * Immediately marks connection as unhealthy without waiting for missed pongs.
   */
  const setupEventListeners = useCallback(() => {
    if (!ws) return

    const handleError = () => {
      if (!isMountedRef.current) return

      const isHealthy = false
      if (lastHealthStatusRef.current !== isHealthy) {
        lastHealthStatusRef.current = isHealthy
        onHealthChange?.(isHealthy)
        setHealth((prev) => ({
          ...prev,
          isHealthy,
        }))
      }
    }

    const handleClose = () => {
      if (!isMountedRef.current) return

      const isHealthy = false
      if (lastHealthStatusRef.current !== isHealthy) {
        lastHealthStatusRef.current = isHealthy
        onHealthChange?.(isHealthy)
        setHealth((prev) => ({
          ...prev,
          isHealthy,
        }))
      }
    }

    ws.addEventListener('error', handleError)
    ws.addEventListener('close', handleClose)

    return () => {
      ws.removeEventListener('error', handleError)
      ws.removeEventListener('close', handleClose)
    }
  }, [ws, onHealthChange])

  /**
   * Initialize health check when WebSocket connection opens.
   */
  const startHealthCheck = useCallback(() => {
    if (!isMountedRef.current || !ws) return

    const now = Date.now()
    lastPongTimeRef.current = now
    nextPingTimeRef.current = now + pingIntervalMs
    missedPongCountRef.current = 0

    setHealth({
      isHealthy: true,
      lastPongTime: now,
      lastPingTime: now,
      missedPongCount: 0,
      connectedAt: now,
    })

    resetHealthTimer()
  }, [ws, pingIntervalMs, resetHealthTimer])

  // Setup event listeners for secondary health checks
  useEffect(() => {
    return setupEventListeners()
  }, [setupEventListeners])

  // Initialize health check when ws connects
  useEffect(() => {
    if (ws?.readyState === WebSocket.OPEN) {
      startHealthCheck()
    }

    return () => {
      if (healthCheckTimeoutRef.current) {
        clearTimeout(healthCheckTimeoutRef.current)
      }
    }
  }, [ws, startHealthCheck])

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      isMountedRef.current = false
      if (healthCheckTimeoutRef.current) {
        clearTimeout(healthCheckTimeoutRef.current)
      }
    }
  }, [])

  return {
    health,
    resetHealthTimer,
    handlePong,
  }
}

import { useState, useRef, useCallback } from 'react';

type ExportStatus = 'idle' | 'initializing' | 'downloading' | 'complete' | 'error' | 'aborted';

interface ExportState {
  status: ExportStatus;
  progress: number;
  bytesReceived: number;
  bytesTotal: number | null;
  error: Error | null;
  usingFallback: boolean;
}

function triggerBlobDownload(blob: Blob, filename: string) {
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

export function useExportData() {
  const [state, setState] = useState<ExportState>({
    status: 'idle',
    progress: 0,
    bytesReceived: 0,
    bytesTotal: null,
    error: null,
    usingFallback: false,
  });
  
  const swRegistrationRef = useRef<ServiceWorkerRegistration | null>(null);
  const messageChannelRef = useRef<MessageChannel | null>(null);
  const abortControllerRef = useRef<AbortController | null>(null);
  const chunksRef = useRef<BlobPart[]>([]);
  const formatRef = useRef<'csv' | 'json'>('csv');

  const updateState = useCallback((updates: Partial<ExportState>) => {
    setState(prev => ({ ...prev, ...updates }));
  }, []);

  const handleServiceWorkerMessage = useCallback((event: MessageEvent) => {
    const { type, bytesReceived, bytesWritten, bytesTotal, error } = event.data;

    switch (type) {
      case 'request-file-handle':
        (async () => {
          try {
            const fileHandle = await window.showSaveFilePicker({
              suggestedName: `node-telemetry-${Date.now()}.csv`,
              types: [
                {
                  description: 'CSV Files',
                  accept: { 'text/csv': ['.csv'] },
                },
                {
                  description: 'JSON Files',
                  accept: { 'application/json': ['.json'] },
                },
              ],
            });

            if (event.ports && event.ports[0]) {
              event.ports[0].postMessage({
                type: 'init-file-stream',
                fileHandle,
              });
            }
          } catch (err) {
            if (err instanceof Error && err.name === 'AbortError') {
              updateState({ status: 'aborted' });
            } else {
              updateState({ status: 'error', error: err as Error });
            }
          }
        })();
        break;

      case 'progress':
        const progress = state.bytesTotal ? Math.min(100, (bytesReceived / state.bytesTotal) * 100) : 0;
        updateState({
          status: 'downloading',
          progress,
          bytesReceived,
        });
        break;

      case 'export-complete':
        updateState({
          status: 'complete',
          progress: 100,
          bytesReceived: bytesWritten,
        });
        break;

      case 'export-aborted':
        updateState({ status: 'aborted' });
        break;

      case 'export-error':
        updateState({
          status: 'error',
          error: error || new Error('Unknown export error'),
        });
        break;
    }
  }, [state.bytesTotal, updateState]);

  const startExport = useCallback(async (url: string, options: { format: 'csv' | 'json'; startDate: Date; endDate: Date; bytesTotal?: number }) => {
    if (!('serviceWorker' in navigator)) {
      throw new Error('Service Workers are not supported in this browser');
    }

    updateState({
      status: 'initializing',
      progress: 0,
      bytesReceived: 0,
      bytesTotal: options.bytesTotal || null,
      error: null,
      usingFallback: false,
    });
    formatRef.current = options.format;
    chunksRef.current = [];

    try {
      // Check if File System Access API is available
      const hasFileSystemAccess = 'showSaveFilePicker' in window;
      
      if (!hasFileSystemAccess) {
        // Fallback: use traditional blob download
        updateState({ usingFallback: true, status: 'downloading' });
        
        abortControllerRef.current = new AbortController();
        
        const response = await fetch(url, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({
            format: options.format,
            startDate: options.startDate.toISOString(),
            endDate: options.endDate.toISOString(),
          }),
          signal: abortControllerRef.current.signal,
        });

        if (!response.ok) {
          throw new Error(`Export failed with status: ${response.status}`);
        }

        const reader = response.body?.getReader();
        if (!reader) {
          throw new Error('Response body is not readable');
        }

        let received = 0;
        while (true) {
          const { done, value } = await reader.read();
          if (done) break;
          if (value) {
            chunksRef.current.push(value);
            received += value.length;
            const progress = options.bytesTotal ? Math.min(100, (received / options.bytesTotal) * 100) : 0;
            updateState({ bytesReceived: received, progress });
          }
        }

        // Create blob and trigger download
        const blob = new Blob(chunksRef.current, {
          type: options.format === 'csv' ? 'text/csv' : 'application/json',
        });
        const filename = `node-telemetry-${Date.now()}.${options.format}`;
        triggerBlobDownload(blob, filename);
        
        updateState({ status: 'complete', progress: 100, bytesReceived: received });
      } else {
        // Use File System Access API via service worker
        const registration = await navigator.serviceWorker.ready;
        swRegistrationRef.current = registration;
        
        abortControllerRef.current = new AbortController();
        messageChannelRef.current = new MessageChannel();

        navigator.serviceWorker.addEventListener('message', handleServiceWorkerMessage);

        const response = await fetch(url, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'X-Stream-Export': 'true',
          },
          body: JSON.stringify({
            format: options.format,
            startDate: options.startDate.toISOString(),
            endDate: options.endDate.toISOString(),
          }),
          signal: abortControllerRef.current.signal,
        });

        if (!response.ok) {
          throw new Error(`Export failed with status: ${response.status}`);
        }
      }
    } catch (error) {
      if (error instanceof Error && error.name === 'AbortError') {
        updateState({ status: 'aborted' });
      } else {
        updateState({ status: 'error', error: error as Error });
      }
    }
  }, [updateState, handleServiceWorkerMessage]);

  const abort = useCallback(() => {
    if (abortControllerRef.current) {
      abortControllerRef.current.abort();
    }
    if (swRegistrationRef.current?.active) {
      swRegistrationRef.current.active.postMessage({ type: 'abort-export' });
    }
    updateState({ status: 'aborted' });
  }, [updateState]);

  const reset = useCallback(() => {
    setState({
      status: 'idle',
      progress: 0,
      bytesReceived: 0,
      bytesTotal: null,
      error: null,
      usingFallback: false,
    });
    chunksRef.current = [];
  }, []);

  return {
    state,
    startExport,
    abort,
    reset,
  };
}

import { useMemo } from 'react';
import * as d3 from 'd3';

export interface FlatNetworkNode {
  id: string;
  name: string;
  type: 'region' | 'facility' | 'rack' | 'node' | 'sensor';
  status: 'healthy' | 'warning' | 'critical';
  region?: string;
  facility?: string;
  rack?: string;
  node?: string;
}

interface HierarchyRawNode {
  id: string;
  name: string;
  status: 'healthy' | 'warning' | 'critical';
  children?: Map<string, HierarchyRawNode> | HierarchyRawNode[];
}

export const useHierarchicalData = (nodeList: FlatNetworkNode[]) => {
  return useMemo(() => {
    if (!nodeList || nodeList.length === 0) return null;

    // Root structure
    const rootData: HierarchyRawNode = {
      id: 'root',
      name: 'Network Root',
      status: 'healthy',
      children: new Map(),
    };

    // Helper to resolve status aggregation up the tree
    const worstStatus = (s1: string, s2: string): 'healthy' | 'warning' | 'critical' => {
      if (s1 === 'critical' || s2 === 'critical') return 'critical';
      if (s1 === 'warning' || s2 === 'warning') return 'warning';
      return 'healthy';
    };

    // Build the map-based tree structure
    nodeList.forEach((item) => {
      const regionName = item.region || 'Uncategorized';
      const facilityName = item.facility || 'Uncategorized';
      const rackName = item.rack || 'Uncategorized';
      const nodeName = item.node || 'Uncategorized';

      // 1. Region Level
      let region = (rootData.children as Map<string, HierarchyRawNode>).get(regionName);
      if (!region) {
        region = { id: `region-${regionName}`, name: regionName, status: 'healthy', children: new Map() };
        (rootData.children as Map<string, HierarchyRawNode>).set(regionName, region);
      }
      region.status = worstStatus(region.status, item.status);

      // 2. Facility Level
      let facility = (region.children as Map<string, HierarchyRawNode>).get(facilityName);
      if (!facility) {
        facility = { id: `facility-${facilityName}`, name: facilityName, status: 'healthy', children: new Map() };
        (region.children as Map<string, HierarchyRawNode>).set(facilityName, facility);
      }
      facility.status = worstStatus(facility.status, item.status);

      // 3. Rack Level
      let rack = (facility.children as Map<string, HierarchyRawNode>).get(rackName);
      if (!rack) {
        rack = { id: `rack-${rackName}`, name: rackName, status: 'healthy', children: new Map() };
        (facility.children as Map<string, HierarchyRawNode>).set(rackName, rack);
      }
      rack.status = worstStatus(rack.status, item.status);

      // 4. Node Level
      let node = (rack.children as Map<string, HierarchyRawNode>).get(nodeName);
      if (!node) {
        node = { id: `node-${nodeName}`, name: nodeName, status: 'healthy', children: new Map() };
        (rack.children as Map<string, HierarchyRawNode>).set(nodeName, node);
      }
      node.status = worstStatus(node.status, item.status);

      // 5. Sensor Level (Leaf Node)
      if (item.type === 'sensor') {
        const sensorMap = node.children as Map<string, HierarchyRawNode>;
        sensorMap.set(item.id, { id: item.id, name: item.name, status: item.status, children: [] });
      }
    });

    // Recursively convert Maps to Arrays for D3 compatibility
    const formatChildren = (node: HierarchyRawNode): any => {
      if (node.children instanceof Map) {
        node.children = Array.from(node.children.values()).map(formatChildren);
      }
      return node;
    };

    const formattedRoot = formatChildren(rootData);
    
    // Create D3 Hierarchy
    return d3.hierarchy(formattedRoot);
  }, [nodeList]);
};

'use client'

import { useCallback, useEffect, useRef, useState } from 'react'
import { computeAggregation } from '@/src/lib/aggregators'
import type {
  AnalyticsDataPoint,
  AggregatedResult,
  AggregationConfig,
  AnalyticsWorkerMessage,
} from '@/src/types/network'

interface PendingRequest {
  resolve: (result: AggregatedResult) => void
  reject: (err: unknown) => void
}

export function useNetworkAnalytics() {
  const workerRef = useRef<Worker | null>(null)
  const pendingRef = useRef<Map<string, PendingRequest>>(new Map())
  const [workerAvailable, setWorkerAvailable] = useState<boolean | null>(null)
  const corrIdCounter = useRef(0)

  const getWorker = useCallback((): Worker | null => {
    if (workerRef.current) return workerRef.current

    try {
      const w = new Worker(
        new URL('@/src/workers/analyticsProcessor.worker', import.meta.url),
        { type: 'module' },
      )

      w.onmessage = (e: MessageEvent<AnalyticsWorkerMessage>) => {
        if (e.data.type === 'result') {
          const { result, correlationId } = e.data.payload
          const pending = pendingRef.current.get(correlationId)
          if (pending) {
            pending.resolve(result)
            pendingRef.current.delete(correlationId)
          }
        }
      }

      w.onerror = (err) => {
        const entries = [...pendingRef.current.entries()]
        pendingRef.current.clear()
        for (const [, pending] of entries) {
          pending.reject(err)
        }
      }

      workerRef.current = w
      setWorkerAvailable(true)
      return w
    } catch {
      setWorkerAvailable(false)
      return null
    }
  }, [])

  const aggregate = useCallback(
    async (
      data: AnalyticsDataPoint[],
      config: AggregationConfig,
    ): Promise<AggregatedResult> => {
      const worker = getWorker()

      if (!worker) {
        return computeAggregation(data, config)
      }

      return new Promise<AggregatedResult>((resolve, reject) => {
        const correlationId = `${Date.now()}-${corrIdCounter.current++}`
        pendingRef.current.set(correlationId, { resolve, reject })

        const transferable = new ArrayBuffer(data.length * 32)
        worker.postMessage(
          {
            type: 'aggregate',
            payload: { data, config, correlationId },
          } satisfies AnalyticsWorkerMessage,
          [transferable],
        )
      })
    },
    [getWorker],
  )

  useEffect(() => {
    return () => {
      if (workerRef.current) {
        workerRef.current.terminate()
        workerRef.current = null
      }
      pendingRef.current.clear()
    }
  }, [])

  return { aggregate, workerAvailable }
}

"use client";

import { useCallback, useMemo, useState } from "react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import type {
  StakingPortfolio,
  UnstakeRequest,
  RewardHistoryPage,
  StakingChartPoint,
} from "@/src/lib/staking/types";
import {
  formatCooldownTime,
  getCooldownEnd,
  getCooldownRemaining,
  generateMockChartData,
} from "@/src/lib/staking/stakingCalculator";

const MOCK_STAKED = 5_000_000_000_000n;
const MOCK_PENDING = 125_000_000_000n;
const DEFAULT_APR = 1200;

export function useStaking(walletAddress?: string) {
  const queryClient = useQueryClient();
  const [isSubmitting, setIsSubmitting] = useState(false);

  const portfolioQueryKey = useMemo(
    () => ["staking", "portfolio", walletAddress],
    [walletAddress],
  );

  const historyQueryKey = useMemo(
    () => ["staking", "history", walletAddress],
    [walletAddress],
  );

  const unstakeRequestsQueryKey = useMemo(
    () => ["staking", "unstake-requests", walletAddress],
    [walletAddress],
  );

  const chartDataQueryKey = useMemo(
    () => ["staking", "chart", walletAddress],
    [walletAddress],
  );

  const { data: portfolio, isLoading: portfolioLoading } = useQuery({
    queryKey: portfolioQueryKey,
    queryFn: async (): Promise<StakingPortfolio> => {
      const nextClaim = Date.now() + 7 * 86_400_000;
      return {
        totalStaked: MOCK_STAKED,
        aprBps: DEFAULT_APR,
        userStake: walletAddress ? MOCK_STAKED : 0n,
        pendingRewards: MOCK_PENDING,
        nextRewardClaimDate: nextClaim,
      };
    },
    enabled: !!walletAddress,
    staleTime: 30_000,
  });

  const { data: stakeHistory, isLoading: historyLoading } = useQuery({
    queryKey: historyQueryKey,
    queryFn: async (): Promise<RewardHistoryPage> => {
      return {
        records: [],
        totalRecords: 0,
        page: 1,
        pageSize: 10,
      };
    },
    enabled: !!walletAddress,
    staleTime: 30_000,
  });

  const { data: unstakeRequests, isLoading: unstakeLoading } = useQuery({
    queryKey: unstakeRequestsQueryKey,
    queryFn: async (): Promise<UnstakeRequest[]> => {
      return [];
    },
    enabled: !!walletAddress,
    staleTime: 30_000,
  });

  const { data: chartData, isLoading: chartLoading } = useQuery({
    queryKey: chartDataQueryKey,
    queryFn: async (): Promise<StakingChartPoint[]> => {
      return generateMockChartData(30);
    },
    enabled: !!walletAddress,
    staleTime: 60_000,
  });

  const approve = useCallback(async (_amount: bigint): Promise<boolean> => {
    setIsSubmitting(true);
    try {
      await new Promise((r) => setTimeout(r, 1000));
      return true;
    } finally {
      setIsSubmitting(false);
    }
  }, []);

  const stake = useCallback(
    async (_amount: bigint): Promise<boolean> => {
      setIsSubmitting(true);
      try {
        await new Promise((r) => setTimeout(r, 1500));
        queryClient.invalidateQueries({ queryKey: portfolioQueryKey });
        queryClient.invalidateQueries({ queryKey: chartDataQueryKey });
        return true;
      } finally {
        setIsSubmitting(false);
      }
    },
    [queryClient, portfolioQueryKey, chartDataQueryKey],
  );

  const requestUnstake = useCallback(
    async (amount: bigint): Promise<boolean> => {
      setIsSubmitting(true);
      try {
        await new Promise((r) => setTimeout(r, 1500));
        const now = Date.now();
        const newRequest: UnstakeRequest = {
          amount,
          walletAddress: walletAddress ?? "",
          requestedAt: now,
          cooldownEndsAt: getCooldownEnd(now),
          status: "pending",
        };
        queryClient.setQueryData<UnstakeRequest[]>(
          unstakeRequestsQueryKey,
          (prev) => [...(prev ?? []), newRequest],
        );
        queryClient.invalidateQueries({ queryKey: portfolioQueryKey });
        return true;
      } finally {
        setIsSubmitting(false);
      }
    },
    [walletAddress, queryClient, portfolioQueryKey, unstakeRequestsQueryKey],
  );

  const claimRewards = useCallback(async (): Promise<boolean> => {
    setIsSubmitting(true);
    try {
      await new Promise((r) => setTimeout(r, 1500));
      queryClient.invalidateQueries({ queryKey: portfolioQueryKey });
      return true;
    } finally {
      setIsSubmitting(false);
    }
  }, [queryClient, portfolioQueryKey]);

  const claimUnstake = useCallback(
    async (requestId: string): Promise<boolean> => {
      setIsSubmitting(true);
      try {
        await new Promise((r) => setTimeout(r, 1500));
        queryClient.setQueryData<UnstakeRequest[]>(
          unstakeRequestsQueryKey,
          (prev) =>
            (prev ?? []).map((r) =>
              r.requestedAt.toString() === requestId
                ? { ...r, status: "claimed" as const }
                : r,
            ),
        );
        return true;
      } finally {
        setIsSubmitting(false);
      }
    },
    [queryClient, unstakeRequestsQueryKey],
  );

  const cooldownInfo = useMemo(() => {
    if (!unstakeRequests || unstakeRequests.length === 0) return null;
    const pending = unstakeRequests.filter((r) => r.status !== "claimed");
    if (pending.length === 0) return null;
    const latest = pending[pending.length - 1];
    const remaining = getCooldownRemaining(latest);
    return {
      remaining,
      formatted: formatCooldownTime(remaining),
      isComplete: remaining <= 0,
      request: latest,
    };
  }, [unstakeRequests]);

  const fetchHistoryPage = useCallback(
    async (page: number, pageSize: number = 10): Promise<RewardHistoryPage> => {
      const start = (page - 1) * pageSize;
      const records = [];
      for (let i = 0; i < pageSize; i++) {
        records.push({
          id: `rec-${start + i}`,
          amount: BigInt(Math.floor(Math.random() * 1_000_000_000_000)),
          timestamp: Date.now() - i * 86_400_000,
          type: (["stake", "unstake", "reward"] as const)[i % 3],
          txHash: `0x${Math.random().toString(16).slice(2, 18)}`,
        });
      }
      return { records, totalRecords: 50, page, pageSize };
    },
    [],
  );

  return {
    portfolio,
    portfolioLoading,
    stakeHistory,
    historyLoading,
    unstakeRequests,
    unstakeLoading,
    chartData,
    chartLoading,
    isSubmitting,
    cooldownInfo,
    approve,
    stake,
    requestUnstake,
    claimRewards,
    claimUnstake,
    fetchHistoryPage,
  };
}

/**
 * useWebSocket - Generic WebSocket connection hook
 * 
 * Features:
 * - Automatic reconnection with exponential backoff
 * - Connection state tracking
 * - Message queuing during disconnection
 * - Clean teardown on unmount
 * - Type-safe message handling
 */

import { useCallback, useEffect, useRef, useState } from 'react'
import { enqueueError } from '@/src/lib/sentry/sentryClient'

export type ConnectionState = 'connecting' | 'connected' | 'disconnected' | 'error'

export interface WebSocketConfig {
  /** WebSocket URL */
  url: string
  /** Reconnection strategy */
  reconnect?: boolean
  /** Maximum reconnection attempts (0 = infinite) */
  maxReconnectAttempts?: number
  /** Initial reconnection delay in ms */
  reconnectDelayMs?: number
  /** Maximum reconnection delay in ms */
  maxReconnectDelayMs?: number
  /** Protocols to use */
  protocols?: string | string[]
}

export interface UseWebSocketReturn<T> {
  /** Current connection state */
  state: ConnectionState
  /** Send a message (queued if disconnected) */
  send: (message: string | object) => void
  /** Manually close connection */
  close: () => void
  /** Manually reconnect */
  reconnect: () => void
  /** Last error */
  error: Event | null
  /** Number of reconnection attempts */
  reconnectAttempts: number
}

export function useWebSocket<T = unknown>(
  config: WebSocketConfig,
  onMessage: (data: T) => void
): UseWebSocketReturn<T> {
  const {
    url,
    reconnect = true,
    maxReconnectAttempts = 5,
    reconnectDelayMs = 1000,
    maxReconnectDelayMs = 30000,
    protocols,
  } = config

  const [state, setState] = useState<ConnectionState>('connecting')
  const [error, setError] = useState<Event | null>(null)
  const [reconnectAttempts, setReconnectAttempts] = useState(0)

  const wsRef = useRef<WebSocket | null>(null)
  const reconnectTimeoutRef = useRef<NodeJS.Timeout | null>(null)
  const messageQueueRef = useRef<string[]>([])
  const isMountedRef = useRef(true)
  const isManualCloseRef = useRef(false)
  const connectionReadyRef = useRef(false) // Dedup flag to prevent multiple onopen events

  // Calculate exponential backoff delay
  const getReconnectDelay = useCallback((attempt: number): number => {
    const delay = reconnectDelayMs * Math.pow(2, attempt)
    return Math.min(delay, maxReconnectDelayMs)
  }, [reconnectDelayMs, maxReconnectDelayMs])

  // Create WebSocket connection
  const connect = useCallback(() => {
    if (!isMountedRef.current) return

    try {
      setState('connecting')
      setError(null)

      const ws = protocols 
        ? new WebSocket(url, protocols)
        : new WebSocket(url)

      ws.onopen = () => {
        if (!isMountedRef.current) return
        
        // Dedup: ignore duplicate onopen events (e.g., Firefox browser retry logic)
        // Set flag on first onopen, subsequent onopen events are ignored
        if (connectionReadyRef.current === true) {
          console.warn('[useWebSocket] Ignoring duplicate onopen event')
          return
        }
        
        connectionReadyRef.current = true
        setState('connected')
        setReconnectAttempts(0)

        // Send any queued messages
        while (messageQueueRef.current.length > 0) {
          const message = messageQueueRef.current.shift()
          if (message) ws.send(message)
        }
      }

      ws.onmessage = (event: MessageEvent) => {
        if (!isMountedRef.current) return

        try {
          const data = typeof event.data === 'string' 
            ? JSON.parse(event.data) 
            : event.data
          onMessage(data as T)
        } catch (err) {
          console.error('[useWebSocket] Failed to parse message:', err)
        }
      }

      ws.onerror = (event: Event) => {
        if (!isMountedRef.current) return
        
        setState('error')
        setError(event)
        console.error('[useWebSocket] Connection error:', event)
        void enqueueError(new Error(`WebSocket connection error: ${url}`), {
          component: 'useWebSocket',
          tags: { transport: 'websocket' },
          extra: { url, type: event.type },
        })
      }

      ws.onclose = () => {
        if (!isMountedRef.current || isManualCloseRef.current) {
          setState('disconnected')
          connectionReadyRef.current = false
          return
        }

        connectionReadyRef.current = false
        setState('disconnected')

        // Attempt reconnection if enabled
        if (reconnect) {
          const attempts = reconnectAttempts + 1
          
          if (maxReconnectAttempts === 0 || attempts <= maxReconnectAttempts) {
            const delay = getReconnectDelay(attempts)
            
            console.log(
              `[useWebSocket] Reconnecting in ${delay}ms (attempt ${attempts})`
            )
            
            setReconnectAttempts(attempts)
            
            reconnectTimeoutRef.current = setTimeout(() => {
              if (isMountedRef.current) {
                connect()
              }
            }, delay)
          } else {
            console.error(
              `[useWebSocket] Max reconnection attempts (${maxReconnectAttempts}) reached`
            )
            void enqueueError(new Error(`WebSocket connection dropped: ${url}`), {
              component: 'useWebSocket',
              tags: { transport: 'websocket' },
              extra: { url, reconnectAttempts: attempts },
            })
          }
        }
      }

      wsRef.current = ws
    } catch (err) {
      console.error('[useWebSocket] Failed to create connection:', err)
      void enqueueError(err, {
        component: 'useWebSocket',
        tags: { transport: 'websocket' },
        extra: { url },
      })
      setState('error')
    }
  }, [url, protocols, reconnect, maxReconnectAttempts, getReconnectDelay, reconnectAttempts, onMessage])

  // Send message
  const send = useCallback((message: string | object) => {
    const payload = typeof message === 'string' ? message : JSON.stringify(message)

    if (wsRef.current?.readyState === WebSocket.OPEN) {
      wsRef.current.send(payload)
    } else {
      // Queue message if not connected
      messageQueueRef.current.push(payload)
    }
  }, [])

  // Close connection
  const closeConnection = useCallback(() => {
    isManualCloseRef.current = true
    
    if (reconnectTimeoutRef.current) {
      clearTimeout(reconnectTimeoutRef.current)
      reconnectTimeoutRef.current = null
    }

    if (wsRef.current) {
      wsRef.current.close()
      wsRef.current = null
    }

    setState('disconnected')
    messageQueueRef.current = []
  }, [])

  // Manual reconnect
  const manualReconnect = useCallback(() => {
    isManualCloseRef.current = false
    setReconnectAttempts(0)
    closeConnection()
    connect()
  }, [connect, closeConnection])

  // Initial connection
  useEffect(() => {
    connect()

    return () => {
      isMountedRef.current = false
      
      if (reconnectTimeoutRef.current) {
        clearTimeout(reconnectTimeoutRef.current)
      }
      
      if (wsRef.current) {
        wsRef.current.close()
      }
    }
  }, [connect])

  return {
    state,
    send,
    close: closeConnection,
    reconnect: manualReconnect,
    error,
    reconnectAttempts,
  }
}

