"use client";

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useRef,
  useState,
} from "react";
import type { Locale, TranslationMap } from "./types";

const STORAGE_KEY = "lumina-locale";
const DEFAULT_LOCALE: Locale = "en-US";

function getStoredLocale(): Locale {
  if (typeof window === "undefined") return DEFAULT_LOCALE;
  try {
    const stored = localStorage.getItem(STORAGE_KEY);
    if (stored && isSupportedLocale(stored)) return stored as Locale;
  } catch {}
  return DEFAULT_LOCALE;
}

function isSupportedLocale(locale: string): locale is Locale {
  return [
    "en-US",
    "zh-CN",
    "ja-JP",
    "ko-KR",
    "ru-RU",
    "ar-SA",
    "he-IL",
    "es-ES",
    "pt-BR",
  ].includes(locale);
}

const RTL_LOCALES = new Set(["ar-SA", "he-IL"]);

interface I18nContextValue {
  locale: Locale;
  setLocale: (locale: Locale) => void;
  t: (key: string, params?: Record<string, string | number>) => string;
  translations: TranslationMap;
  isLoaded: boolean;
}

const I18nContext = createContext<I18nContextValue | null>(null);

export function I18nProvider({ children }: { children: React.ReactNode }) {
  const [locale, setLocaleState] = useState<Locale>(DEFAULT_LOCALE);
  const [translations, setTranslations] = useState<TranslationMap>({});
  const [isLoaded, setIsLoaded] = useState(false);
  const cacheRef = useRef<Map<string, TranslationMap>>(new Map());
  const mountedRef = useRef(false);

  useEffect(() => {
    mountedRef.current = true;
    const initial = getStoredLocale();
    loadLocale(initial);
    return () => {
      mountedRef.current = false;
    };
  }, []);

  const loadLocale = useCallback(async (loc: Locale) => {
    const cached = cacheRef.current.get(loc);
    if (cached) {
      if (mountedRef.current) {
        setTranslations(cached);
        setIsLoaded(true);
      }
      return;
    }

    try {
      const mod = await import(`./locales/${loc}.json`);
      const map = mod.default || mod;
      cacheRef.current.set(loc, map);
      if (mountedRef.current) {
        setTranslations(map);
        setIsLoaded(true);
      }
    } catch {
      if (loc !== DEFAULT_LOCALE) {
        const fallback = cacheRef.current.get(DEFAULT_LOCALE);
        if (fallback) {
          if (mountedRef.current) {
            setTranslations(fallback);
            setIsLoaded(true);
          }
          return;
        }
        try {
          const fallbackMod = await import(`./locales/${DEFAULT_LOCALE}.json`);
          const fallbackMap = fallbackMod.default || fallbackMod;
          cacheRef.current.set(DEFAULT_LOCALE, fallbackMap);
          if (mountedRef.current) {
            setTranslations(fallbackMap);
            setIsLoaded(true);
          }
        } catch {}
      }
    }
  }, []);

  const setLocale = useCallback(
    (newLocale: Locale) => {
      setLocaleState(newLocale);
      setIsLoaded(false);
      try {
        localStorage.setItem(STORAGE_KEY, newLocale);
      } catch {}
      loadLocale(newLocale);

      if (RTL_LOCALES.has(newLocale)) {
        document.documentElement.dir = "rtl";
      } else {
        document.documentElement.dir = "ltr";
      }
    },
    [loadLocale],
  );

  const t = useCallback(
    (key: string, params?: Record<string, string | number>): string => {
      let value = translations[key];
      if (value === undefined) {
        if (process.env.NODE_ENV === "development") {
          console.warn(`[i18n] Missing translation key: "${key}" for locale "${locale}"`);
        }
        value = key;
      }

      if (params) {
        for (const [k, v] of Object.entries(params)) {
          value = value.replace(`{${k}}`, String(v));
        }
      }

      return value;
    },
    [translations, locale],
  );

  return (
    <I18nContext.Provider
      value={{ locale, setLocale, t, translations, isLoaded }}
    >
      {children}
    </I18nContext.Provider>
  );
}

export function useI18nContext() {
  const ctx = useContext(I18nContext);
  if (!ctx) {
    throw new Error("useI18nContext must be used within an I18nProvider");
  }
  return ctx;
}

"use client";

import { QueryClient } from "@tanstack/react-query";
import { generateIdempotencyKey } from "@/src/services/txPersistence";

export interface OptimisticSnapshot {
  nonce: string;
  queryKey: unknown[];
  previousData: unknown;
  delta: BalanceDelta;
  timestamp: number;
  contractId: string;
  method: string;
  args: unknown[];
}

export interface BalanceDelta {
  amount: bigint;
  operation: "deposit" | "withdraw";
}

export interface TransactionParams {
  contractId: string;
  method: string;
  args: unknown[];
  delta: BalanceDelta;
  queryKey: unknown[];
  txXdr: string;
}

const STORAGE_KEY = "lumina-optimistic-snapshots";
const STORAGE_EXPIRY_MS = 5 * 60 * 1000; // 5 minutes
const SUBMIT_DEBOUNCE_MS = 50;

export class OptimisticTransactionManager {
  private queryClient: QueryClient;
  private submitting = new Set<string>();

  constructor(queryClient: QueryClient) {
    this.queryClient = queryClient;
  }

  /**
   * Apply optimistic update within 50ms of user action
   */
  applyOptimisticUpdate(
    queryKey: unknown[],
    delta: BalanceDelta,
    previousData: unknown
  ): string {
    const nonce = generateIdempotencyKey();
    const startTime = performance.now();

    // Apply the balance delta immediately
    this.queryClient.setQueryData(queryKey, (old: any) => {
      if (!old) return old;

      const newBalance =
        delta.operation === "deposit"
          ? old.rawBalance + delta.amount
          : old.rawBalance - delta.amount;

      return {
        ...old,
        rawBalance: newBalance,
        balance: newBalance.toString(),
        formattedBalance: this.formatBalance(newBalance),
      };
    });

    const elapsed = performance.now() - startTime;
    if (elapsed > SUBMIT_DEBOUNCE_MS) {
      console.warn(`Optimistic update took ${elapsed.toFixed(2)}ms (target: <${SUBMIT_DEBOUNCE_MS}ms)`);
    }

    return nonce;
  }

  /**
   * Persist snapshot to sessionStorage for crash recovery
   */
  persistSnapshot(snapshot: OptimisticSnapshot): void {
    try {
      const existing = this.loadSnapshots();
      existing.push(snapshot);
      sessionStorage.setItem(STORAGE_KEY, JSON.stringify(existing));
    } catch (error) {
      console.error("Failed to persist optimistic snapshot:", error);
    }
  }

  /**
   * Load all snapshots from sessionStorage
   */
  loadSnapshots(): OptimisticSnapshot[] {
    try {
      const raw = sessionStorage.getItem(STORAGE_KEY);
      if (!raw) return [];

      const snapshots = JSON.parse(raw) as OptimisticSnapshot[];
      
      // Filter out expired snapshots
      const now = Date.now();
      const valid = snapshots.filter(
        (s) => now - s.timestamp < STORAGE_EXPIRY_MS
      );

      if (valid.length !== snapshots.length) {
        sessionStorage.setItem(STORAGE_KEY, JSON.stringify(valid));
      }

      return valid;
    } catch {
      return [];
    }
  }

  /**
   * Remove snapshot by nonce
   */
  removeSnapshot(nonce: string): void {
    try {
      const snapshots = this.loadSnapshots();
      const filtered = snapshots.filter((s) => s.nonce !== nonce);
      sessionStorage.setItem(STORAGE_KEY, JSON.stringify(filtered));
    } catch (error) {
      console.error("Failed to remove snapshot:", error);
    }
  }

  /**
   * Rollback optimistic update within 200ms of failure detection
   */
  rollbackOptimisticUpdate(
    queryKey: unknown[],
    previousData: unknown,
    nonce: string
  ): void {
    const startTime = performance.now();

    this.queryClient.setQueryData(queryKey, previousData);
    this.removeSnapshot(nonce);

    const elapsed = performance.now() - startTime;
    if (elapsed > 200) {
      console.warn(`Rollback took ${elapsed.toFixed(2)}ms (target: <200ms)`);
    }
  }

  /**
   * Check if a transaction is currently being submitted
   */
  isSubmitting(nonce: string): boolean {
    return this.submitting.has(nonce);
  }

  /**
   * Mark transaction as submitting to prevent duplicates
   */
  markSubmitting(nonce: string): boolean {
    if (this.submitting.has(nonce)) {
      return false; // Already submitting
    }
    this.submitting.add(nonce);
    return true;
  }

  /**
   * Clear submitting flag
   */
  clearSubmitting(nonce: string): void {
    this.submitting.delete(nonce);
  }

  /**
   * Reconcile orphaned optimistic entries on mount
   */
  async reconcileOrphanedSnapshots(
    backendBalanceFetcher: () => Promise<{ rawBalance: bigint }>
  ): Promise<number> {
    const snapshots = this.loadSnapshots();
    if (snapshots.length === 0) return 0;

    try {
      // Fetch the actual backend balance
      const backendData = await backendBalanceFetcher();
      
      // For each snapshot, check if it should be rolled back
      for (const snapshot of snapshots) {
        this.queryClient.setQueryData(snapshot.queryKey, (current: any) => {
          if (!current) return current;

          // If current balance doesn't match backend, use backend value
          return {
            ...current,
            rawBalance: backendData.rawBalance,
            balance: backendData.rawBalance.toString(),
            formattedBalance: this.formatBalance(backendData.rawBalance),
          };
        });

        this.removeSnapshot(snapshot.nonce);
      }

      return snapshots.length;
    } catch (error) {
      console.error("Failed to reconcile orphaned snapshots:", error);
      return 0;
    }
  }

  /**
   * Clear all snapshots (for testing or manual cleanup)
   */
  clearAllSnapshots(): void {
    try {
      sessionStorage.removeItem(STORAGE_KEY);
    } catch (error) {
      console.error("Failed to clear snapshots:", error);
    }
  }

  /**
   * Format balance for display
   */
  private formatBalance(balance: bigint): string {
    const decimals = 7; // Standard Stellar stroops
    const divisor = 10n ** BigInt(decimals);
    const integerPart = balance / divisor;
    const fractionalPart = balance % divisor;
    
    const fractionalStr = fractionalPart
      .toString()
      .padStart(decimals, "0")
      .replace(/0+$/, "") || "0";

    return `${integerPart}.${fractionalStr}`;
  }
}

import axios from 'axios'
import { useWorkspaceStore } from '../../store/workspaceStore'

export const apiClient = axios.create({
  baseURL: '/api',
})

apiClient.interceptors.request.use((config) => {
  const activeOrg = useWorkspaceStore.getState().activeOrg
  const orgId = config.params?.orgId || config.headers?.['X-Org-Id'] || activeOrg?.id
  if (orgId) {
    config.headers['X-Org-Id'] = orgId
  }
  return config
})

export async function streamExport(
  url: string,
  data: { format: 'csv' | 'json'; startDate: string; endDate: string },
  onProgress?: (bytesReceived: number) => void
): Promise<Response> {
  const activeOrg = useWorkspaceStore.getState().activeOrg
  const headers: Record<string, string> = {
    'Content-Type': 'application/json',
    'X-Stream-Export': 'true',
  }
  if (activeOrg?.id) {
    headers['X-Org-Id'] = activeOrg.id
  }

  const response = await fetch(url, {
    method: 'POST',
    headers,
    body: JSON.stringify(data),
  })

  if (!response.ok) {
    throw new Error(`Export failed with status ${response.status}`)
  }

  return response
}

import type {
  Approval,
  ApprovalHistoryEntry,
  ApprovalStatus,
  ApprovalStoreEvents,
  ApprovalStoreListener,
  SpendingCap,
  SpendingCapPeriod,
} from "./types"

export class ApprovalStore {
  private approvals = new Map<string, Approval>()
  private caps = new Map<string, SpendingCap>()
  private history: ApprovalHistoryEntry[] = []
  private listeners = new Map<string, Set<ApprovalStoreListener>>()
  private historyLimit = 200

  constructor(historyLimit?: number) {
    if (historyLimit !== undefined) this.historyLimit = historyLimit
  }

  addApproval(approval: Approval): void {
    this.approvals.set(approval.id, approval)
    this.emit("approval_added", { approval })
  }

  updateApproval(id: string, updates: Partial<Approval>): Approval | undefined {
    const existing = this.approvals.get(id)
    if (!existing) return undefined
    const updated: Approval = { ...existing, ...updates }
    this.approvals.set(id, updated)
    this.emit("approval_updated", { approval: updated })
    return updated
  }

  removeApproval(id: string): boolean {
    const removed = this.approvals.delete(id)
    if (removed) this.emit("approval_removed", { id })
    return removed
  }

  getApproval(id: string): Approval | undefined {
    return this.approvals.get(id)
  }

  getApprovalsByDApp(dAppAddress: string): Approval[] {
    return Array.from(this.approvals.values()).filter(
      (a) => a.dAppAddress === dAppAddress,
    )
  }

  getAllApprovals(): Approval[] {
    return Array.from(this.approvals.values())
  }

  getApprovalsByStatus(status: ApprovalStatus): Approval[] {
    return Array.from(this.approvals.values()).filter(
      (a) => a.status === status,
    )
  }

  revokeApproval(id: string): Approval | undefined {
    return this.updateApproval(id, {
      status: "revoked",
      allowance: 0n,
    })
  }

  addSpendingCap(cap: SpendingCap): void {
    this.caps.set(cap.id, cap)
    this.emit("cap_added", { cap })
  }

  updateSpendingCap(id: string, updates: Partial<SpendingCap>): SpendingCap | undefined {
    const existing = this.caps.get(id)
    if (!existing) return undefined
    const updated: SpendingCap = { ...existing, ...updates }
    this.caps.set(id, updated)
    this.emit("cap_updated", { cap: updated })
    return updated
  }

  removeSpendingCap(id: string): boolean {
    const removed = this.caps.delete(id)
    if (removed) this.emit("cap_removed", { id })
    return removed
  }

  getSpendingCap(id: string): SpendingCap | undefined {
    return this.caps.get(id)
  }

  getSpendingCapsByDApp(dAppAddress: string): SpendingCap[] {
    return Array.from(this.caps.values()).filter(
      (c) => c.dAppAddress === dAppAddress,
    )
  }

  getAllSpendingCaps(): SpendingCap[] {
    return Array.from(this.caps.values())
  }

  checkSpendingCap(dAppAddress: string, amount: bigint): boolean {
    const caps = this.getSpendingCapsByDApp(dAppAddress)
    if (caps.length === 0) return true
    const now = Date.now()
    for (const cap of caps) {
      const windowMs = cap.period === "daily" ? 86_400_000 : 604_800_000
      if (now - cap.windowStart > windowMs) {
        this.updateSpendingCap(cap.id, {
          spent: 0n,
          windowStart: now,
        })
        continue
      }
      if (cap.spent + amount > cap.limit) return false
    }
    return true
  }

  recordSpend(dAppAddress: string, amount: bigint): void {
    const caps = this.getSpendingCapsByDApp(dAppAddress)
    const now = Date.now()
    for (const cap of caps) {
      const windowMs = cap.period === "daily" ? 86_400_000 : 604_800_000
      const reset = now - cap.windowStart > windowMs
      this.updateSpendingCap(cap.id, {
        spent: reset ? amount : cap.spent + amount,
        windowStart: reset ? now : cap.windowStart,
        lastUpdated: now,
      })
    }
  }

  addHistoryEntry(entry: ApprovalHistoryEntry): void {
    this.history.push(entry)
    if (this.history.length > this.historyLimit) {
      this.history.shift()
    }
    this.emit("history_added", { entry })
  }

  getHistory(approvalId?: string): ApprovalHistoryEntry[] {
    const entries = approvalId
      ? this.history.filter((e) => e.approvalId === approvalId)
      : this.history
    return [...entries].sort((a, b) => b.timestamp - a.timestamp)
  }

  clearHistory(): void {
    this.history = []
  }

  subscribe<E extends keyof ApprovalStoreEvents>(
    event: E,
    listener: (event: ApprovalStoreEvents[E]) => void,
  ): () => void {
    if (!this.listeners.has(event)) {
      this.listeners.set(event, new Set())
    }
    this.listeners.get(event)!.add(listener as ApprovalStoreListener)
    return () => this.listeners.get(event)?.delete(listener as ApprovalStoreListener)
  }

  clear(): void {
    this.approvals.clear()
    this.caps.clear()
    this.history = []
    this.listeners.clear()
  }

  private emit<E extends keyof ApprovalStoreEvents>(
    event: E,
    data: ApprovalStoreEvents[E],
  ): void {
    const set = this.listeners.get(event)
    if (!set) return
    for (const listener of set) {
      try {
        listener(data)
      } catch {
        /* noop */
      }
    }
  }
}

