  BackupFrequency,
  RestoreReport,
  VerifyReport,
  BackupDatabases,
  BackupEventType,
  BackupRestoreTelemetryPayload,
} from "./types";
export { BACKUP_SCHEMA_VERSION, PERFORMANCE_BUDGET_MS } from "./types";

import type { BackupFile, RestoreReport, StoreResult } from "./types";
import { verifyBackup } from "./verify";
import {
  exportDatabase,
  importDatabase,
  countDatabaseRecords,
} from "./storage";

/**
 * Runs a dry-run restore test: validates the backup file and reports what
 * would be restored without writing any data to IndexedDB.
 */
export async function runRestoreTest(backup: BackupFile): Promise<RestoreReport> {
  const start = performance.now();
  const stores: StoreResult[] = [];
  let totalRecordsRestored = 0;

  // First, verify the backup integrity
  const verifyReport = await verifyBackup(backup);
  if (!verifyReport.ok) {
    return {
      ok: false,
      storesAttempted: 0,
      storesSucceeded: 0,
      storesFailed: 1,
      totalRecordsRestored: 0,
      durationMs: Math.round(performance.now() - start),
      results: [],
      error: `Verification failed: ${verifyReport.errors.join("; ")}`,
    };
  }

  // Count what would be restored
  for (const [dbName, storesData] of Object.entries(backup.databases ?? {})) {
    for (const [storeName, records] of Object.entries(storesData)) {
      stores.push({
        storeName: `${dbName}/${storeName}`,
        records: records.length,
        ok: true,
      });
      totalRecordsRestored += records.length;
    }
  }

  return {
    ok: true,
    storesAttempted: stores.length,
    storesSucceeded: stores.length,
    storesFailed: 0,
    totalRecordsRestored,
    durationMs: Math.round(performance.now() - start),
    results: stores,
  };
}

/**
 * Performs a full restore of the backup file to IndexedDB.
 * If `dryRun` is true, validates without writing.
 *
 * Creates a pre-restore snapshot in memory that is returned so callers
 * can perform a rollback if needed.
 */
export async function restoreBackup(
  backup: BackupFile,
  dryRun?: boolean,
): Promise<RestoreReport & { preRestoreSnapshot?: BackupFile["databases"] }> {
  const start = performance.now();
  const stores: StoreResult[] = [];
  let totalRecordsRestored = 0;

  // First, verify the backup
  const verifyReport = await verifyBackup(backup);
  if (!verifyReport.ok) {
    return {
      ok: false,
      storesAttempted: 0,
      storesSucceeded: 0,
      storesFailed: 1,
      totalRecordsRestored: 0,
      durationMs: Math.round(performance.now() - start),
      results: [],
      error: `Verification failed: ${verifyReport.errors.join("; ")}`,
    };
  }

  // Capture pre-restore snapshot for rollback
  const preRestoreSnapshot: BackupFile["databases"] = {};
  for (const dbName of Object.keys(backup.databases ?? {})) {
    preRestoreSnapshot[dbName] = await exportDatabase(dbName);
  }

  if (dryRun) {
    // In dry-run mode, count what would be written
    for (const [dbName, storesData] of Object.entries(backup.databases ?? {})) {
      for (const [storeName, records] of Object.entries(storesData)) {
        stores.push({
          storeName: `${dbName}/${storeName}`,
          records: records.length,
          ok: true,
        });
        totalRecordsRestored += records.length;
      }
    }

    return {
      ok: true,
      storesAttempted: stores.length,
      storesSucceeded: stores.length,
      storesFailed: 0,
      totalRecordsRestored,
      durationMs: Math.round(performance.now() - start),
      results: stores,
      preRestoreSnapshot,
    };
  }

  // Perform actual restore
  let anyFailed = false;
  for (const [dbName, storesData] of Object.entries(backup.databases ?? {})) {
    const dbResults = await importDatabase(dbName, storesData, true);
    for (const [storeName, written] of Object.entries(dbResults)) {
      const expected = (storesData[storeName] ?? []).length;
      const ok = written === expected;
      stores.push({
        storeName: `${dbName}/${storeName}`,
        records: written,
        ok,
      });
      totalRecordsRestored += written;
      if (!ok) anyFailed = true;
    }
  }

  return {
    ok: !anyFailed,
    storesAttempted: stores.length,
    storesSucceeded: stores.filter((s) => s.ok).length,
    storesFailed: stores.filter((s) => !s.ok).length,
    totalRecordsRestored,
    durationMs: Math.round(performance.now() - start),
    results: stores,
    preRestoreSnapshot,
  };
}

/**
 * Rolls back a restore by writing the pre-restore snapshot back into
 * IndexedDB.
 */
export async function rollbackRestore(
  snapshot: BackupFile["databases"],
): Promise<RestoreReport> {
  const start = performance.now();
  const stores: StoreResult[] = [];
  let totalRecordsRestored = 0;
  const anyFailed = false;

  for (const [dbName, storesData] of Object.entries(snapshot)) {
    const dbResults = await importDatabase(dbName, storesData, true);
    for (const [storeName, written] of Object.entries(dbResults)) {
      stores.push({
        storeName: `${dbName}/${storeName}`,
        records: written,
        ok: true,
      });
      totalRecordsRestored += written;
    }
  }

  return {
    ok: !anyFailed,
    storesAttempted: stores.length,
    storesSucceeded: stores.filter((s) => s.ok).length,
    storesFailed: stores.filter((s) => !s.ok).length,
    totalRecordsRestored,
    durationMs: Math.round(performance.now() - start),
    results: stores,
  };
}

/**
 * Runs a full restore test cycle: verify → dry-run → full restore → verify.
 * Returns the final restore report.
 */
export async function restoreTestCycle(
  backup: BackupFile,
): Promise<RestoreReport> {
  const verifyResult = await verifyBackup(backup);
  if (!verifyResult.ok) {
    return {
      ok: false,
      storesAttempted: 0,
      storesSucceeded: 0,
      storesFailed: 1,
      totalRecordsRestored: 0,
      durationMs: verifyResult.durationMs,
      results: [],
      error: `Verification failed: ${verifyResult.errors.join("; ")}`,
    };
  }

  const dryRunResult = await runRestoreTest(backup);
  if (!dryRunResult.ok) {
    return dryRunResult;
  }

  return restoreBackup(backup, false);
}

import type { BackupScheduleConfig, BackupFrequency } from "./types";

type SchedulerCallback = () => Promise<void>;

let activeTimer: ReturnType<typeof setInterval> | null = null;
let currentCallback: SchedulerCallback | null = null;
let lastRunAt: number | null = null;

/**
 * Returns the interval in milliseconds for a given frequency.
 */
export function getIntervalMs(config: BackupScheduleConfig): number {
  switch (config.frequency) {
    case "hourly":
      return 60 * 60 * 1000;
    case "daily":
      return 24 * 60 * 60 * 1000;
    case "weekly":
      return 7 * 24 * 60 * 60 * 1000;
    case "manual":
    default:
      return 0;
  }
}

/**
 * Checks whether the schedule should fire based on time-of-day and day-of-week constraints.
 */
export function shouldRunNow(config: BackupScheduleConfig, now?: Date): boolean {
  const d = now ?? new Date();

  // Weekly: check day of week (0=Sun, 6=Sat)
  if (config.frequency === "weekly" && config.dayOfWeek != null) {
    if (d.getDay() !== config.dayOfWeek) return false;
  }

  // Hourly/daily/weekly: check time of day
  if (
    config.frequency !== "hourly" &&
    config.timeOfDay
  ) {
    const [hours, minutes] = config.timeOfDay.split(":").map(Number);
    if (d.getHours() !== hours || d.getMinutes() !== minutes) return false;
  }

  return true;
}

/**
 * Registers a scheduled backup callback. If a schedule was already active,
 * it is unregistered first.
 *
 * The scheduler uses `setInterval` with the configured frequency and also
 * checks time-of-day / day-of-week constraints.
 */
export function registerSchedule(
  config: BackupScheduleConfig,
  callback: SchedulerCallback,
): void {
  unregisterSchedule();

  if (!config.enabled || config.frequency === "manual") return;

  currentCallback = callback;
  const intervalMs = getIntervalMs(config);

  if (intervalMs <= 0) return;

  // On registration, check if we should run immediately
  if (shouldRunNow(config)) {
    callback().catch(() => {
      // Silently handle — errors flow through the event system
    });
  }

  // Check once per minute for time-of-day constraints
  const CHECK_INTERVAL = 60 * 1000;
  activeTimer = setInterval(async () => {
    if (!currentCallback) return;

    const shouldRun = shouldRunNow(config);
    if (!shouldRun) return;

    // Guard against running twice in the same minute
    const now = Date.now();
    if (lastRunAt && now - lastRunAt < intervalMs * 0.5) return;

    lastRunAt = now;
    try {
      await currentCallback();
    } catch {
      // Errors handled by caller
    }
  }, CHECK_INTERVAL);
}

/**
 * Unregisters the active schedule timer.
 */
export function unregisterSchedule(): void {
  if (activeTimer !== null) {
    clearInterval(activeTimer);
    activeTimer = null;
  }
  currentCallback = null;
  lastRunAt = null;
}

/**
 * Returns whether a schedule is currently active.
 */
export function isScheduleActive(): boolean {
  return activeTimer !== null;
}

/**
 * Returns the last run timestamp, or null if never run.
 */
export function getLastRunAt(): number | null {
  return lastRunAt;
}

import { openDB, type DBSchema, type IDBPDatabase } from "idb";
import type { BackupMetadata } from "./types";

const BACKUP_META_KEY = "lumina-backup-metadata";

// In-memory fallback for environments without localStorage (Node.js tests, SSR)
const memoryStore = new Map<string, string>();

function hasLocalStorage(): boolean {
  try {
    return typeof localStorage !== "undefined" && localStorage !== null;
  } catch {
    return false;
  }
}

// ── Known database schemas ──────────────────────────────────────────

interface HorizonPageRecord {
  index: number;
  cursor: string | null;
  prevCursor: string | null;
  nextCursor: string | null;
}

interface SerializedCursorCache {
  endpoint: string;
  pages: HorizonPageRecord[];
  updatedAt: string;
}

interface LuminaFieldDB extends DBSchema {
  inspectionRecords: {
    key: number;
    value: Record<string, unknown>;
    indexes: { "by-nodeId": string; "by-createdAt": string };
  };
  nodeConfigSnapshots: {
    key: number;
    value: Record<string, unknown>;
    indexes: { "by-nodeId": string; "by-snapshotAt": string };
  };
  syncQueue: {
    key: number;
    value: Record<string, unknown>;
    indexes: { "by-collection": string; "by-createdAt": string };
  };
  syncMetadata: {
    key: number;
    value: Record<string, unknown>;
    indexes: { "by-collection": string };
  };
  horizonCursors: {
    key: string;
    value: SerializedCursorCache;
  };
}

interface LuminaOfflineDB extends DBSchema {
  "outgoing-requests": {
    key: number;
    value: Record<string, unknown>;
    indexes: { "by-enqueuedAt": string };
  };
}

// ── DB names and store lists ────────────────────────────────────────

const DB_CONFIGS: Record<
  string,
  { version: number; stores: string[]; upgrade?: (db: IDBPDatabase<any>) => void }
> = {
  "lumina-field-db": {
    version: 2,
    stores: [
      "inspectionRecords",
      "nodeConfigSnapshots",
      "syncQueue",
      "syncMetadata",
      "horizonCursors",
    ],
  },
  "lumina-offline-queue": {
    version: 1,
    stores: ["outgoing-requests"],
  },
};

const KNOWN_DB_NAMES = Object.keys(DB_CONFIGS);

// ── Metadata helpers (localStorage) ─────────────────────────────────

function getStoredMetadata(): BackupMetadata[] {
  try {
    const raw = hasLocalStorage()
      ? localStorage.getItem(BACKUP_META_KEY)
      : memoryStore.get(BACKUP_META_KEY);
    if (!raw) return [];
    return JSON.parse(raw) as BackupMetadata[];
  } catch {
    return [];
  }
}

function persistMetadata(list: BackupMetadata[]): void {
  try {
    const json = JSON.stringify(list);
    if (hasLocalStorage()) {
      localStorage.setItem(BACKUP_META_KEY, json);
    } else {
      memoryStore.set(BACKUP_META_KEY, json);
    }
  } catch {
    // localStorage full — silently degrade
  }
}

export function saveMetadata(meta: BackupMetadata): void {
  const list = getStoredMetadata();
  const idx = list.findIndex((m) => m.id === meta.id);
  if (idx >= 0) {
    list[idx] = meta;
  } else {
    list.push(meta);
  }
  persistMetadata(list);
}

export function getMetadataList(): BackupMetadata[] {
  return getStoredMetadata();
}

export function removeMetadata(id: string): void {
  const list = getStoredMetadata().filter((m) => m.id !== id);
  persistMetadata(list);
}

export function clearAllMetadata(): void {
  try {
    if (hasLocalStorage()) {
      localStorage.removeItem(BACKUP_META_KEY);
    } else {
      memoryStore.delete(BACKUP_META_KEY);
    }
  } catch {
    // noop
  }
}

// ── IndexedDB export / import ───────────────────────────────────────

function getFieldDbPromise(): Promise<IDBPDatabase<LuminaFieldDB>> | null {
  if (typeof indexedDB === "undefined") return null;
  return openDB<LuminaFieldDB>("lumina-field-db", 2, {
    upgrade(db, oldVersion) {
      if (oldVersion < 1) {
        const ir = db.createObjectStore("inspectionRecords", {
          keyPath: "id",
          autoIncrement: true,
        });
        ir.createIndex("by-nodeId", "nodeId");
        ir.createIndex("by-createdAt", "createdAt");

        const nc = db.createObjectStore("nodeConfigSnapshots", {
          keyPath: "id",
          autoIncrement: true,
        });
        nc.createIndex("by-nodeId", "nodeId");
        nc.createIndex("by-snapshotAt", "snapshotAt");

        const sq = db.createObjectStore("syncQueue", {
          keyPath: "id",
          autoIncrement: true,
        });
        sq.createIndex("by-collection", "collection");
        sq.createIndex("by-createdAt", "createdAt");

        const sm = db.createObjectStore("syncMetadata", {
          keyPath: "id",
          autoIncrement: true,
        });
        sm.createIndex("by-collection", "collection");
      }
      if (oldVersion < 2) {
        db.createObjectStore("horizonCursors", { keyPath: "endpoint" });
      }
    },
    blocked() {},
  });
}

function getOfflineDbPromise(): Promise<IDBPDatabase<LuminaOfflineDB>> | null {
  if (typeof indexedDB === "undefined") return null;
  return openDB<LuminaOfflineDB>("lumina-offline-queue", 1, {
    upgrade(db) {
      if (!db.objectStoreNames.contains("outgoing-requests")) {
        const store = db.createObjectStore("outgoing-requests", {
          keyPath: "id",
          autoIncrement: true,
        });
        store.createIndex("by-enqueuedAt", "enqueuedAt");
      }
    },
    blocked() {},
  });
}

/**
 * Reads every object store from a named IndexedDB and returns a map of
 * store-name → records[]. Returns an empty object if the DB does not
 * exist or is inaccessible.
 */
export async function exportDatabase(
  dbName: string,
): Promise<Record<string, unknown[]>> {
  const config = DB_CONFIGS[dbName];
  if (!config) return {};

  let db: IDBPDatabase<any> | null = null;
  try {
    if (dbName === "lumina-field-db") {
      db = await getFieldDbPromise();
    } else if (dbName === "lumina-offline-queue") {
      db = await getOfflineDbPromise();
    }
    if (!db) return {};

    const result: Record<string, unknown[]> = {};
    for (const storeName of config.stores) {
      if (db.objectStoreNames.contains(storeName)) {
        const tx = db.transaction(storeName, "readonly");
        const all = await tx.store.getAll();
        await tx.done;
        result[storeName] = all;
      }
    }
    return result;
  } catch {
    return {};
  } finally {
    if (db) db.close();
  }
}

/**
 * Writes records into an IndexedDB object store. If `clear` is true, the
 * store is cleared before writing. Returns the number of records written.
 */
export async function importStore(
  dbName: string,
  storeName: string,
  records: unknown[],
  clear?: boolean,
): Promise<number> {
  let db: IDBPDatabase<any> | null = null;
  try {
    if (dbName === "lumina-field-db") {
      db = await getFieldDbPromise();
    } else if (dbName === "lumina-offline-queue") {
      db = await getOfflineDbPromise();
    }
    if (!db) return 0;

    if (!db.objectStoreNames.contains(storeName)) return 0;

    const tx = db.transaction(storeName, "readwrite");
    if (clear) {
      await tx.store.clear();
    }
    let written = 0;
    for (const record of records) {
      await tx.store.put(record);
      written++;
    }
    await tx.done;
    return written;
  } catch {
    return 0;
  } finally {
    if (db) db.close();
  }
}

/**
 * Writes all stores for a database in a single transaction per store.
 * If `clear` is true, each store is cleared before writing.
 * Returns a map of store-name → recordsWritten.
 */
export async function importDatabase(
  dbName: string,
  data: Record<string, unknown[]>,
  clear?: boolean,
): Promise<Record<string, number>> {
  const config = DB_CONFIGS[dbName];
  if (!config) return {};

  const result: Record<string, number> = {};
  for (const storeName of config.stores) {
    const records = data[storeName];
    if (records && records.length > 0) {
      result[storeName] = await importStore(dbName, storeName, records, clear);
    } else {
      result[storeName] = 0;
    }
  }
  return result;
}

/**
 * Returns the total record count across all stores in a named IndexedDB.
 */
export async function countDatabaseRecords(
  dbName: string,
): Promise<number> {
  let db: IDBPDatabase<any> | null = null;
  try {
    if (dbName === "lumina-field-db") {
      db = await getFieldDbPromise();
    } else if (dbName === "lumina-offline-queue") {
      db = await getOfflineDbPromise();
    }
    if (!db) return 0;

    const config = DB_CONFIGS[dbName];
    if (!config) return 0;

    let total = 0;
    for (const storeName of config.stores) {
      if (db.objectStoreNames.contains(storeName)) {
        total += await db.count(storeName);
      }
    }
    return total;
  } catch {
    return 0;
  } finally {
    if (db) db.close();
  }
}

/**
 * Clears all data from all known databases.
 */
export async function clearAllDatabases(): Promise<void> {
  for (const dbName of KNOWN_DB_NAMES) {
    const config = DB_CONFIGS[dbName];
    if (!config) continue;
    let db: IDBPDatabase<any> | null = null;
    try {
      if (dbName === "lumina-field-db") {
        db = await getFieldDbPromise();
      } else if (dbName === "lumina-offline-queue") {
        db = await getOfflineDbPromise();
      }
      if (!db) continue;
      const tx = db.transaction(config.stores, "readwrite");
      for (const storeName of config.stores) {
        if (db.objectStoreNames.contains(storeName)) {
          await tx.objectStore(storeName).clear();
        }
      }
      await tx.done;
    } catch {
      // best-effort
    } finally {
      if (db) db.close();
    }
  }
}

export function getKnownDbNames(): string[] {
  return [...KNOWN_DB_NAMES];
}

/**
 * Service Worker integration for backup scheduling.
 *
 * Provides helper functions for registering periodic backup sync events
 * in the Service Worker context. These are meant to be called from the
 * SW's `message` event handler or from the main thread via postMessage.
 */

/**
 * Registers a periodic sync event for backup tasks.
 * Falls back to a setInterval-based approach if periodicSync is not supported.
 */
export async function registerPeriodicSync(
  swRegistration: ServiceWorkerRegistration,
  config: { enabled: boolean; frequency: "hourly" | "daily" | "weekly" },
): Promise<void> {
  if (!config.enabled) {
    await unregisterPeriodicSync(swRegistration);
    return;
  }

  const minInterval = getMinIntervalMs(config.frequency);

  // Try the Periodic Sync API first
  if ("periodicSync" in swRegistration) {
    try {
      const ps = (swRegistration as any).periodicSync as {
        register: (tag: string, options: { minInterval: number }) => Promise<void>;
        unregister: (tag: string) => Promise<void>;
        getTags: () => Promise<string[]>;
      };

      await ps.register("backup-db", {
        minInterval,
      });
      return;
    } catch {
      // PeriodicSync not available or permission denied — fall through to setInterval
    }
  }

  // Fallback: send message to SW to start interval-based scheduling
  const sw = swRegistration.active;
  if (sw) {
    sw.postMessage({
      type: "register-backup-interval",
      minInterval,
    });
  }
}

/**
 * Unregisters a previously registered periodic sync.
 */
export async function unregisterPeriodicSync(
  swRegistration: ServiceWorkerRegistration,
): Promise<void> {
  if ("periodicSync" in swRegistration) {
    try {
      const ps = (swRegistration as any).periodicSync as {
        unregister: (tag: string) => Promise<void>;
      };
      await ps.unregister("backup-db");
    } catch {
      // ignore
    }
  }

  const sw = swRegistration.active;
  if (sw) {
    sw.postMessage({ type: "unregister-backup-interval" });
  }
}

function getMinIntervalMs(frequency: "hourly" | "daily" | "weekly"): number {
  switch (frequency) {
    case "hourly":
      return 60 * 60 * 1000;
    case "daily":
      return 24 * 60 * 60 * 1000;
    case "weekly":
      return 7 * 24 * 60 * 60 * 1000;
  }
}

export type SwBackupMessage =
  | { type: "backup-created" }
  | { type: "backup-failed"; error: string }
  | { type: "register-backup-interval"; minInterval: number }
  | { type: "unregister-backup-interval" };

"use client";

export enum RoundingMode {
  HALF_UP = "HALF_UP",
  DOWN = "DOWN",
  UP = "UP",
}

const MAX_STROOP = BigInt("100000000000000000000"); // 10^20 stroops ~ 10^13 XLM

function pow10(exp: number): bigint {
  return 10n ** BigInt(exp);
}

export function toStroop(amount: string, decimals: number): bigint {
  const negative = amount.startsWith("-");
  const clean = negative ? amount.slice(1) : amount;
  const dot = clean.indexOf(".");
  if (dot === -1) {
    const full = clean + "0".repeat(decimals);
    const trimmed = full.replace(/^0+/, "") || "0";
    const result = BigInt(trimmed);
    return negative ? -result : result;
  }
  const intPart = clean.slice(0, dot);
  let decPart = clean.slice(dot + 1);
  const secondDot = decPart.indexOf(".");
  if (secondDot !== -1) {
    decPart = decPart.slice(0, secondDot);
  }
  const padded = decPart.padEnd(decimals, "0").slice(0, decimals);
  const full = intPart + padded;
  const trimmed = full.replace(/^0+/, "") || "0";
  const result = BigInt(trimmed);
  return negative ? -result : result;
}

export function fromStroop(stroops: bigint, decimals: number): string {
  const divisor = pow10(decimals);
  const negative = stroops < 0n;
  const abs = negative ? -stroops : stroops;
  const intPart = abs / divisor;
  const remainder = abs % divisor;
  const prefix = negative ? "-" : "";
  if (remainder === 0n) return prefix + intPart.toString();
  let decStr = remainder.toString().padStart(decimals, "0");
  decStr = decStr.replace(/0+$/, "");
  return `${prefix}${intPart}.${decStr}`;
}

export function formatStroop(
  stroops: bigint,
  decimals: number,
  locale?: string,
): string {
  const divisor = pow10(decimals);
  const negative = stroops < 0n;
  const abs = negative ? -stroops : stroops;
  const intPart = abs / divisor;
  const remainder = abs % divisor;
  const prefix = negative ? "-" : "";
  const intFormatter = new Intl.NumberFormat(locale, { useGrouping: true });
  let formattedInt: string;
  if (intPart <= BigInt(Number.MAX_SAFE_INTEGER)) {
    formattedInt = intFormatter.format(Number(intPart));
  } else {
    formattedInt = intPart.toString();
  }
  if (remainder === 0n) return prefix + formattedInt;
  let decStr = remainder.toString().padStart(decimals, "0");
  decStr = decStr.replace(/0+$/, "");
  const significant = decStr.length;
  return prefix + formattedInt + "." + decStr;
}

export function add(a: bigint, b: bigint): bigint {
  const result = a + b;
  if (result > MAX_STROOP || result < -MAX_STROOP) {
    throw new Error("Overflow: addition exceeds maximum allowed stroop amount");
  }
  return result;
}

export function sub(a: bigint, b: bigint): bigint {
  const result = a - b;
  if (result > MAX_STROOP || result < -MAX_STROOP) {
    throw new Error("Overflow: subtraction exceeds maximum allowed stroop amount");
  }
  return result;
}

export function mul(a: bigint, b: bigint): bigint {
  const result = a * b;
  if (result > MAX_STROOP || result < -MAX_STROOP) {
    throw new Error("Overflow: multiplication exceeds maximum allowed stroop amount");
  }
  return result;
}

export function div(
  a: bigint,
  b: bigint,
  rounding: RoundingMode = RoundingMode.HALF_UP,
): bigint {
  if (b === 0n) throw new Error("Division by zero");
  const q = a / b;
  const r = a % b;
  if (r === 0n) return q;
  const absR = r < 0n ? -r : r;
  const absB = b < 0n ? -b : b;
  switch (rounding) {
    case RoundingMode.DOWN:
      return q;
    case RoundingMode.UP:
      return r > 0n ? q + 1n : q - 1n;
    case RoundingMode.HALF_UP:
      if (absR * 2n >= absB) {
        return r > 0n ? q + 1n : q - 1n;
      }
      return q;
    default:
      return q;
  }
}

export function compare(a: bigint, b: bigint): number {
  if (a > b) return 1;
  if (a < b) return -1;
  return 0;
}

export function isZero(a: bigint): boolean {
  return a === 0n;
}

export function isNegative(a: bigint): boolean {
  return a < 0n;
}

"use client";

import { create } from "zustand";
import type { BridgeTransaction, BridgeRoute, BridgeStatus, ChainId } from "./types";

export const STATUS_ORDER: BridgeStatus[] = [
  "Initiated",
  "SourceConfirmed",
  "BridgeRelayed",
  "DestinationPending",
  "DestinationConfirmed",
  "Complete",
];

const STATUS_TIMESTAMPS = [
  "initiatedAt",
  "sourceConfirmedAt",
  "bridgeRelayedAt",
  "destinationPendingAt",
  "destinationConfirmedAt",
  "completedAt",
] as const;

function getNextStatus(current: BridgeStatus): BridgeStatus | null {
  const idx = STATUS_ORDER.indexOf(current);
  if (idx === -1 || idx === STATUS_ORDER.length - 1) return null;
  return STATUS_ORDER[idx + 1];
}

function getStatusTimestampField(status: BridgeStatus): string | null {
  const idx = STATUS_ORDER.indexOf(status);
  if (idx === -1) return null;
  return STATUS_TIMESTAMPS[idx] ?? null;
}

export interface BridgeState {
  transactions: Record<string, BridgeTransaction>
  routes: BridgeRoute[]

  addTransaction: (tx: BridgeTransaction) => void
  updateStatus: (id: string, status: BridgeStatus, overrides?: Partial<BridgeTransaction>) => void
  advanceStatus: (id: string, overrides?: Partial<BridgeTransaction>) => void
  markFailed: (id: string, reason: string, action: "retry" | "contact_support") => void
  removeTransaction: (id: string) => void
  getTransaction: (id: string) => BridgeTransaction | undefined
  getTransactionsByStatus: (status: BridgeStatus) => BridgeTransaction[]
  getTransactionsByChain: (chainId: ChainId) => BridgeTransaction[]
  setRoutes: (routes: BridgeRoute[]) => void
}

export const useBridgeStore = create<BridgeState>((set, get) => ({
  transactions: {},
  routes: [],

  addTransaction: (tx: BridgeTransaction) => {
    set((state) => ({
      transactions: { ...state.transactions, [tx.id]: tx },
    }));
  },

  updateStatus: (id: string, status: BridgeStatus, overrides?: Partial<BridgeTransaction>) => {
    set((state) => {
      const existing = state.transactions[id];
      if (!existing) return state;

      const timestampField = getStatusTimestampField(status);
      const now = Date.now();

      const timestampUpdate = timestampField ? { [timestampField]: now } : {};

      return {
        transactions: {
          ...state.transactions,
          [id]: {
            ...existing,
            ...timestampUpdate,
            status,
            ...overrides,
          },
        },
      };
    });
  },

  advanceStatus: (id: string, overrides?: Partial<BridgeTransaction>) => {
    const state = get();
    const tx = state.transactions[id];
    if (!tx || tx.status === "Failed") return;

    const next = getNextStatus(tx.status);
    if (!next) return;
    state.updateStatus(id, next, overrides);
  },

  markFailed: (id: string, reason: string, action: "retry" | "contact_support") => {
    set((state) => {
      const existing = state.transactions[id];
      if (!existing) return state;

      return {
        transactions: {
          ...state.transactions,
          [id]: {
            ...existing,
            status: "Failed",
            errorReason: reason,
            recommendedAction: action,
            failedAt: Date.now(),
          },
        },
      };
    });
  },

  removeTransaction: (id: string) => {
    set((state) => {
      const { [id]: _, ...rest } = state.transactions;
      return { transactions: rest };
    });
  },

  getTransaction: (id: string) => {
    return get().transactions[id];
  },

  getTransactionsByStatus: (status: BridgeStatus) => {
    return Object.values(get().transactions).filter((tx) => tx.status === status);
  },

  getTransactionsByChain: (chainId: ChainId) => {
    return Object.values(get().transactions).filter(
      (tx) => tx.sourceChain === chainId || tx.destinationChain === chainId,
    );
  },

  setRoutes: (routes: BridgeRoute[]) => {
    set({ routes });
  },
}));

import assert from "node:assert/strict";
import { RedisCache } from "../redisCache";
import { CacheMonitor } from "../cacheMonitor";
import {
  DEFAULT_TTL_CONFIG,
