import type { Job, JobDefinition, JobStatus } from "./types"

export class JobStore<T = unknown> {
  private jobs = new Map<string, Job<T>>()
  private byStatus = new Map<JobStatus, Set<string>>()

  submit(def: JobDefinition): Job<T> {
    const existing = Array.from(this.jobs.values()).find(
      (j) =>
        j.definition.jobType === def.jobType &&
        j.status === "pending",
    )
    if (existing) return existing

    const jobId = crypto.randomUUID()
    const now = Date.now()
    const job: Job<T> = {
      jobId,
      definition: def,
      status: "pending",
      retryCount: 0,
      createdAt: now,
    }
    this.jobs.set(jobId, job)
    this.addToIndex("pending", jobId)
    return job
  }

  get(jobId: string): Job<T> | undefined {
    return this.jobs.get(jobId)
  }

  updateStatus(jobId: string, status: JobStatus, extra?: Partial<Job<T>>): void {
    const job = this.jobs.get(jobId)
    if (!job) return

    this.removeFromIndex(job.status, jobId)
    job.status = status
    if (extra) Object.assign(job, extra)
    this.addToIndex(status, jobId)
  }

  claimNext(
    workerId: string,
    leaseDurationMs: number,
    now: number,
    allowTypes?: string[],
  ): { job: Job<T>; leaseExpiresAt: number } | null {
    const pending = this.getByStatus("pending")
    for (const job of pending) {
      if (allowTypes && !allowTypes.includes(job.definition.jobType)) continue
      const leaseExpiresAt = now + leaseDurationMs
      this.updateStatus(job.jobId, "running", {
        startedAt: now,
        claimedBy: workerId,
        leaseExpiresAt,
      })
      return { job, leaseExpiresAt }
    }
    return null
  }

  complete(jobId: string, result: T, now: number): void {
    this.updateStatus(jobId, "completed", { result, completedAt: now })
  }

  fail(jobId: string, error: string): void {
    const job = this.jobs.get(jobId)
    if (!job) return

    if (job.retryCount < job.definition.maxRetries) {
      job.retryCount++
      this.updateStatus(jobId, "pending", {
        claimedBy: undefined,
        startedAt: undefined,
        leaseExpiresAt: undefined,
      })
    } else {
      this.updateStatus(jobId, "failed", { error, completedAt: Date.now() })
    }
  }

  timeoutExpiredLeases(now: number, leaseDurationMs: number): string[] {
    const timedOut: string[] = []
    const running = this.getByStatus("running")
    for (const job of running) {
      if (job.leaseExpiresAt && now > job.leaseExpiresAt) {
        if (job.retryCount < job.definition.maxRetries) {
          job.retryCount++
          this.updateStatus(job.jobId, "pending", {
            claimedBy: undefined,
            startedAt: undefined,
            leaseExpiresAt: undefined,
          })
        } else {
          this.updateStatus(job.jobId, "timed_out", {
            error: "Lease expired",
            completedAt: now,
          })
        }
        timedOut.push(job.jobId)
      }
    }
    return timedOut
  }

  timeoutJobs(now: number): string[] {
    const timedOut: string[] = []
    const running = this.getByStatus("running")
    for (const job of running) {
      if (job.startedAt && now - job.startedAt > job.definition.timeoutMs) {
        this.fail(job.jobId, `Job timed out after ${job.definition.timeoutMs}ms`)
        timedOut.push(job.jobId)
      }
    }
    return timedOut
  }

  getByStatus(status: JobStatus): Job<T>[] {
    const ids = this.byStatus.get(status)
    if (!ids) return []
    return Array.from(ids)
      .map((id) => this.jobs.get(id)!)
      .filter(Boolean)
  }

  getAll(): Job<T>[] {
    return Array.from(this.jobs.values()).sort((a, b) => a.createdAt - b.createdAt)
  }

  size(): number {
    return this.jobs.size
  }

  clear(): void {
    this.jobs.clear()
    this.byStatus.clear()
  }

  private addToIndex(status: JobStatus, jobId: string): void {
    let set = this.byStatus.get(status)
    if (!set) {
      set = new Set()
      this.byStatus.set(status, set)
    }
    set.add(jobId)
  }

  private removeFromIndex(status: JobStatus, jobId: string): void {
    this.byStatus.get(status)?.delete(jobId)
  }
}

import type { Lease, WorkerIdentity, WorkerClaim } from "./types"
import { JobStore } from "./jobStore"

export class LeaseManager {
  private leases = new Map<string, Lease>()
  private workers = new Map<string, WorkerIdentity>()
  private jobStore: JobStore

  constructor(jobStore: JobStore) {
    this.jobStore = jobStore
  }

  registerWorker(identity: WorkerIdentity): void {
    this.workers.set(identity.workerId, identity)
  }

  unregisterWorker(workerId: string): void {
    this.workers.delete(workerId)
    for (const [leaseId, lease] of this.leases) {
      if (lease.workerId === workerId && lease.status === "active") {
        this.releaseLease(leaseId)
      }
    }
  }

  getWorker(workerId: string): WorkerIdentity | undefined {
    return this.workers.get(workerId)
  }

  getWorkerCount(): number {
    return this.workers.size
  }

  getWorkers(): WorkerIdentity[] {
    return Array.from(this.workers.values())
  }

  claimJob(claim: WorkerClaim): { job: import("./types").Job; lease: Lease } | null {
    const now = claim.claimedAt
    const result = this.jobStore.claimNext(claim.workerId, claim.leaseDurationMs, now)
    if (!result) return null

    const leaseId = crypto.randomUUID()
    const lease: Lease = {
      leaseId,
      jobId: result.job.jobId,
      workerId: claim.workerId,
      status: "active",
      acquiredAt: now,
      expiresAt: result.leaseExpiresAt,
      heartbeatAt: now,
    }
    this.leases.set(leaseId, lease)
    return { job: result.job, lease }
  }

  renewLease(leaseId: string, now: number): boolean {
    const lease = this.leases.get(leaseId)
    if (!lease || lease.status !== "active") return false
    lease.heartbeatAt = now
    return true
  }

  releaseLease(leaseId: string): boolean {
    const lease = this.leases.get(leaseId)
    if (!lease) return false
    lease.status = "released"
    return true
  }

  expireStaleLeases(now: number, leaseDurationMs: number): string[] {
    const expired: string[] = []
    for (const [leaseId, lease] of this.leases) {
      if (lease.status === "active" && now > lease.expiresAt) {
        lease.status = "expired"
        expired.push(leaseId)
      }
    }
    return expired
  }

  getActiveLeaseCount(): number {
    let count = 0
    for (const lease of this.leases.values()) {
      if (lease.status === "active") count++
    }
    return count
  }

  getExpiredLeaseCount(): number {
    let count = 0
    for (const lease of this.leases.values()) {
      if (lease.status === "expired") count++
    }
    return count
  }

  getLease(leaseId: string): Lease | undefined {
    return this.leases.get(leaseId)
  }

  getLeasesByWorker(workerId: string): Lease[] {
    return Array.from(this.leases.values()).filter(
      (l) => l.workerId === workerId,
    )
  }

  clear(): void {
    this.leases.clear()
    this.workers.clear()
  }
}

"use client";

import { openDB, type DBSchema, type IDBPDatabase } from "idb";

export interface InspectionRecord {
  id?: number;
  nodeId: string;
  technicianId: string;
  status: string;
  notes: string;
  checklist: Record<string, boolean>;
  createdAt: string;
  updatedAt: string;
  serverTimestamp?: string;
}

export interface NodeConfigSnapshot {
  id?: number;
  nodeId: string;
  config: Record<string, unknown>;
  version: number;
  snapshotAt: string;
  serverTimestamp?: string;
}

export interface SyncQueueEntry {
  id?: number;
  collection: "inspectionRecords" | "nodeConfigSnapshots";
  payload: string;
  createdAt: string;
  retryCount: number;
  lastAttemptAt: string | null;
}

export interface SyncMetadata {
  id?: number;
  collection: string;
  lastSyncAt: string | null;
  syncStatus: "idle" | "syncing" | "error";
  errorMessage: string | null;
}

export interface SyncFlushResult {
  attempted: number;
  succeeded: number;
  failed: number;
}

// ── Horizon cursor cache types ──────────────────────────────────────

/**
 * One page entry in the Horizon cursor cache.
 * `cursor` is the paging token used to *load* this page (null = first page).
 */
export interface HorizonPageRecord {
  /** 0-based page index */
  index: number;
  /** Cursor used to fetch this page (null = page 0, no cursor needed) */
  cursor: string | null;
  /** Cursor to fetch the previous page */
  prevCursor: string | null;
  /** Cursor to fetch the next page */
  nextCursor: string | null;
}

/** Top-level record stored per endpoint/accountId in IndexedDB */
export interface SerializedCursorCache {
  /** Key: `horizon/cursors/${accountId}` */
  endpoint: string;
  pages: HorizonPageRecord[];
  updatedAt: string;
}

interface LuminaFieldDB extends DBSchema {
  inspectionRecords: {
    key: number;
    value: InspectionRecord;
    indexes: { "by-nodeId": string; "by-createdAt": string };
  };
  nodeConfigSnapshots: {
    key: number;
    value: NodeConfigSnapshot;
    indexes: { "by-nodeId": string; "by-snapshotAt": string };
  };
  syncQueue: {
    key: number;
    value: SyncQueueEntry;
    indexes: { "by-collection": string; "by-createdAt": string };
  };
  syncMetadata: {
    key: number;
    value: SyncMetadata;
    indexes: { "by-collection": string };
  };
  /** Horizon cursor cache — keyed by endpoint string */
  horizonCursors: {
    key: string;
    value: SerializedCursorCache;
  };
}

const DB_NAME = "lumina-field-db";
const DB_VERSION = 2;

let dbPromise: Promise<IDBPDatabase<LuminaFieldDB>> | null = null;

function hasIndexedDB(): boolean {
  return typeof indexedDB !== "undefined";
}

export function getFieldDb(): Promise<IDBPDatabase<LuminaFieldDB>> | null {
  if (!hasIndexedDB()) return null;
  if (!dbPromise) {
    dbPromise = openDB<LuminaFieldDB>(DB_NAME, DB_VERSION, {
      upgrade(db, oldVersion) {
        if (oldVersion < 1) {
          const ir = db.createObjectStore("inspectionRecords", {
            keyPath: "id",
            autoIncrement: true,
          });
          ir.createIndex("by-nodeId", "nodeId");
          ir.createIndex("by-createdAt", "createdAt");

          const nc = db.createObjectStore("nodeConfigSnapshots", {
            keyPath: "id",
            autoIncrement: true,
          });
          nc.createIndex("by-nodeId", "nodeId");
          nc.createIndex("by-snapshotAt", "snapshotAt");

          const sq = db.createObjectStore("syncQueue", {
            keyPath: "id",
            autoIncrement: true,
          });
          sq.createIndex("by-collection", "collection");
          sq.createIndex("by-createdAt", "createdAt");

          const sm = db.createObjectStore("syncMetadata", {
            keyPath: "id",
            autoIncrement: true,
          });
          sm.createIndex("by-collection", "collection");
        }
        // v2: Horizon cursor-cache store
        if (oldVersion < 2) {
          db.createObjectStore("horizonCursors", { keyPath: "endpoint" });
        }
      },
      blocked() {},
    });
  }
  return dbPromise;
}

// ── Inspection Records ──────────────────────────────────────────────

export async function saveInspectionRecord(
  record: Omit<InspectionRecord, "id">
): Promise<number | null> {
  const db = await getFieldDb();
  if (!db) return null;
  const tx = db.transaction(["inspectionRecords", "syncQueue"], "readwrite");
  const id = await tx.objectStore("inspectionRecords").add(record as InspectionRecord);
  await tx.objectStore("syncQueue").add({
    collection: "inspectionRecords",
    payload: JSON.stringify({ ...record, id }),
    createdAt: record.createdAt,
    retryCount: 0,
    lastAttemptAt: null,
  } as SyncQueueEntry);
  await tx.done;
  return id;
}

export async function getInspectionRecords(): Promise<InspectionRecord[]> {
  const db = await getFieldDb();
  if (!db) return [];
  return db.getAllFromIndex("inspectionRecords", "by-createdAt");
}

// ── Node Config Snapshots ───────────────────────────────────────────

export async function saveNodeConfigSnapshot(
  snapshot: Omit<NodeConfigSnapshot, "id">
): Promise<number | null> {
  const db = await getFieldDb();
  if (!db) return null;
  const tx = db.transaction(["nodeConfigSnapshots", "syncQueue"], "readwrite");
  const id = await tx.objectStore("nodeConfigSnapshots").add(snapshot as NodeConfigSnapshot);
  await tx.objectStore("syncQueue").add({
    collection: "nodeConfigSnapshots",
    payload: JSON.stringify({ ...snapshot, id }),
    createdAt: snapshot.snapshotAt,
    retryCount: 0,
    lastAttemptAt: null,
  } as SyncQueueEntry);
  await tx.done;
  return id;
}

export async function getNodeConfigSnapshots(nodeId?: string): Promise<NodeConfigSnapshot[]> {
  const db = await getFieldDb();
  if (!db) return [];
  if (nodeId) {
    return db.getAllFromIndex("nodeConfigSnapshots", "by-nodeId", nodeId);
  }
  return db.getAllFromIndex("nodeConfigSnapshots", "by-snapshotAt");
}

// ── Sync Queue ──────────────────────────────────────────────────────

export async function getSyncQueue(): Promise<SyncQueueEntry[]> {
  const db = await getFieldDb();
  if (!db) return [];
  return db.getAllFromIndex("syncQueue", "by-createdAt");
}

export async function getSyncQueueSize(): Promise<number> {
  const db = await getFieldDb();
  if (!db) return 0;
  return db.count("syncQueue");
}

export async function removeSyncEntry(id: number): Promise<void> {
  const db = await getFieldDb();
  if (!db) return;
  await db.delete("syncQueue", id);
}

export async function updateSyncEntry(
  id: number,
  update: Partial<Pick<SyncQueueEntry, "retryCount" | "lastAttemptAt">>
): Promise<void> {
  const db = await getFieldDb();
  if (!db) return;
  const tx = db.transaction("syncQueue", "readwrite");
  const entry = await tx.store.get(id);
  if (entry) await tx.store.put({ ...entry, ...update });
  await tx.done;
}

export async function clearSyncQueue(): Promise<void> {
  const db = await getFieldDb();
  if (!db) return;
  await db.clear("syncQueue");
}

export async function clearAllFieldData(): Promise<void> {
  const db = await getFieldDb();
  if (!db) return;
  const tx = db.transaction(
    ["inspectionRecords", "nodeConfigSnapshots", "syncQueue", "syncMetadata"],
    "readwrite"
  );
  await tx.objectStore("inspectionRecords").clear();
  await tx.objectStore("nodeConfigSnapshots").clear();
  await tx.objectStore("syncQueue").clear();
  await tx.objectStore("syncMetadata").clear();
  await tx.done;
}

// ── Sync Metadata ───────────────────────────────────────────────────

export async function getSyncMetadata(
  collection: string
): Promise<SyncMetadata | undefined> {
  const db = await getFieldDb();
  if (!db) return undefined;
  const results = await db.getAllFromIndex("syncMetadata", "by-collection", collection);
  return results[0];
}

export async function upsertSyncMetadata(
  collection: string,
  update: Partial<Omit<SyncMetadata, "id" | "collection">>
): Promise<void> {
  const db = await getFieldDb();
  if (!db) return;
  const tx = db.transaction("syncMetadata", "readwrite");
  const existing = (await tx.store.index("by-collection").getAll(collection))[0];
  if (existing) {
    await tx.store.put({ ...existing, ...update });
  } else {
    await tx.store.add({
      collection,
      lastSyncAt: null,
      syncStatus: "idle",
      errorMessage: null,
      ...update,
    } as SyncMetadata);
  }
  await tx.done;
}

// ── Sync Flush ──────────────────────────────────────────────────────

const COLLECTION_ENDPOINTS: Record<SyncQueueEntry["collection"], string> = {
  inspectionRecords: "/api/inspections",
  nodeConfigSnapshots: "/api/node-configs",
};

/**
 * Drains the syncQueue FIFO, uploading each entry to its collection endpoint.
 *
 * - 5xx or network throw  → stops the batch immediately; entry retryCount++,
 *   remaining entries stay queued (resumable across reconnects).
 * - 409 Conflict          → last-writer-wins with server timestamp authority:
 *   server >= local → discard local and move on; server < local → keep entry
 *   for the next sync cycle.
 * - 4xx (non-409)         → permanent client-side rejection; remove and move on.
 */
export async function flushSyncQueue(): Promise<SyncFlushResult> {
  const entries = await getSyncQueue();
  const result: SyncFlushResult = { attempted: entries.length, succeeded: 0, failed: 0 };

  for (const entry of entries) {
    if (entry.id == null) continue;
    const base = process.env.NEXT_PUBLIC_API_BASE_URL ?? "";
    const url = base + COLLECTION_ENDPOINTS[entry.collection];
    const now = new Date().toISOString();

    try {
      const response = await fetch(url, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: entry.payload,
        keepalive: true,
      });

      if (response.status === 409) {
        const serverData = (await response.json().catch(() => null)) as {
          serverTimestamp?: string;
        } | null;
        const local = JSON.parse(entry.payload) as {
          updatedAt?: string;
          snapshotAt?: string;
        };
        const localTs = new Date(local.updatedAt ?? local.snapshotAt ?? 0).getTime();
        const serverTs = serverData?.serverTimestamp
          ? new Date(serverData.serverTimestamp).getTime()
          : 0;

        if (serverTs >= localTs) {
          await removeSyncEntry(entry.id);
          await upsertSyncMetadata(entry.collection, {
            syncStatus: "idle",
            lastSyncAt: now,
            errorMessage: null,
          });
          result.succeeded++;
        } else {
          await updateSyncEntry(entry.id, {
            retryCount: entry.retryCount + 1,
            lastAttemptAt: now,
          });
          await upsertSyncMetadata(entry.collection, {
            syncStatus: "error",
            errorMessage: "Conflict: local record is newer, queued for retry",
          });
          result.failed++;
          return result;
        }
        continue;
      }

      if (!response.ok && response.status >= 500) {
        await updateSyncEntry(entry.id, {
          retryCount: entry.retryCount + 1,
          lastAttemptAt: now,
        });
        await upsertSyncMetadata(entry.collection, {
          syncStatus: "error",
          errorMessage: `Server error ${response.status}`,
        });
        result.failed++;
        return result;
      }

      await removeSyncEntry(entry.id);
      await upsertSyncMetadata(entry.collection, {
        syncStatus: "idle",
        lastSyncAt: now,
        errorMessage: null,
      });
      result.succeeded++;
    } catch {
      await updateSyncEntry(entry.id, {
        retryCount: entry.retryCount + 1,
        lastAttemptAt: now,
      });
      result.failed++;
      return result;
    }
  }

  return result;
}

// ── Generic Wrappers for useNodeConfig Hook ──────────────────────────

/**
 * Wrapper to match hook signature for saving node configuration
 */
export async function saveToIndexedDB(key: string, data: any): Promise<void> {
  // We use the nodeConfigSnapshots store. The key matches the nodeId.
  await saveNodeConfigSnapshot({
    nodeId: key,
    config: data,
    version: 1,
    snapshotAt: new Date().toISOString()
  });
}

/**
 * Wrapper to match hook signature for loading node configuration
 */
export async function loadFromIndexedDB(key: string): Promise<any | null> {
  const snapshots = await getNodeConfigSnapshots(key);
  if (snapshots.length === 0) return null;
  
  // Sort by snapshot date to get the newest one if multiple exist
  snapshots.sort((a, b) => new Date(b.snapshotAt).getTime() - new Date(a.snapshotAt).getTime());
  return snapshots[0].config;
}

// ── Horizon Cursor Cache ─────────────────────────────────────────────

/**
 * Persists (upserts) the full cursor page list for a given Horizon endpoint.
 * Key format: `horizon/cursors/${accountId}`
 */
export async function saveCursorCache(
  endpoint: string,
  pages: HorizonPageRecord[]
): Promise<void> {
  const db = await getFieldDb();
  if (!db) return;
  await db.put("horizonCursors", {
    endpoint,
    pages,
    updatedAt: new Date().toISOString(),
  });
}

/**
 * Loads the cached cursor list for a given Horizon endpoint.
 * Returns `undefined` when no cache exists.
 */
export async function loadCursorCache(
  endpoint: string
): Promise<SerializedCursorCache | undefined> {
  const db = await getFieldDb();
  if (!db) return undefined;
  return db.get("horizonCursors", endpoint);
}

/**
 * Removes the cursor cache for a given Horizon endpoint.
 * Called when a cursor expires or is deliberately purged.
 */
export async function deleteCursorCache(endpoint: string): Promise<void> {
  const db = await getFieldDb();
  if (!db) return;
  await db.delete("horizonCursors", endpoint);
}

'use client'

import { RefObject, useCallback, useEffect, useLayoutEffect, useMemo, useRef, useState } from 'react'

interface UseVirtualListOptions {
  totalCount: number
  estimatedRowHeight: number
  overscanScreens?: number
  maxRenderedItems?: number
  preserveKey?: string
}

interface VirtualItem {
  index: number
  offsetTop: number
  height: number
}

interface VirtualRange {
  start: number
  end: number
  paddingTop: number
  paddingBottom: number
  totalHeight: number
  virtualItems: VirtualItem[]
}

const savedScrollPositions = new Map<string, number>()

export function useVirtualList<T>(
  items: readonly T[],
  {
    totalCount,
    estimatedRowHeight,
    overscanScreens = 3,
    maxRenderedItems = 100,
    preserveKey,
  }: UseVirtualListOptions,
): VirtualRange & {
  containerRef: RefObject<HTMLDivElement | null>
  topSentinelRef: RefObject<HTMLDivElement | null>
  bottomSentinelRef: RefObject<HTMLDivElement | null>
  visibleItems: readonly T[]
  measureElement: (index: number, element: HTMLElement | null) => void
} {
  const containerRef = useRef<HTMLDivElement | null>(null)
  const topSentinelRef = useRef<HTMLDivElement | null>(null)
  const bottomSentinelRef = useRef<HTMLDivElement | null>(null)
  const heightsRef = useRef(new Map<number, number>())
  const [scrollState, setScrollState] = useState({ scrollTop: 0, viewportHeight: 0 })

  const getHeight = useCallback(
    (index: number) => heightsRef.current.get(index) ?? estimatedRowHeight,
    [estimatedRowHeight],
  )

  const getOffsetTop = useCallback(
    (index: number) => {
      let offset = 0
      for (let i = 0; i < index; i += 1) offset += getHeight(i)
      return offset
    },
    [getHeight],
  )

  const totalHeight = useMemo(() => {
    let measuredDelta = 0
    heightsRef.current.forEach((height) => {
      measuredDelta += height - estimatedRowHeight
    })
    return Math.max(0, totalCount * estimatedRowHeight + measuredDelta)
  }, [estimatedRowHeight, totalCount, scrollState])

  const range = useMemo(() => {
    const { scrollTop, viewportHeight } = scrollState
    const overscanPixels = viewportHeight * overscanScreens
    const requestedStart = Math.max(0, Math.floor((scrollTop - overscanPixels) / estimatedRowHeight))
    const requestedEnd = Math.min(
      totalCount,
      Math.ceil((scrollTop + viewportHeight + overscanPixels) / estimatedRowHeight),
    )
    const visibleCenter = Math.max(0, Math.floor((scrollTop + viewportHeight / 2) / estimatedRowHeight))
    const requestedCount = Math.max(1, requestedEnd - requestedStart)
    const cappedCount = Math.min(maxRenderedItems, requestedCount, totalCount)
    const start = requestedCount > maxRenderedItems
      ? Math.max(0, Math.min(totalCount - cappedCount, visibleCenter - Math.floor(cappedCount / 2)))
      : requestedStart
    const end = Math.min(totalCount, start + cappedCount)
    const paddingTop = getOffsetTop(start)
    const virtualItems = Array.from({ length: end - start }, (_, position) => {
      const index = start + position
      return { index, offsetTop: getOffsetTop(index), height: getHeight(index) }
    })
    const renderedHeight = virtualItems.reduce((sum, item) => sum + item.height, 0)

    return {
      start,
      end,
      paddingTop,
      paddingBottom: Math.max(0, totalHeight - paddingTop - renderedHeight),
      totalHeight,
      virtualItems,
    }
  }, [estimatedRowHeight, getHeight, getOffsetTop, maxRenderedItems, overscanScreens, scrollState, totalCount, totalHeight])

  const updateScrollState = useCallback(() => {
    const container = containerRef.current
    if (!container) return
    const next = { scrollTop: container.scrollTop, viewportHeight: container.clientHeight }
    if (preserveKey) savedScrollPositions.set(preserveKey, next.scrollTop)
    setScrollState((previous) => (
      previous.scrollTop === next.scrollTop && previous.viewportHeight === next.viewportHeight ? previous : next
    ))
  }, [preserveKey])

  useLayoutEffect(() => {
    const container = containerRef.current
    if (!container) return
    if (preserveKey) container.scrollTop = savedScrollPositions.get(preserveKey) ?? container.scrollTop
    updateScrollState()
  }, [preserveKey, updateScrollState])

  useEffect(() => {
    const container = containerRef.current
    if (!container) return
    const observer = new IntersectionObserver(updateScrollState, { root: container })
    if (topSentinelRef.current) observer.observe(topSentinelRef.current)
    if (bottomSentinelRef.current) observer.observe(bottomSentinelRef.current)
    container.addEventListener('scroll', updateScrollState, { passive: true })
    const resizeObserver = new ResizeObserver(updateScrollState)
    resizeObserver.observe(container)
    return () => {
      container.removeEventListener('scroll', updateScrollState)
      observer.disconnect()
      resizeObserver.disconnect()
    }
  }, [updateScrollState])

  const measureElement = useCallback((index: number, element: HTMLElement | null) => {
    if (!element) return
    const nextHeight = element.getBoundingClientRect().height
    if (nextHeight > 0 && heightsRef.current.get(index) !== nextHeight) {
      heightsRef.current.set(index, nextHeight)
      updateScrollState()
    }
  }, [updateScrollState])

  return {
    ...range,
    containerRef,
    topSentinelRef,
    bottomSentinelRef,
    visibleItems: items.slice(range.start, range.end),
    measureElement,
  }
}

import React, { useState, useEffect } from 'react';
import { useBluetoothProvisioning } from '../../hooks/useBluetoothProvisioning';
import { BLEScanSheet } from '../../components/provisioning/BLEScanSheet';
import { ConfigPayloadEditor } from '../../components/provisioning/ConfigPayloadEditor';
import { decodeResponse } from '../../lib/bluetooth/provisioningProtocol';

type Step = 'scan' | 'configure' | 'verify';

export default function ProvisioningConsole() {
  const [step, setStep] = useState<Step>('scan');
  const [isScanOpen, setIsScanOpen] = useState(false);
  const [verificationResult, setVerificationResult] = useState<{ success: boolean; message: string } | null>(null);
  
  const { 
    device, 
    writeChar, 
    notifyChar, 
    isConnected, 
    error, 
    connect, 
    disconnect 
  } = useBluetoothProvisioning();

    useEffect(() => {
      if (isConnected && notifyChar) {
       const handleNotification = async (event: Event) => {
         const value = (event.target as any as BluetoothRemoteGATTCharacteristic).value;
         if (value) {
           const result = decodeResponse(value);
           setVerificationResult(result);
         }
       };

        const startNotifications = async () => {
          try {
            await notifyChar.startNotifications();
            notifyChar.addEventListener('characteristicvaluechanged', handleNotification);
          } catch {
            console.error('Failed to start notifications');
          }
        };

        startNotifications();

        return () => {
          notifyChar.removeEventListener('characteristicvaluechanged', handleNotification);
          notifyChar.stopNotifications().catch(() => {});
        };
      }
    }, [isConnected, notifyChar]);

  const handleConnect = async () => {
    try {
      await connect();
      setIsScanOpen(false);
      setStep('configure');
    } catch {
      // error state in hook handles this
    }
  };

  const handleWriteSuccess = () => {
    setVerificationResult(null);
    setStep('verify');
  };

  const handleWriteError = (err: string) => {
    alert(`Error: ${err}`);
  };

  return (
    <div className="max-w-4xl mx-auto p-6">
      <header className="mb-8 flex justify-between items-center">
        <div>
          <h1 className="text-3xl font-bold text-foreground">Provisioning Console</h1>
          <p className="text-muted">Configure and provision new BLE sensor nodes</p>
        </div>
        {isConnected && (
          <button 
            onClick={disconnect} 
            className="px-4 py-2 bg-red-100 text-red-600 rounded-lg hover:bg-red-200 transition-colors"
          >
            Disconnect
          </button>
        )}
      </header>

      <div className="flex justify-between mb-8 relative">
        {['scan', 'configure', 'verify'].map((s, idx) => (
          <div key={s} className="flex flex-col items-center z-10">
            <div className={`w-10 h-10 rounded-full flex items-center justify-center font-bold ${
              step === s ? 'bg-primary text-primary-text' : 'bg-surface-alt text-muted'
            }`}>
              {idx + 1}
            </div>
            <span className="text-xs mt-2 capitalize">{s}</span>
          </div>
        ))}
        <div className="absolute top-5 left-0 w-full h-0.5 bg-surface-alt z-0"></div>
        <div 
          className="absolute top-5 left-0 h-0.5 bg-primary transition-all duration-300 z-0"
          style={{ width: step === 'scan' ? '0%' : step === 'configure' ? '33.3%' : '66.6%' }}
        ></div>
      </div>

      <main className="bg-surface border rounded-xl p-6 shadow-sm min-h-100">
        {step === 'scan' && (
          <div className="flex flex-col items-center justify-center h-full py-20">
            <div className="text-center mb-8">
              <div className="w-20 h-20 bg-primary/10 text-primary rounded-full flex items-center justify-center mx-auto mb-4">
                <svg className="w-10 h-10" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8.111 16.404a5.5 5.5 0 017.778 0M12 20h.01m-7.08-7.071a9.05 9.05 0 0112.728 0m-15.557-3.636a12 12 0 0116.666 0" />
                </svg>
              </div>
              <h2 className="text-xl font-semibold">Ready to Scan</h2>
              <p className="text-muted">Click the button below to search for BLE devices</p>
            </div>
            <button
              onClick={() => setIsScanOpen(true)}
              className="px-8 py-3 bg-primary text-primary-text rounded-lg font-medium hover:bg-primary-hover transition-colors shadow-lg shadow-blue-200"
            >
              Open Device Scanner
            </button>
          </div>
        )}

        {step === 'configure' && (
          <div className="max-w-2xl mx-auto">
            <h2 className="text-xl font-semibold mb-4">Configuration</h2>
            <ConfigPayloadEditor 
              writeCharacteristic={writeChar} 
              onWriteSuccess={handleWriteSuccess}
              onWriteError={handleWriteError}
            />
            <button 
              onClick={() => setStep('scan')}
              className="mt-4 text-sm text-muted hover:text-foreground"
            >
              &larr; Back to scan
            </button>
          </div>
        )}

        {step === 'verify' && (
          <div className="flex flex-col items-center justify-center py-20">
            <h2 className="text-xl font-semibold mb-6">Verifying Handshake...</h2>
            
            {!verificationResult ? (
              <div className="flex flex-col items-center">
                <div className="w-12 h-12 border-4 border-primary border-t-transparent rounded-full animate-spin mb-4"></div>
                <p className="text-muted">Waiting for response from node</p>
              </div>
            ) : (
              <div className={`p-8 rounded-2xl text-center border-2 ${
                verificationResult.success ? 'bg-green-50 border-green-200' : 'bg-red-50 border-red-200'
              }`}>
                <div className={`w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4 ${
                  verificationResult.success ? 'bg-green-100 text-green-600' : 'bg-red-100 text-red-600'
                }`}>
                  {verificationResult.success ? (
                    <svg className="w-8 h-8" fill="currentColor" viewBox="0 0 20 20">
                      <path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd" />
                    </svg>
                  ) : (
                    <svg className="w-8 h-8" fill="currentColor" viewBox="0 0 20 20">
                      <path fillRule="evenodd" d="M4.293 4.293a1 1 0 011.414 0L10 8.586l4.293-4.293a1 1 0 111.414 1.414L11.414 10l4.293 4.293a1 1 0 01-1.414 1.414L10 11.414l-4.293 4.293a1 1 0 01-1.414-1.414L8.586 10 4.293 5.707a1 1 0 010-1.414z" clipRule="evenodd" />
                    </svg>
                  )}
                </div>
                <h3 className={`text-lg font-bold ${verificationResult.success ? 'text-green-800' : 'text-red-800'}`}>
                  {verificationResult.success ? 'Provisioning Successful!' : 'Provisioning Failed'}
                </h3>
                <p className="text-muted mt-2">{verificationResult.message}</p>
                <button 
                  onClick={() => {
                    setVerificationResult(null);
                    setStep('configure');
                  }}
                  className="mt-6 px-4 py-2 bg-surface border rounded-lg hover:bg-surface-alt transition-colors"
                >
                  Retry Configuration
                </button>
              </div>
            )}
          </div>
        )}
      </main>

      <BLEScanSheet 
        isOpen={isScanOpen}
        onClose={() => setIsScanOpen(false)}
        onScan={handleConnect}
        device={device}
        isConnected={isConnected}
        error={error}
      />
    </div>
  );
}

